ForeverPathfinderTrees = {
  druid = { { "Balance", { { "Improved Wrath", "spell_nature_abolishmagic", 1, 2, 5, "", "Reduces the cast time of your Wrath spell by 0.5 sec and its Mana cost by 50%." }, { "Genesis", "spell_arcane_arcane03", 1, 3, 5, "", "Increases the periodic damage and healing done by your spells and abilities by 10%." }, { "Moonglow", "spell_nature_sentinal", 2, 1, 3, "", "Reduces the Mana cost of your damaging spells by 25%." }, { "Improved Moonfire", "spell_nature_starfall", 2, 2, 2, "", "Increases the damage and critical strike chance of your Moonfire spell by 10%." }, { "Nature's Majesty", "inv_staff_01", 2, 3, 2, "", "Increases your critical strike chance with spells and melee attacks by 4%." }, { "Nature's Reach", "spell_nature_naturetouchgrow", 2, 4, 2, "", "Increases the range of your offensive Balance spells by 20% and improves your chance to hit by 4%." }, { "Improved Entangling Roots", "spell_nature_stranglevines", 3, 1, 3, "", "Increases the damage done by your Entangling Roots spell by 75%, and its victims can take up to 75% more damage without interrupting the effect." }, { "Nature's Splendor", "spell_nature_natureresistancetotem", 3, 3, 1, "Nature's Majesty", "Increases the duration of your Moonfire and Rejuvenation spells by 3 sec, your Regrowth spell by 6 sec, and your Insect Swarm spell by 2 sec." }, { "Insect Swarm", "spell_nature_insectswarm", 4, 1, 1, "", "The enemy target is swarmed by insects, decreasing their chance to hit with attacks by 2% and causing 48 Nature damage over 12 sec." }, { "Vengeance", "spell_nature_purge", 4, 2, 5, "Improved Moonfire", "Increases the critical strike damage bonus of your Arcane and Nature spells by 100%." }, { "Improved Starfire", "spell_arcane_starfire", 4, 3, 5, "", "Reduces the cast time of Starfire by 0.5 sec and Starfire has a 15% chance to stun its target for 3 sec." }, { "Overgrowth", "inv_misc_herb_15", 5, 1, 2, "", "Increases the maximum number of targets you may have affected by Entangling Roots by 2." }, { "Nature's Grace", "spell_nature_naturesblessing", 5, 2, 1, "", "All non-periodic spell criticals grace you with a blessing of nature, increasing your spellcasting speed and reducing your global cooldown by 10% for 3 sec." }, { "Eclipse", "ability_druid_eclipse", 5, 3, 3, "", "Your Wrath spell reduces the cast time of your next 2 Starfire spells by 0.50 sec. Stores up to 4 charges. Lasts 15 sec." }, { "Moonfury", "spell_nature_moonglow", 6, 2, 5, "", "Increases the damage done by your Arcane and Nature spells by 10%." }, { "Moonkin Form", "spell_nature_forceofnature", 7, 2, 1, "", "Shapeshift into Moonkin Form, increasing Omen of Clarity's chance to trigger by 100%, Armor contribution from items by 360%, and all party or raid members within 45 yards have their Critical Strike chance increased by 3%. Also protects the caster from Polymorph effects and prevents the use of healing spells.\n\nThe act of shapeshifting frees the caster of Polymorph and Movement Impairing effects." } } }, { "Feral Combat", { { "Ferocity", "ability_hunter_pet_hyena", 1, 2, 5, "", "Reduces the cost of your Maul, Primal Bite, Swipe, Claw, and Rake abilities by 5 Rage or Energy." }, { "Furor", "spell_holy_blessingofstamina", 1, 3, 5, "", "Gives you a 100% chance to gain 10 Rage when shapeshifting into Bear Form or Dire Bear Form. Shapeshifting into Cat Form restores 100% of the Energy you had when last in Cat Form, plus 10 Energy per second spent outside Bear Form or Dire Bear Form, up to 100 Energy." }, { "Feral Swiftness", "spell_nature_spiritwolf", 2, 1, 2, "", "Increases your movement speed while in Cat Form by 30%, and increases your chance to Dodge by 4%." }, { "Feral Instinct", "ability_ambush", 2, 2, 3, "", "Increases damage done by your Swipe ability by 30% and reduces the chance enemies have to detect you while Prowling as if you were 3 levels higher." }, { "Brutal Impact", "ability_druid_bash", 2, 3, 2, "", "Increases the stun duration of your Bash and Pounce abilities by 1 sec and reduces the cooldown of Bash by 30 sec." }, { "Thick Hide", "inv_misc_pelt_bear_03", 2, 4, 3, "", "While in Bear Form, Cat Form, Dire Bear Form, or Moonkin Form, you gain 180 additional base Armor per level and another 2.00 base Armor for each point of defense skill beyond five times your level. This amount can be further increased by multipliers from those forms." }, { "Shredding Attacks", "spell_shadow_vampiricaura", 3, 1, 3, "", "Reduces the Energy cost of your Shred ability by 18 and reduces the Rage cost of your Lacerate ability by 3." }, { "Savage Fury", "ability_druid_ravage", 3, 2, 2, "", "Increases the damage caused by your Claw, Rake, Shred, Maul, and Swipe abilities by 10%." }, { "Feral Charge", "ability_hunter_pet_bear", 3, 3, 1, "", "Requires Bear Form, Dire Bear Form\nCharge an enemy, immobilizing them and interrupting any spell they are casting for 4 sec.\n\nLeap behind an enemy." }, { "Sharpened Claws", "inv_misc_monsterclaw_04", 3, 4, 2, "", "Increases your critical strike chance while in Bear Form, Dire Bear Form, or Cat Form by 6%." }, { "Predatory Strikes", "ability_hunter_pet_cat", 4, 1, 3, "", "Increases your melee Attack Power in Cat Form, Bear Form, and Dire Bear Form by 150% of your level." }, { "Lacerate", "ability_druid_lacerate", 4, 2, 1, "Savage Fury", "Lacerates the enemy target, making them bleed for 20 damage over 15 sec plus 10% weapon damage per existing application of Lacerate on the target. Causes a high amount of threat. This effect stacks up to 5 times on the same target." }, { "Predatory Discipline", "spell_druid_savagery", 4, 3, 1, "", "Your Ferocious Bite ability no longer converts extra Energy into damage, but still deals extra damage based on your excess Energy." }, { "Blood Frenzy", "ability_ghoulfrenzy", 4, 4, 2, "Sharpened Claws", "Gives you a 100% chance to gain an additional 5 Rage any time you get a critical strike while in Bear Form or Dire Bear Form. In addition, your non-periodic critical strikes from Cat Form abilities that generate Combo Points have a 100% chance to add an additional Combo Point." }, { "Leader of the Pack", "spell_nature_unyeildingstamina", 5, 2, 1, "", "While in Cat Form, Bear Form, or Dire Bear Form, the Leader of the Pack increases the Critical Strike chance of all party or raid members within 45 yards by 3%." }, { "Natural Instinct", "ability_druid_predatoryinstincts", 5, 4, 2, "", "Increases the critical strike damage bonus of your melee abilities by 20% and increases your spell healing by 25% of your Intellect." }, { "Rend and Tear", "ability_druid_primalagression", 6, 1, 5, "Predatory Strikes", "Increases damage done by your melee abilities on Bleeding targets by 15%." }, { "Natural Reaction", "ability_bullrush", 6, 4, 5, "", "Increases your dodge chance by 5%, and gives you a 100% chance to gain 5 Rage each time you dodge." }, { "Primal Bite", "ability_racial_cannibalize", 7, 2, 1, "Leader of the Pack", "Bite the target, dealing 100% normal damage plus 42 and generating a high amount of threat." }, { "Shifting Power", "spell_druid_displacement", 7, 3, 1, "Predatory Discipline", "Instantly convert 55% of base Mana into 40 Energy. Shifting Power's cost is reduced by effects that reduce the cost of Shapeshifting." } } }, { "Restoration", { { "Nature's Focus", "spell_nature_healingwavegreater", 1, 2, 5, "", "Gives your Arcane and Nature spells a 70% chance to not lose casting time when you take damage." }, { "Heart of the Wild", "spell_holy_blessingofagility", 1, 3, 5, "", "Increases your Intellect by 10%. In addition, while in Bear Form or Dire Bear Form your Stamina is increased by 20% and while in Cat Form your Strength is increased by 10%." }, { "Naturalist", "spell_nature_healingtouch", 2, 1, 5, "", "Reduces the cast time of your Healing Touch and Wild Growth spells by 0.5 sec and increases all damage you deal by 10%." }, { "Reflection", "spell_frost_windwalkon", 2, 2, 3, "", "Allows 50% of your Mana regeneration to continue while casting." }, { "Natural Shapeshifter", "spell_nature_wispsplode", 2, 3, 3, "", "Reduces the mana cost of all shapeshifting by 30%." }, { "Subtlety", "ability_eyeoftheowl", 3, 2, 3, "", "Reduces the threat generated by your Nature and Arcane spells by 30%." }, { "Gift of Nature", "spell_nature_protectionformnature", 3, 3, 5, "", "Increases the effect of all your healing spells by 10%." }, { "Bloom", "inv_misc_herb_felblossom", 3, 4, 1, "", "When your Rejuvenation or Regrowth spell expires due to its duration, the target is instantly healed for an amount equal to 100% of your Spirit. If either spell expires due to being dispelled, the target is healed for 50% of your Spirit instead." }, { "Tranquil Spirit", "spell_holy_elunesgrace", 4, 2, 5, "", "Reduces the mana cost of your Healing Touch and Tranquility spells by 10%." }, { "Improved Rejuvenation", "spell_nature_rejuvenation", 4, 3, 3, "", "Increases the effect of your Rejuvenation spell by 15%." }, { "Swiftmend", "inv_relics_idolofrejuvenation", 4, 4, 1, "", "Instantly heals a target with your active Rejuvenation or Regrowth effect for an amount equal to the full duration of the periodic effect." }, { "Nature's Swiftness", "spell_nature_ravenform", 5, 1, 1, "Naturalist", "When activated, your next Nature spell becomes an instant cast spell." }, { "Living Spirit", "spell_nature_giftofthewaterspirit", 5, 2, 3, "", "Increases your Spirit by 15%." }, { "Improved Tranquility", "spell_nature_tranquility", 5, 4, 2, "", "Reduces threat caused by Tranquility by 100% and its cooldown by 60%." }, { "Improved Regrowth", "spell_nature_resistnature", 6, 3, 5, "Improved Rejuvenation", "Increases the critical effect chance of your Regrowth spell by 50%." }, { "Wild Growth", "ability_druid_flourish", 7, 2, 1, "Living Spirit", "Heals the target and their party for 336 over 7 sec. Party members must be within 43.5 yards of target. The amount healed is applied quickly at first, and slows down as Wild Growth reaches its full duration." } } } },
  hunter = { { "Beast Mastery", { { "Deadly Aspects", "spell_nature_ravenform", 1, 2, 5, "", "While Aspect of the Hawk is active, Auto Shot has a 10% chance of increasing ranged attack speed by 30% for 12 sec. While Aspect of the Beast is active, all melee auto attacks have a 10% chance of increasing melee attack speed by 30% for 12 sec." }, { "Endurance Training", "spell_nature_reincarnation", 1, 3, 5, "", "Increases the Health and Armor of your pets by 15%." }, { "Focused Fire", "inv_weapon_crossbow_10", 2, 1, 2, "", "Increases all damage you and your pet deal by 2% while your pet is active." }, { "Improved Aspect of the Monkey", "ability_hunter_aspectofthemonkey", 2, 2, 3, "", "Increases the Dodge bonus of your Aspect of the Monkey by 6%. Additionally, your pet gains 50% of the effect of your Aspect of the Monkey ability." }, { "Improved Revive Pet", "ability_hunter_beastsoothe", 2, 3, 2, "", "Revive Pet's casting time is reduced by 6 sec, mana cost is reduced by 40%, and increases the health your pet returns with by an additional 30%." }, { "Pathfinding", "ability_mount_jungletiger", 3, 1, 2, "", "Increases the speed bonus of your Aspect of the Cheetah and Aspect of the Pack by 6%." }, { "Bestial Swiftness", "ability_druid_dash", 3, 2, 1, "", "Increases the movement speed of your pets by 30%." }, { "Unleashed Fury", "ability_bullrush", 3, 3, 5, "", "Increases the damage done by your pets and hawks by 15%." }, { "Improved Mend Pet", "ability_hunter_mendpet", 4, 1, 2, "", "Gives your Mend Pet spell a 50% chance of cleansing 1 Curse, Disease, Magic, or Poison effect from your pet each time it heals and reduces the Mana cost by 20%." }, { "Ferocity", "inv_misc_monsterclaw_04", 4, 3, 5, "", "Increases the critical strike chance of your pets and hawks by 10%." }, { "Summon Hawk", "ability_hunter_animalhandler", 4, 4, 1, "", "Command a hawk to dive-bomb your targeted enemy, dealing 34 Physical damage and continuing its assault for 18 sec. Only 2 hawks can be active at once. Summon Hawk shares its cooldown with Arcane Shot." }, { "Spirit Bond", "ability_druid_demoralizingroar", 5, 1, 2, "", "While your pet is active, you and your pet will regenerate 1% of total health every 5 sec." }, { "Intimidation", "ability_devour", 5, 2, 1, "Bestial Swiftness", "Command your pet to Stun the target for 3 sec on its next successful attack, which also gains 100% increased critical strike chance. Generates high threat." }, { "Bestial Discipline", "spell_nature_abolishmagic", 5, 4, 2, "", "Increases the Focus regeneration of your pets by 20% and allows 50% of your Mana regeneration to continue while casting." }, { "Frenzy", "inv_misc_monsterclaw_03", 6, 3, 5, "Ferocity", "Gives your pet a 100% chance to gain a 30% attack speed increase for 8 sec after dealing a critical strike." }, { "Bestial Wrath", "ability_druid_ferociousbite", 7, 2, 1, "Intimidation", "Send your pet into a rage causing 50% additional damage for 18 sec. While enraged, the beast does not feel pity or remorse or fear and it cannot be stopped unless killed." } } }, { "Marksmanship", { { "Hawk Eye", "ability_townwatch", 1, 1, 3, "", "Increases the range of your ranged weapons by 6 yards." }, { "Improved Concussive Shot", "spell_frost_stun", 1, 2, 5, "", "Gives your Concussive Shot a 20% chance to stun the target for 3 sec." }, { "Lethal Attacks", "ability_searingarrow", 1, 3, 5, "", "Increases your critical strike chance with all attacks by 5%." }, { "Improved Stings", "ability_hunter_quickshot", 2, 1, 3, "", "Increases the damage of your Serpent Sting ability by 20%, reduces the cooldown of your Viper Sting ability by 6 sec, and increases the duration of your Scorpid Sting ability by 45 sec." }, { "Efficiency", "spell_frost_wizardmark", 2, 2, 5, "", "Reduces the Mana cost of your Shots, Stings, and melee abilities by 15%." }, { "Careful Aim", "ability_hunter_zenarchery", 2, 3, 5, "", "Increases your Attack Power by 100% of your Intellect." }, { "Rapid Killing", "ability_hunter_rapidkilling", 3, 1, 2, "", "Reduces the cooldown on your Rapid Fire ability by 2 min. In addition, when you kill a non-trivial enemy or it dies while afflicted by your Serpent Sting, you gain Rapid Killing, increasing the damage of your next Shot ability within 20 sec by 20%." }, { "Improved Arcane Shot", "ability_impalingbolt", 3, 2, 5, "", "Reduces the cooldown of your Arcane Shot by 1.5 sec. Does not affect the cooldown of abilities which share a cooldown with Arcane Shot." }, { "Lone Wolf", "ability_mount_whitedirewolf", 3, 4, 1, "", "You deal 20% increased damage with all attacks while you do not have an active pet." }, { "Trueshot Aura", "ability_trueshot", 4, 2, 1, "", "Increases the Ranged Attack Power of party or raid members within 45 yds by 20." }, { "Mortal Shots", "ability_piercedamage", 4, 3, 5, "Careful Aim", "Increases the critical strike damage bonus on all ranged abilities by 30%." }, { "Rapid Recuperation", "ability_hunter_rapidregeneration", 5, 1, 2, "Rapid Killing", "Afflicting a target with Serpent Sting allows 50% of your Mana Regeneration to continue while casting for 15 sec, increased to 100% when Rapid Killing is consumed." }, { "Barrage", "ability_upgrademoonglaive", 5, 3, 3, "", "Increases the damage done by your Multi-Shot, Aimed Shot, and Volley abilities by 15%." }, { "Scatter Shot", "ability_golemstormbolt", 5, 4, 1, "", "A short-range shot that deals 50% weapon damage and disorients the target for 4 sec. Any damage caused will remove the effect. Turns off your attack when used." }, { "Ranged Weapon Specialization", "inv_weapon_rifle_06", 6, 3, 5, "", "Increases the damage you deal with ranged weapons by 5%." }, { "Sniper Shot", "hunter_pvp_snipershot", 7, 2, 1, "Trueshot Aura", "A long-range shot that deals ranged damage plus 320 and increases the range of your next 3 Shots by 10 yards for 10 sec." } } }, { "Survival", { { "Improved Tracking", "inv_misc_head_dragon_black", 1, 2, 5, "", "While tracking Beasts, Demons, Dragonkin, Elementals, Giants, Humanoids, or Undead, all damage you deal to the tracked creature type is increased by 5%." }, { "Deflection", "ability_parry", 1, 3, 5, "", "Increases your Parry chance by 5%." }, { "Entrapment", "spell_nature_stranglevines", 2, 1, 5, "", "When your traps are triggered, all affected targets are Entrapped, preventing them from moving for 5 sec." }, { "Savage Strikes", "ability_racial_bloodrage", 2, 2, 2, "", "Increases the critical strike chance of all your melee abilities by 4%." }, { "Survivalist", "spell_shadow_twilight", 2, 3, 5, "", "Increases your total Health by 10%." }, { "Improved Wing Clip", "ability_rogue_trip", 2, 4, 3, "", "Gives your Wing Clip ability a 20% chance to immobilize the target for 5 sec." }, { "Clever Traps", "spell_nature_timestop", 3, 1, 2, "", "Increases the duration of Freezing and Frost trap effects by 30% and the damage of Immolation and Explosive trap effects by 30%." }, { "Surefooted", "ability_kick", 3, 2, 3, "", "Increases your hit chance by 3% and reduces the duration of movement impairing effects on you by 30%." }, { "Deterrence", "ability_whirlwind", 3, 3, 1, "", "When activated, increases your Dodge and Parry chance by 25% for 10 sec." }, { "Survival Tactics", "ability_ensnare", 4, 1, 2, "", "Increases your chance to hit with your Trap and Feign Death abilities by 10%." }, { "Predator's Edge", "ability_dualwield", 4, 2, 5, "", "Increases your melee ability critical strike damage by 30% and your Off Hand weapon damage by 50%." }, { "Counterattack", "ability_warrior_challange", 4, 3, 1, "Deterrence", "A strike that becomes active after parrying an opponent's attack. This attack deals 50% weapon damage plus 26 and immobilizes the target for 5 sec. Counterattack cannot be blocked, dodged, or parried." }, { "Resourcefulness", "ability_hunter_resourcefulness", 5, 1, 2, "", "Reduces the Mana cost of your Trap and melee abilities by 60%, and grants your melee and ranged ability Critical Strikes a 100% chance to allow 50% of your Mana Regeneration to continue while casting for 30 sec." }, { "Expose Prey", "ability_hunter_swiftstrike", 5, 2, 2, "", "Grants your melee and ranged attacks against enemies afflicted by Hunter's Mark a 10% chance to allow an activation of Mongoose Bite. Lasts 10 sec." }, { "Survivalist's Discipline", "ability_hunter_mastertactitian", 5, 3, 2, "", "Reduces the cooldown of your Trap and Deterrence abilities by 40%." }, { "Strider Kick", "ability_hunter_pet_tallstrider", 5, 4, 1, "", "A powerful kick that deals 100% melee weapon damage and increases movement speed by 30% for 3 sec." }, { "Lightning Reflexes", "spell_nature_invisibilty", 6, 3, 5, "", "Increases your Agility by 15%." }, { "Lacerating Strikes", "ability_gouge", 7, 2, 1, "Expose Prey", "Your Mongoose Bite also causes the target to Bleed for damage equal to 40% of the damage done by Mongoose Bite over 21 sec" } } } },
  mage = { { "Arcane", { { "Wand Specialization", "inv_wand_01", 1, 1, 2, "", "Increases your damage with Wands by 25%." }, { "Improved Channeling", "spell_nature_starfall", 1, 2, 5, "", "Gives your Arcane Missiles spell a 100% chance and your Arcane Blast and Arcane Wrath spells a 70% chance to not lose casting time when you take damage." }, { "Arcane Resilience", "spell_arcane_arcaneresilience", 1, 3, 3, "", "Increases your Armor by an amount equal to 75% of your Intellect." }, { "Arcane Subtlety", "spell_holy_dispelmagic", 2, 1, 2, "", "Reduces your target's resistance to all your spells by 15 and reduces the threat caused by your Arcane spells by 30%." }, { "Magic Absorption", "spell_nature_astralrecalgroup", 2, 2, 2, "", "Increases all your resistances by 10 and causes all spells you fully resist to restore 2% of your total mana. Cannot trigger more often than 1 time per sec." }, { "Arcane Concentration", "spell_shadow_manaburn", 2, 3, 5, "", "Gives you a 10% chance of entering a Clearcasting state after any damage spell hits a target. The Clearcasting state reduces the mana cost of your next damage spell by 100%." }, { "Missile Barrage", "ability_mage_missilebarrage", 2, 4, 2, "", "Gives your Arcane Blast spell a 40% chance, and your Arcane Wrath, Fireball, Frostbolt, and Frostfire Bolt spells a 20% chance to reduce the channeled duration of your next Arcane Missiles spell by 50%, reduce the Mana cost by 100%, and missiles fire every 0.5 sec." }, { "Arcane Geometry", "inv_ability_mage_radiantspark", 3, 1, 2, "", "Increases the range of your Arcane spells by 6 yards." }, { "Arcane Impact", "spell_nature_wispsplode", 3, 2, 3, "", "Increases the critical strike chance of your Arcane spells by 6%." }, { "Arcane Blast", "spell_arcane_blast", 3, 4, 1, "", "Blasts the target with energy, dealing 34 to 38 Arcane damage. Each time you cast Arcane Blast, you gain 12% of your Intellect as Spell Damage and the mana cost of Arcane Blast is increased by 100%. Effect stacks up to 4 times and lasts 18 sec from time of initial application." }, { "Arcane Shielding", "spell_shadow_detectlesserinvisibility", 4, 1, 2, "", "Decreases the Mana lost per point of damage taken when your Mana Shield spell is active by 33% and increases the resistances granted by your Mage Armor spell by 50%." }, { "Improved Counterspell", "spell_frost_iceshock", 4, 2, 2, "", "Your Counterspell also Silences the target for 4 sec." }, { "Arcane Meditation", "spell_shadow_siphonmana", 4, 3, 3, "Arcane Concentration", "Allows 50% of your Mana regeneration to continue while casting." }, { "Arcane Wrath", "ability_mage_netherwindpresence", 4, 4, 1, "Arcane Blast", "Launches a projectile of pure Arcane energy at the enemy target, causing 122 to 146 Arcane damage. This spell gains additional Spell Damage equal to 5% of your maximum Mana." }, { "Presence of Mind", "spell_nature_enchantarmor", 5, 2, 1, "", "When activated, your next Mage spell with a casting time less than 10 sec becomes an instant cast spell." }, { "Arcane Mind", "spell_shadow_charm", 5, 3, 5, "", "Increases your Intellect by 10% and increases the critical strike damage bonus of your Arcane spells by 100%." }, { "Arcane Instability", "spell_shadow_teleport", 6, 3, 3, "", "Increases the damage done by your spells by 3% and your critical strike chance by 3%." }, { "Arcane Power", "spell_nature_lightning", 7, 2, 1, "Presence of Mind", "For the next 15 sec, your spells deal 30% more damage while costing 30% more mana to cast." } } }, { "Fire", { { "Incineration", "spell_fire_flameshock", 1, 2, 5, "", "Increases the critical strike chance of your Fire Blast, Ice Lance, Arcane Blast, and Scorch spells by 10%." }, { "Accelerant", "spell_fire_flamebolt", 1, 3, 5, "", "Reduces the casting time of your Fireball, Frostfire Bolt, and Arcane Wrath spells by 0.5 sec." }, { "Ignite", "spell_fire_incinerate", 2, 1, 5, "", "Your critical strikes from Fire damage spells cause the target to burn for an additional 40% of your spell's damage over 4 sec." }, { "Flame Throwing", "spell_fire_flare", 2, 2, 2, "", "Increases the range of your Fire spells by 6 yards." }, { "Impact", "spell_fire_meteorstorm", 2, 3, 3, "", "Gives your Fire spells a 10% chance to stun the target for 2 sec." }, { "Burning Soul", "spell_fire_fire", 3, 1, 3, "", "Gives your Fire spells a 70% chance to not lose casting time when you take damage and reduces the threat caused by your Fire spells by 30%." }, { "Improved Flamestrike", "spell_fire_selfdestruct", 3, 2, 3, "", "Increases the critical strike chance of your Flamestrike spell by 15%." }, { "Pyroblast", "spell_fire_fireball02", 3, 3, 1, "", "Hurls an immense fiery boulder that causes 101 to 131 Fire damage and an additional 44 Fire damage over 12 sec." }, { "Improved Fire Blast", "spell_fire_lavaspawn", 3, 4, 2, "", "Reduces the cooldown of your Fire Blast spell by 2 sec and increases its range by 15 yards." }, { "Improved Scorch", "spell_fire_soulburn", 4, 1, 3, "", "Your Scorch spell has a 100% chance to cause your target to be vulnerable to Fire damage. This vulnerability increases all Fire damage you deal to your target by 3% and lasts 30 sec, stacking up to 5 times." }, { "Improved Fire Ward", "spell_fire_firearmor", 4, 2, 2, "", "Causes your Fire Ward to have a 20% chance to reflect Fire spells while active." }, { "Heating Up", "spell_fire_firebolt", 4, 3, 1, "Pyroblast", "Non-periodic critical strikes with Fireball, Frostfire Bolt, Fire Blast, and Scorch reduce the cast time of your next Pyroblast cast within 20 sec by 25%, stacking up to 3 times. Fire Blast grants an additional stack every time it deals damage." }, { "Master of Elements", "spell_fire_masterofelements", 4, 4, 3, "", "Your Fire and Frost critical strikes will refund 30% of their base mana cost." }, { "Critical Mass", "spell_nature_wispheal", 5, 2, 3, "", "Increases the critical strike chance of your Fire spells by 6%." }, { "Blast Wave", "spell_holy_excorcism_02", 5, 3, 1, "", "A wave of flame radiates outward from the caster, damaging all enemies caught within the blast for 154 to 184 Fire damage, and Dazing them for 50% reduced movement speed for 6 sec." }, { "Fire Power", "spell_fire_immolation", 6, 3, 3, "", "Increases the damage done by your Fire spells by 3% per your Fire effects on the target, up to a maximum increase of 12%. Effects which mix multiple schools of magic do not qualify." }, { "Combustion", "spell_fire_sealoffire", 7, 2, 1, "Critical Mass", "When activated, this spell causes each of your Fire damage spell hits to increase your critical strike chance with Fire damage spells by 10%. This effect lasts until you have caused 3 non-periodic critical strikes with Fire spells." } } }, { "Frost", { { "Frost Warding", "spell_frost_frostward", 1, 1, 2, "", "Increases the Armor and resistances granted by your Frost Armor and Ice Armor spells by 30%, gives your Frost Ward a 20% chance to negate the warded damage spell, and increases the amount absorbed by your Ice Barrier and Frost Ward by 20%." }, { "Improved Frostbolt", "spell_frost_frostbolt02", 1, 2, 5, "", "Reduces the casting time of your Frostbolt spell by 0.5 sec." }, { "Precision", "spell_ice_magicdamage", 1, 3, 3, "", "Improves your chance to hit with all spells by 6%." }, { "Ice Shards", "spell_frost_iceshard", 2, 1, 5, "", "Increases the critical strike damage bonus of your Frost spells by 100%." }, { "Frostbite", "spell_frost_frostarmor", 2, 2, 3, "", "Gives your Chill effects a 15% chance to Freeze the target for 5 sec." }, { "Improved Frost Nova", "spell_frost_freezingbreath", 2, 3, 2, "", "Reduces the cooldown of your Frost Nova spell by 4 sec." }, { "Permafrost", "spell_frost_wisp", 2, 4, 3, "", "Increases the duration of your Chill effects by 33% and reduces the target's speed by an additional 10%." }, { "Frost Channeling", "spell_frost_stun", 3, 1, 3, "", "Reduces the mana cost of your Frost spells by 15% and reduces the threat caused by your Frost spells by 30%." }, { "Improved Blizzard", "spell_frost_icestorm", 3, 2, 3, "", "Adds a Chill effect to your Blizzard spell. This effect lowers the target's movement speed by 40% for 1.5 sec." }, { "Ice Lance", "spell_frost_frostblast", 3, 3, 1, "", "Deals 28 to 32 Frost damage to an enemy target. Deals 300% increased damage to Frozen targets." }, { "Arctic Reach", "spell_shadow_darkritual", 4, 1, 2, "", "Increases the range of your Frostbolt, Ice Lance, and Blizzard spells and the radius of your Frost Nova and Cone of Cold spells by 20%." }, { "Ice Block", "spell_frost_frost", 4, 2, 1, "", "You become encased in a block of ice, protecting you from all physical attacks and spells for 10 sec, but during that time you cannot attack, move, or cast spells." }, { "Shatter", "spell_frost_frostshock", 4, 4, 3, "", "Increases the critical strike chance of all your spells against Frozen targets by 50%." }, { "Improved Cone of Cold", "spell_frost_glacier", 5, 1, 3, "", "Increases the damage dealt by your Cone of Cold spell by 35%." }, { "Cold Snap", "spell_frost_wizardmark", 5, 2, 1, "", "Finishes the remaining cooldown on all your other Frost spells." }, { "Fingers of Frost", "ability_mage_wintersgrasp", 5, 3, 2, "Ice Lance", "Gives your Chill effects a 15% chance to grant you the Fingers of Frost effect, which treats your next 2 spells cast as if the target were Frozen. Lasts 15 sec." }, { "Winter's Chill", "spell_frost_chillingblast", 6, 3, 5, "", "Gives your Frostbolt and Fingers of Frost empowered Ice Lance spells a 100% chance to apply Winter's Chill, increasing the target's damage taken from your next Cone of Cold by 20% and it gains an additional 7% of your spell damage, stacking up to 5 times." }, { "Ice Barrier", "spell_ice_lament", 7, 2, 1, "Cold Snap", "Shield yourself, absorbing 493 damage and increasing your Frost damage by 15% for 1 min. While shielded, your Frost damage is increased by an additional 5% and you do not lose casting time when you take damage." } } } },
  paladin = { { "Holy", { { "Spiritual Focus", "spell_arcane_blink", 1, 2, 5, "", "Gives your Flash of Light, Holy Light, and Light's Vigil spells a 70% chance to not lose casting time when you take damage." }, { "Divine Strength", "ability_golemthunderclap", 1, 3, 5, "", "Increases your Strength by 10%." }, { "Healing Light", "spell_holy_holybolt", 2, 1, 3, "", "Increases the amount healed by your Holy Light, Flash of Light, and Holy Shock spells by 12%." }, { "Reverence", "spell_holy_divineillumination", 2, 2, 2, "", "Allows 30% of your Mana regeneration to continue while casting." }, { "Improved Seals", "ability_thunderbolt", 2, 3, 5, "", "Increases the damage done by your Seals and Judgements by 15%." }, { "Purifying Power", "spell_holy_purifyingpower", 2, 4, 2, "", "Reduces the mana cost of your Cleanse and Purify spells by 20% and reduces the cooldown of your Exorcism and Holy Wrath spells by 33%." }, { "Divine Favor", "spell_holy_heal", 3, 1, 1, "", "When activated, gives your next Flash of Light, Holy Light, or Holy Shock spell a 100% critical effect chance." }, { "Illumination", "spell_holy_greaterheal", 3, 2, 5, "Reverence", "After getting a critical effect from your Flash of Light, Holy Light, Light's Vigil, or Holy Shock heal spell you have a 100% chance to gain Mana equal to 50% of the base cost of the spell." }, { "Holy Conduit", "spell_holy_devineaegis", 3, 3, 2, "", "Reduces the mana cost of your Consecration, Holy Wrath, Exorcism, and Hammer of Wrath spells by 40%." }, { "Divine Precision", "spell_holy_mindsooth", 4, 1, 2, "", "Improves your chance to hit with Holy spells by 8%, and reduces the duration of Silence effects on you by 20%." }, { "Infusion of Light", "ability_paladin_infusionoflight", 4, 2, 2, "", "Your Holy Shock and Flash of Light critical hits reduce the cast time of your next Holy Light cast within 15 sec by 1.0 sec." }, { "Oath of Light", "spell_holy_greaterblessingoflight", 4, 3, 1, "", "Swear an Oath to protect target ally for 5 min, increasing the healing of your Holy Light on them by up to 0, your Flash of Light by up to 0, and your Holy Shock by up to 0. Only one Oath of Light may be sworn by the Paladin at any one time." }, { "Consecrated Ground", "spell_holy_innerfire", 5, 1, 2, "", "Gives your Holy spells 10% increased damage against the first 4 enemies that enter your Consecration." }, { "Holy Shock", "spell_holy_searinglight", 5, 2, 1, "", "Blasts the target with Holy energy, causing 129 to 139 Holy damage to an enemy, or 110 to 118 healing to an ally." }, { "Boundless Light", "ability_paladin_sacredcleansing", 5, 3, 2, "Holy Shock", "Increases the critical strike chance of your Holy Shock spell by 30% when cast on allies not affected by your Oath of Light." }, { "Holy Power", "spell_holy_power", 6, 3, 5, "", "Increases the critical strike healing bonus of your Holy spells by 50%." }, { "Light's Vigil", "ability_paladin_judgementofthepure", 7, 2, 1, "Holy Shock", "Applies Light's Vigil to a friendly target for 30 sec. The caster's next Holy Shock on the target incurs no cooldown and heals the target and their party for 326 to 344. Only one Vigil per Paladin may be active in each party." } } }, { "Protection", { { "Divine Intellect", "spell_nature_sleep", 1, 2, 5, "", "Increases your total Intellect by 10%." }, { "Redoubt", "ability_defend", 1, 3, 5, "", "Damaging melee attacks against you have a 10% chance to increase your chance to block by 30%. Lasts 10 sec or 5 blocks." }, { "Precision", "ability_rogue_ambush", 2, 1, 3, "", "Improves your chance to hit by 3%." }, { "Guardian's Favor", "spell_holy_sealofprotection", 2, 2, 2, "", "Reduces the cooldown of your Blessing of Protection by 2 min and increases the duration of your Blessing of Freedom by 6 sec." }, { "Sacred Duty", "spell_holy_divineintervention", 2, 4, 2, "", "Reduces the cooldown of your Divine Shield, Divine Protection, and Templar's Bulwark spells by 60 sec, and reduces the duration of Forbearance by 10 sec." }, { "Templar's Bulwark", "ability_paladin_shieldofthetemplar", 3, 1, 1, "", "When activated, this ability grants you an absorb shield equal to 100% of your maximum health for 8 sec. Applies Forbearance for 1 min. Cannot be cast while Forbearance is active." }, { "Improved Hammer of Justice", "spell_holy_sealofmight", 3, 2, 3, "", "Decreases the cooldown of your Hammer of Justice spell by 15 sec." }, { "Shield Specialization", "inv_shield_06", 3, 3, 2, "Redoubt", "Increases the amount of damage absorbed by your shield by 30%, and gives your blocks a 100% chance to restore 4% of your maximum Mana. May only occur once every 3 sec." }, { "Toughness", "spell_holy_devotion", 3, 4, 5, "", "Increases your armor value from items by 10%." }, { "Swift Judgement", "ability_paladin_judgementred", 4, 1, 1, "Templar's Bulwark", "Unleash the energy of a Seal spell upon an enemy. Does not consume the Seal. Refer to individual Seals for Judgement effect. Does not share a cooldown with your Judgement ability." }, { "Improved Righteous Fury", "spell_holy_sealoffury", 4, 2, 3, "", "While Righteous Fury is active, all damage taken is reduced by 9%." }, { "Anticipation", "spell_magic_lesserinvisibilty", 4, 3, 5, "", "Increases your Defense Skill by 20." }, { "Stoicism", "spell_holy_stoicism", 5, 1, 2, "", "Reduces the duration of Stun and Charm effects on you by 20%." }, { "Holy Shield", "spell_holy_blessingofprotection", 5, 2, 1, "", "Increases chance to block by 30% for 10 sec, and deals 75 Holy damage for each attack blocked while active. Damage caused by Holy Shield causes 20% additional threat. Each block expends a charge. 4 charges." }, { "Reckoning", "spell_holy_blessingofstrength", 5, 3, 5, "", "Gives you a 40% chance after Blocking and a 100% chance after receiving a non-periodic critical strike to gain an extra attack. Stores up to 4 extra attacks. Cannot occur from Blocks more than once every 1.5 sec." }, { "Iron Creed", "spell_holy_improvedresistanceauras", 6, 3, 3, "", "Increases the threat generated by your Holy Strike ability by 30%. While Righteous Fury is active, Holy Strike also reduces your damage taken by 6% for 6 sec." }, { "Shieldsworn", "spell_holy_greaterblessingofsanctuary", 7, 2, 1, "Holy Shield", "Reduces the cooldown of your Holy Strike ability by 4 sec. Additionally, Holy Strike now strikes with your shield, triggering your active Holy Shield and Shield Specialization talents without consuming their charges or triggering their cooldowns, and allowing you to Block spells for 6 sec." } } }, { "Retribution", { { "Deflection", "ability_parry", 1, 2, 5, "", "Increases your Parry chance by 5%." }, { "Benediction", "spell_frost_windwalkon", 1, 3, 5, "", "Reduces the Mana cost of all instant cast spells and abilities by 10%." }, { "Improved Judgement", "spell_holy_righteousfury", 2, 1, 2, "", "Decreases the cooldown of your Judgement ability by 2 sec." }, { "Conviction", "spell_holy_retributionaura", 2, 2, 3, "", "Improves your chance to get a critical strike with all spells and attacks by 6%." }, { "Sanctified Judgement", "ability_paladin_judgementblue", 2, 3, 3, "", "Gives your Judgement ability a 100% chance to return 60% of the Mana cost of the judged seal." }, { "Vindication", "spell_holy_vindication", 3, 1, 3, "", "Gives your damaging melee attacks a chance to reduce the target's Attack Power by 200 for 30 sec." }, { "Unyielding Faith", "spell_holy_unyieldingfaith", 3, 2, 2, "", "Reduces the duration of Fear and Disorient effects on you by 30%." }, { "Seal of Command", "ability_warrior_innerrage", 3, 3, 1, "", "Gives the Paladin a chance to deal additional Holy damage equal to 70% of normal weapon damage. Only one Seal can be active on the Paladin at any one time. Lasts 30 sec.\n\nUnleashing this Seal's energy will judge an enemy, instantly causing 69 to 73 Holy damage, 138 to 146 if the target is stunned or incapacitated." }, { "Pursuit of Justice", "spell_holy_persuitofjustice", 3, 4, 2, "", "Increases movement speed and mounted movement speed by 15%. This does not stack with other movement speed increasing effects." }, { "Eye for an Eye", "spell_holy_eyeforaneye", 4, 1, 2, "", "All critical strikes against you cause 10% of the damage taken to the attacker as well. The damage caused by Eye for an Eye will not exceed 50% of the Paladin's total health." }, { "Sacred Arbiter", "inv_sword_08", 4, 2, 1, "", "Increases the damage of your Holy Strike ability by 20% and causes it to refresh all Judgement effects on the target." }, { "Two-Handed Weapon Specialization", "inv_hammer_04", 4, 4, 3, "", "Increases the Physical and Holy damage you deal by 6%, and reduces all threat you generate by 20% while a two-handed melee weapon is equipped." }, { "Turn Evil", "spell_holy_turnundead", 5, 1, 2, "", "Reduces the cast time of your Turn Undead spell by 1.0 sec, its cooldown by 10 sec, and allows it to affect Demons." }, { "Repentance", "spell_holy_prayerofhealing", 5, 2, 1, "", "Puts the enemy target in a state of meditation, incapacitating them for up to 6 sec. Any damage caused will awaken the target. Only works against Humanoids." }, { "Vengeance", "ability_racial_avatar", 5, 3, 3, "Seal of Command", "Increases your Physical and Holy damage dealt by 3% for 30 sec after landing a non-periodic critical strike. Stacks up to 5 times." }, { "Champion of the Light", "ability_paladin_enlightenedjudgements", 6, 3, 5, "", "Increases your spell damage by up to 60% of your Intellect, and reduces the cast time of your Hammer of Wrath by 1.0 sec." }, { "Unsealed Wrath", "spell_holy_blessedresillience", 7, 2, 1, "Repentance", "Your melee attacks store a copy of your active Seal for 15 sec, stacking up to 3 times. Landing an attack with a different Seal consumes all stacks, giving the stored Seal its normal chance to activate once per stack." } } } },
  priest = { { "Discipline", { { "Power in Light", "spell_holy_searinglight", 1, 1, 5, "", "Your Smite and Penance spells deal 10% increased damage to targets afflicted with your Holy Fire or Shadow Word: Pain." }, { "Wand Specialization", "inv_wand_01", 1, 2, 2, "", "Increases your damage with Wands by 25%." }, { "Twin Disciplines", "spell_holy_sealofvengeance", 1, 3, 5, "", "Increases the damage and healing of your instant cast spells by 5%." }, { "Silent Resolve", "spell_nature_manaregentotem", 2, 1, 3, "", "Reduces the threat generated by your spells by 30% and reduces the duration of Stun, Fear, and Silence effects inflicted on you by 15%." }, { "Holy Precision", "spell_holy_divineillumination", 2, 2, 3, "", "Improves your chance to hit with Holy spells by 18%." }, { "Mental Strength", "spell_nature_enchantarmor", 2, 3, 5, "", "Increases your total Intellect by 10%." }, { "Martyrdom", "spell_nature_tranquility", 2, 4, 2, "", "Gives you a 100% chance to gain Focused Casting for 6 sec after being the victim of a melee or ranged critical strike. The Focused Casting effect prevents you from losing casting time when taking damage and increases your resistance to Interrupt effects by 20%." }, { "Mental Agility", "ability_hibernation", 3, 1, 3, "", "Reduces the mana cost of your Smite, Holy Fire, and instant cast spells by 10%." }, { "Inner Focus", "spell_frost_windwalkon", 3, 2, 1, "", "When activated, reduces the Mana cost of your next spell by 100% and increases its critical effect chance by 25% if it is a non-periodic spell and capable of a critical effect." }, { "Improved Power Word: Shield", "spell_holy_powerwordshield", 3, 3, 3, "", "Increases the damage absorbed by your Power Word: Shield by 20%." }, { "Meditation", "spell_nature_sleep", 3, 4, 3, "", "Allows 50% of your Mana regeneration to continue while casting." }, { "Improved Inner Fire", "spell_holy_innerfire", 4, 1, 3, "", "Increases the Armor bonus of your Inner Fire spell by 45% and increases its total charges by 12." }, { "Improved Mana Burn", "spell_shadow_manaburn", 4, 2, 2, "", "Reduces the casting time of your Mana Burn spell by 1.0 sec." }, { "Soul Warding", "spell_holy_pureofheart", 4, 3, 1, "Improved Power Word: Shield", "Reduces the cooldown on your Power Word: Shield spell by 4 sec and reduces its mana cost by 15%." }, { "Penance", "spell_holy_penance", 5, 2, 1, "", "Launches a volley of holy light at the target, causing 45 Holy damage to an enemy, or 134 healing to an ally, instantly and every 1 sec for 2 sec." }, { "Renewed Hope", "spell_holy_holyprotection", 5, 3, 5, "Soul Warding", "Your heals from Flash Heal, Lesser Heal, Heal, Greater Heal, and Penance gain 10% increased critical strike chance when cast on targets with Weakened Soul, and reduce the remaining duration of Weakened Soul on their target by 5 sec." }, { "Divine Aegis", "spell_holy_devineaegis", 6, 3, 3, "", "Your non-periodic critical heals create a protective shield on the target, absorbing 15% of the amount healed. Shields up to 1200 damage and lasts 12 sec." }, { "Power Infusion", "spell_holy_powerinfusion", 7, 2, 1, "Penance", "Infuses the target with power, increasing their spell damage and healing done by 20% for 15 sec." } } }, { "Holy", { { "Twilight Focus", "spell_holy_healingfocus", 1, 1, 3, "", "Gives your spells a 70% chance to not lose casting time when you take damage." }, { "Improved Renew", "spell_holy_renew", 1, 2, 3, "", "Increases the amount healed by your Renew spell by 15%." }, { "Holy Specialization", "spell_holy_sealofsalvation", 1, 3, 5, "", "Increases the critical effect chance of your Holy spells by 5%." }, { "Spell Warding", "spell_holy_spellwarding", 2, 2, 5, "", "Reduces all spell damage taken by 10%." }, { "Divine Fury", "spell_holy_sealofwrath", 2, 3, 5, "", "Reduces the casting time of your Smite, Holy Fire, Heal, and Greater Heal spells by 0.5 sec." }, { "Holy Nova", "spell_holy_holynova", 3, 1, 1, "", "Causes an explosion of holy light around the caster, causing 26 to 30 Holy damage to all enemy targets within 10 yards and healing all party members within 10 yards for 50 to 57. These effects cause no threat." }, { "Blessed Recovery", "spell_holy_blessedrecovery", 3, 2, 3, "", "After being struck by a melee or ranged critical hit, or suffering more than 30% of your maximum Health from a single attack, heal 25% of the damage taken over 6 sec. Refreshing this effect carries over any remaining healing." }, { "Inspiration", "spell_holy_layonhands", 3, 4, 3, "", "Your non-periodic critical heals increase your target's Armor by 25% for 15 sec." }, { "Holy Reach", "spell_holy_purify", 4, 1, 2, "", "Increases the range of your Smite and Holy Fire spells and the radius of your Prayer of Healing and Holy Nova spells by 20%." }, { "Improved Healing", "spell_holy_heal02", 4, 2, 3, "", "Reduces the Mana cost of your Lesser Heal, Heal, Greater Heal, Penance, and Prayer of Mending spells by 15%." }, { "Searing Light", "spell_holy_searinglightpriest", 4, 3, 2, "Divine Fury", "Increases your Holy damage done by 5%, and gives a 10% chance each time your Holy Fire spell deals periodic damage for your next Holy Nova to cost no Mana." }, { "Holy Binding", "spell_holy_blindingheal", 4, 4, 1, "", "Each time you heal a target other than yourself with Flash Heal, you are healed for 50% as much. This healing generates no threat." }, { "Litany of Light", "inv_scroll_07", 5, 1, 2, "", "When you cast a healing spell, gain Mana equal to 10% of the base cost of the spell if your previous heal was a different spell." }, { "Spirit of Redemption", "inv_enchant_essenceeternallarge", 5, 2, 1, "", "Upon death, the priest becomes the Spirit of Redemption for 15 sec. The Spirit of Redemption cannot move, attack, be attacked or targeted by any spells or effects. While in this form the priest can cast any healing spell free of cost. When the effect ends, the priest dies." }, { "Spiritual Guidance", "spell_holy_spiritualguidence", 5, 3, 5, "", "Increases your spell healing by up to 25% of your total Spirit and your spell damage by up to 8% of your total Spirit." }, { "Spiritual Healing", "spell_nature_moonglow", 6, 3, 3, "", "Increases the amount healed by your spells by 10%." }, { "Prayer of Mending", "spell_holy_prayerofmendingtga", 7, 2, 1, "Spirit of Redemption", "Places a spell on the target that heals them for 172 the next time they take damage or receive non-periodic healing. When the heal occurs, Prayer of Mending jumps to a party or raid member within 20 yards. Jumps up to 5 times and lasts 30 sec after each jump. This spell can only be placed on one target at a time per caster." } } }, { "Shadow", { { "Shadow Focus", "spell_shadow_burningspirit", 1, 1, 5, "", "Improves your chance to hit with Shadow spells by 5%." }, { "Blackout", "spell_shadow_gathershadows", 1, 2, 5, "", "Gives your Shadow damage spells a 10% chance to stun the target for 3 sec." }, { "Spirit Tap", "spell_shadow_requiem", 1, 3, 5, "", "Gives you a 100% chance to increase your Spirit by 100% for 15 sec after killing a non-trivial target or when an enemy afflicted by your Vampiric Embrace dies. For the duration, 50% of your Mana regeneration will continue while casting." }, { "Improved Mind Blast", "spell_shadow_unholyfrenzy", 2, 1, 5, "", "Reduces the cooldown of your Mind Blast spell by 2.5 sec." }, { "Improved Shadow Word: Pain", "spell_shadow_shadowwordpain", 2, 3, 2, "", "Increases the duration of your Shadow Word: Pain spell by 6 sec." }, { "Shadow Reach", "spell_shadow_chilltouch", 2, 4, 2, "", "Increases the range of your offensive Shadow spells by 20%." }, { "Improved Psychic Scream", "spell_shadow_psychicscream", 3, 2, 2, "Blackout", "Reduces the cooldown of your Psychic Scream spell by 4 sec." }, { "Mind Flay", "spell_shadow_siphonmana", 3, 3, 1, "", "Assault the target's mind with Shadow energy, causing 63 Shadow damage over 3 sec and slowing their movement speed by 50%." }, { "Improved Mind Flay", "spell_shadow_soulleech_2", 3, 4, 2, "Mind Flay", "Each instance of damage of Mind Flay deals 20% more damage than its previous instance of damage." }, { "Dark Inspiration", "spell_warlock_demonsoul", 4, 1, 5, "", "Your Mind Blast and fully channeled Mind Flay causes Dark Inspiration, increasing yours and your party's Spirit by 15% for 10 sec." }, { "Vampiric Embrace", "spell_shadow_unsummonbuilding", 4, 2, 1, "", "Afflicts your target with Shadow energy that causes all party members to be healed for 20% of any Shadow spell damage you deal for 30 sec." }, { "Shadow Weaving", "spell_shadow_blackplague", 4, 3, 3, "", "Your Shadow damage spells have a 100% chance to increase the Shadow damage the target takes from you by 2% for 15 sec, stacking up to 5 times." }, { "Silence", "spell_shadow_impphaseshift", 5, 1, 1, "", "Silences the target, preventing them from casting spells for 5 sec and interrupting their spellcasts for 3 sec." }, { "Devouring Contagion", "spell_shadow_devouringplague.", 5, 3, 2, "", "Reduces the mana cost of your Devouring Plague by 50%.\n\nTargets that die while Devouring Plague is active spreads it, jumping to 2 nearby enemies within 10 yds for the remaining duration." }, { "Early Demise", "spell_shadow_demonicfortitude", 6, 1, 2, "", "Increases Shadow Word: Death's critical strike chance on targets at or below 20% health by 30%." }, { "Darkness", "spell_shadow_twilight", 6, 3, 5, "", "Increases your Shadow damage done by 10%." }, { "Shadowform", "spell_shadow_shadowform", 7, 2, 1, "Vampiric Embrace", "Assume Shadowform, increasing your Shadow damage by 10%, reducing the Mana cost of all Shadow spells by 50%, increasing the critical strike damage bonus of your Shadow spells by 100%, and reducing Physical damage taken by you by 15%. However, you may not cast healing spells while in this form." } } } },
  rogue = { { "Assassination", { { "Improved Gouge", "ability_gouge", 1, 1, 3, "", "Increases the duration of your Gouge ability by 1.5 sec." }, { "Remorseless Attacks", "ability_fiegndead", 1, 2, 2, "", "After killing a non-trivial enemy, gives you a 40% increased critical strike chance on your next Sinister Strike, Backstab, Ambush, Mutilate, or Ghostly Strike. Lasts 20 sec." }, { "Malice", "ability_racial_bloodrage", 1, 3, 5, "", "Increases your critical strike chance with all attacks and Poisons by 5%." }, { "Ruthlessness", "ability_druid_disembowel", 2, 1, 3, "", "Gives your finishing moves a 60% chance to add a Combo Point to your target." }, { "Improved Expose Armor", "ability_warrior_riposte", 2, 2, 2, "", "Reduces the Energy cost of your Expose Armor ability by 10, and refunds 2 Combo Points when cast with 5 Combo Points." }, { "Improved Slice and Dice", "ability_rogue_slicedice", 2, 4, 3, "", "Increases the duration of your Slice and Dice ability by 45%." }, { "Vigor", "spell_nature_earthbindtotem", 3, 1, 2, "", "Increases your maximum Energy by 10." }, { "Blood Splatter", "ability_rogue_rupture", 3, 2, 1, "", "Increases the duration of your Rupture ability by 6 sec and your Garrote ability by 9 sec." }, { "Lethality", "ability_criticalstrike", 3, 3, 2, "Malice", "Increases the critical strike damage bonus of your Sinister Strike, Gouge, Backstab, Mutilate, Ghostly Strike, and Hemorrhage abilities by 20%." }, { "Vile Poisons", "ability_rogue_feigndeath", 4, 1, 5, "", "Increases the damage dealt by your poisons by 20% and gives your poisons an additional 40% chance to resist dispel effects." }, { "Cold Blood", "spell_ice_lament", 4, 2, 1, "", "When activated, increases the critical strike chance of your next Sinister Strike, Backstab, Ambush, Eviscerate, or Mutilate by 100%." }, { "Improved Poisons", "ability_poisons", 4, 3, 5, "", "Increases the chance to apply Poisons to your target by 10%, and gives Poison applications a 50% chance to not consume a charge." }, { "Relentless Strikes", "ability_warrior_decisivestrike", 5, 1, 5, "", "Your finishing moves have a 20% chance per Combo Point to restore 25 Energy." }, { "Venom", "inv_sword_31", 5, 2, 1, "", "Causes your Shank ability to increase your Poison damage by 30% and your chance to apply Poisons by 20% for 6 sec." }, { "Improved Kidney Shot", "ability_rogue_kidneyshot", 5, 3, 2, "", "Enemies Stunned by your Kidney Shot ability take 10% increased damage from your poisons and attacks." }, { "Seal Fate", "spell_shadow_chilltouch", 6, 3, 3, "", "Your critical strikes from abilities that add Combo Points have a 100% chance to add an additional Combo Point." }, { "Mutilate", "ability_rogue_deadlybrew", 7, 2, 1, "Venom", "Instantly attacks with both weapons for 90% weapon damage plus an additional 40 with each weapon. Damage increased by 20% against Poisoned targets. Awards 2 Combo Points." } } }, { "Combat", { { "Coup de Grace", "ability_rogue_eviscerate", 1, 1, 3, "", "Increases the damage done by your Eviscerate ability by 20%, and the damage and storage rate of your Death Mark ability by 20%." }, { "Efficient Strikes", "spell_shadow_ritualofsacrifice", 1, 2, 2, "", "Reduces the Energy cost of your Sinister Strike and Hemorrhage abilities by 5." }, { "Lightning Reflexes", "spell_nature_invisibilty", 1, 3, 5, "", "Increases your Dodge chance by 5%." }, { "Puncturing Wounds", "ability_backstab", 2, 1, 3, "", "Increases the critical strike chance of your Backstab by 30% and your Mutilate by 15%, and gives Backstab a 45% chance to add an additional Combo Point." }, { "Deflection", "ability_parry", 2, 2, 3, "", "Increases your Parry chance by 6%." }, { "Precision", "ability_marksmanship", 2, 3, 3, "", "Improves your chance to hit by 3%." }, { "Improved Sprint", "ability_rogue_sprint", 2, 4, 2, "", "Gives a 100% chance to remove all movement impairing effects when you activate your Sprint ability." }, { "Endurance", "spell_shadow_shadowward", 3, 1, 2, "", "Reduces the cooldown of your Sprint and Evasion abilities by 60%." }, { "Riposte", "ability_warrior_challange", 3, 2, 1, "Deflection", "A strike that becomes active after parrying an opponent's attack. This attack deals 150% weapon damage and disarms the target for 6 sec." }, { "Composure", "ability_rogue_fleetfooted", 3, 4, 2, "", "Increases the Energy cost reduction of your Poised ability by 10." }, { "Improved Kick", "ability_kick", 4, 1, 2, "", "Gives your Kick ability a 100% chance to Silence the target for 2 sec." }, { "Flawless Execution", "inv_sword_35", 4, 2, 1, "", "Reduces the Energy cost of your Eviscerate ability by 15." }, { "Weapon Expertise", "spell_holy_blessingofstrength", 4, 3, 2, "Precision", "Reduces the chance for your attacks to be Dodged or Parried by 2%." }, { "Aggression", "ability_racial_avatar", 4, 4, 3, "", "Increases the damage of your Sinister Strike and Eviscerate abilities by 15%." }, { "Dual Wield Specialization", "ability_dualwield", 5, 1, 2, "", "Increases the damage done by your off-hand weapon by 50%." }, { "Blade Flurry", "ability_warrior_punishingblow", 5, 2, 1, "", "Increases your melee attack speed by 20% and your melee attacks strike an additional nearby opponent. Lasts 15 sec." }, { "Hack and Slash", "inv_sword_27", 5, 3, 5, "", "Gives your melee weapon attacks a benefit depending on the weapon.\n\nAxe/Sword: Your successful\nmelee attacks have a 5% chance\nto trigger an extra attack on the\ntarget.\n\nDagger/Fist: Increases your\ncritical strike chance by 5%.\n\nMace: Your attacks ignore 15% of\nyour target's armor." }, { "Flash of Steel", "ability_rogue_restlessblades", 6, 3, 5, "", "Increases the Energy generated by your Shank ability by 15 and reduces its cooldown by 2.0 sec." }, { "Adrenaline Rush", "spell_shadow_shadowworddominate", 7, 2, 1, "Blade Flurry", "Increases your Energy regeneration rate by 100% for 15 sec." } } }, { "Subtlety", { { "Setup", "spell_nature_mirrorimage", 1, 1, 3, "", "Gives you a 45% chance to add a Combo Point to your target after Dodging their attack or fully resisting one of their spells." }, { "Master of Deception", "spell_shadow_charm", 1, 2, 3, "", "Reduces the chance enemies have to detect you while in Stealth mode as if you were 3 levels higher." }, { "Opportunity", "ability_warrior_warcry", 1, 3, 5, "", "Increases the damage dealt by your Backstab, Garrote, Ambush, and Mutilate abilities by 20%." }, { "Dirty Deeds", "spell_shadow_summonsuccubus", 2, 1, 2, "", "Reduces the Energy cost of your Cheap Shot and Garrote abilities by 20, and your Garrote ability no longer requires you to be behind your target." }, { "Camouflage", "ability_stealth", 2, 2, 3, "", "Reduces your speed penalty from your Stealth ability by 15% and reduces its cooldown by 6 sec." }, { "Improved Ambush", "ability_rogue_ambush", 2, 3, 3, "", "Increases the critical strike chance of your Ambush ability by 45%." }, { "Dirty Tricks", "ability_sap", 2, 4, 2, "", "Reduces the Energy cost of your Sap and Blind abilities by 50%." }, { "Initiative", "spell_shadow_fumble", 3, 1, 3, "", "Gives you a 100% chance to add an additional combo point to your target when using your Ambush, Garrote, or Cheap Shot ability." }, { "Premeditation", "spell_shadow_possession", 3, 2, 1, "", "Adds 2 Combo Points to your target. You must add to or use those combo points within 20 sec or the combo points are lost." }, { "Serrated Blades", "inv_sword_17", 3, 3, 3, "", "Causes your attacks to ignore 9% of your target's Armor and increases the damage dealt by your Rupture ability by 30%." }, { "Elusiveness", "spell_magic_lesserinvisibilty", 4, 1, 2, "", "Reduces the cooldown of your Vanish and Blind abilities by 90 sec." }, { "Ghostly Strike", "spell_shadow_curse", 4, 2, 1, "", "A strike that deals 125% (180% if a Dagger is equipped in your Main Hand) weapon damage, increases your chance to dodge by 15% for 7 sec, and causes your next Ambush or Garrote cast within 7 sec to not require Stealth. Awards 1 combo points." }, { "Quick Getaway", "ability_rogue_blackjack", 4, 4, 2, "Dirty Tricks", "Increases the maximum number of targets you may have Sapped by 1, and increases your movement speed by 30% for 3 sec after Sapping a target." }, { "Heightened Senses", "ability_ambush", 5, 1, 2, "", "Increases your Stealth detection as if you were 3 levels higher and reduces your chance to be hit by spells and ranged attacks by 4%." }, { "Preparation", "spell_shadow_antishadow", 5, 2, 1, "", "When activated, this ability immediately finishes the cooldown on your other Rogue abilities." }, { "Hemorrhage", "spell_shadow_lifedrain", 5, 3, 1, "Serrated Blades", "An instant strike that deals 100% weapon damage (145% if a Dagger is equipped) and causes the target to take 15% increased Rupture and Garrote damage from the Rogue. Lasts 15 sec. Awards 1 Combo Points." }, { "Boot Knife", "inv_sword_32", 6, 3, 5, "", "Grants your Shank ability a 100% chance to add 2 Combo Points to the target." }, { "Death Mark", "ability_creature_cursed_02", 7, 2, 1, "Preparation", "Finishing move that marks the target, storing a portion of the damage dealt by your attacks per Combo Point. Garrote and Rupture damage is stored at twice the rate. After 6 sec, the stored damage is dealt, up to a maximum increased by Attack Power and Critical Strike chance:\n1 point : 12% stored, (169.95 + 4.12% of attack power) damage cap\n2 points: 24% stored, (275.01 + 8.24% of attack power) damage cap\n3 points: 36% stored, (380.07 + 12.36% of attack power) damage cap\n4 points: 48% stored, (485.13 + 16.48% of attack power) damage cap\n5 points: 60% stored, (590.19 + 20.6% of attack power) damage cap" } } } },
  shaman = { { "Elemental", { { "Convection", "spell_nature_wispsplode", 1, 2, 5, "", "Reduces the mana cost of your Shock, Lightning Bolt, and Chain Lightning spells by 10%." }, { "Concussion", "spell_nature_earthshock", 1, 3, 5, "", "Increases the damage done by your Lightning Bolt, Chain Lightning, and Earth Shock spells by 5%." }, { "Elemental Devastation", "spell_fire_elementaldevastation", 2, 1, 3, "", "Your Critical Strikes with direct damage spells increase your chance to get a Critical Strike with melee attacks by 9% for 10 sec." }, { "Reverberation", "spell_frost_frostward", 2, 2, 5, "", "Reduces the cooldown of your Shock spells by 1.0 sec." }, { "Elemental Alacrity", "spell_lightning_lightningbolt01", 2, 3, 3, "", "Reduces the cast time of your Lightning Bolt and Chain Lightning spells by 0.50 sec." }, { "Call of Flame", "spell_fire_immolation", 2, 4, 3, "", "Increases the damage done by your Fire Totems and by your Flame Shock and Fire Nova spells by 15%, as well as increases the duration of your Flame Shock spell by 9 sec." }, { "Elemental Focus", "spell_shadow_manaburn", 3, 1, 1, "", "Gives you a 10% chance to enter a Clearcasting state after casting any Fire, Frost, or Nature damage spell. The Clearcasting state reduces the mana cost of your next damage spell by 100%." }, { "Elemental Warding", "spell_nature_spiritarmor", 3, 2, 3, "", "Reduces damage taken from Fire, Frost, and Nature effects by 10%." }, { "Trial by Fire", "spell_fire_sealoffire", 4, 1, 2, "", "Increases the damage done by your Fire Nova spell by 20% and reduces its cooldown by 4 sec, and increases the duration of your Magma Totem by 20 sec." }, { "Eye of the Storm", "spell_nature_eyeofthestorm", 4, 2, 3, "", "Gives your Lightning Bolt and Chain Lightning spells a 70% chance to not lose casting time when you take damage." }, { "Earthbound", "spell_nature_stranglevines", 4, 4, 1, "", "Your Earthbind Totem Immobilizes nearby targets for 5 sec when cast." }, { "Elemental Reach", "spell_nature_stormreach", 5, 1, 2, "", "Increases the range of your Lightning Bolt, Chain Lightning, and Fire Nova spells by 6 yards." }, { "Call of Thunder", "spell_nature_callstorm", 5, 2, 1, "", "Increases the critical strike chance of your Lightning Bolt and Chain Lightning spells by 5%." }, { "Lightning Overload", "spell_nature_lightningoverload", 5, 3, 3, "Elemental Alacrity", "Gives your Lightning Bolt and Chain Lightning spells a 30% chance to cast a second, similar spell on the same target at no additional cost that causes half damage and no threat." }, { "Elemental Fury", "spell_fire_volcano", 6, 3, 5, "Lightning Overload", "Increases the critical strike damage bonus of your Searing and Magma Totems and your Fire, Frost, and Nature spells by 100%." }, { "Lightning Mastery", "spell_nature_unrelentingstorm", 7, 2, 1, "Call of Thunder", "Gain mastery over Lightning, reducing the cast time of your Lightning Bolt spell by 0.5 sec, and removing the cooldown from your Chain Lightning spell. Lasts 15 sec." } } }, { "Enhancement", { { "Earth's Grasp", "spell_nature_stoneclawtotem", 1, 1, 2, "", "Increases the health of your Stoneclaw Totem by 50% and the radius of your Earthbind Totem by 20%." }, { "Thundering Strikes", "ability_thunderbolt", 1, 2, 5, "", "Improves your chance to get a critical strike with all spells and attacks by 5%." }, { "Ancestral Knowledge", "spell_shadow_grimward", 1, 3, 5, "", "Increases your Intellect by 10%." }, { "Guardian Totems", "spell_nature_stoneskintotem", 2, 1, 2, "", "Increases the amount of damage reduced by your Stoneskin Totem and Windwall Totem by 20% and reduces the cooldown of your Grounding Totem by 2 sec." }, { "Mental Dexterity", "spell_nature_mentalquickness", 2, 2, 3, "", "Increases your Attack Power by an amount equal to 100% of your Intellect." }, { "Improved Lightning Shield", "spell_nature_lightningshield", 2, 3, 3, "", "Increases the damage done by your Lightning Shield orbs by 15%." }, { "Elemental Weapons", "spell_fire_flametounge", 3, 1, 3, "", "Increases the melee attack power bonus of your Rockbiter Weapon by 20%, your Windfury Weapon effect by 40% and increases the damage caused by your Flametongue Weapon and Frostbrand Weapon by 15%." }, { "Shamanistic Focus", "spell_nature_elementalabsorption", 3, 3, 1, "", "Reduces the mana cost of your Shock and Lightning Shield spells by 45%." }, { "Anticipation", "spell_nature_mirrorimage", 3, 4, 3, "", "Increases your chance to dodge by an additional 6%." }, { "Toughness", "spell_holy_devotion", 4, 1, 5, "", "Increases your Stamina by 10%." }, { "Flurry", "ability_ghoulfrenzy", 4, 2, 5, "Mental Dexterity", "Increases your attack speed by 30% for your next 3 swings after dealing a melee critical strike." }, { "Stormstrike", "ability_shaman_stormstrike", 4, 3, 1, "", "Instantly strike for 100% weapon damage and increase the damage you deal to the target with your next Lightning Bolt, Chain Lightning, or Earth Shock spell by 20% for 12 sec." }, { "Improved Ghost Wolf", "spell_nature_spiritwolf", 4, 4, 2, "", "Reduces the cast time of your Ghost Wolf spell by 3.0 sec, and Ghost Wolf may be used indoors." }, { "Spirit Weapons", "ability_parry", 5, 1, 1, "", "Gives a chance to parry enemy melee attacks, reduces all threat generated by your attacks by 30% while Rockbiter Weapon is not active, and increases all threat generated by 30% while Rockbiter Weapon is active." }, { "Mental Quickness", "spell_nature_sleep", 5, 2, 2, "", "Increases your spell damage and healing by up to 30% of your Intellect." }, { "Improved Stormstrike", "spell_shaman_improvedstormstrike", 5, 3, 2, "Stormstrike", "When you Stormstrike, you have a 100% chance to gain 50% mana regeneration while casting spells for 15 sec, and Stormstrike's cooldown has a 100% chance to reset each time you Dodge or Parry." }, { "Maelstrom Weapon", "spell_shaman_maelstromweapon", 6, 3, 5, "", "When you deal damage with a melee attack, you have a chance (based on weapon speed) to reduce the cast time and Mana cost of your next Lightning Bolt spell by 20%. Stacks up to 5 times. Lasts 30 sec. Activates about 10 times per minute." }, { "Rage of the Farseer", "spell_nature_bloodlust", 7, 2, 1, "Mental Quickness", "Increases your attack speed by 30% for 25 sec." } } }, { "Restoration", { { "Improved Healing Wave", "spell_nature_magicimmunity", 1, 2, 5, "", "Reduces the casting time of your Healing Wave spell by 0.5 sec." }, { "Tidal Focus", "spell_frost_manarecharge", 1, 3, 5, "", "Reduces the Mana cost of your healing spells by 5% and improves your chance to hit by 5%." }, { "Mindfulness", "spell_nature_sleep", 2, 1, 3, "", "Allows 50% of your Mana regeneration to continue while casting." }, { "Natural Grace", "spell_nature_healingtouch", 2, 2, 3, "", "Reduces the threat generated by your spells by 15%." }, { "Totemic Focus", "spell_nature_moonglow", 2, 3, 5, "", "Reduces the Mana cost of your totems and any spells that summon or move them by 25%." }, { "Improved Reincarnation", "spell_nature_reincarnation", 2, 4, 2, "", "Reduces the cooldown of your Reincarnation spell by 20 min, increases your maximum health by 4%, and increases the amount of health and Mana you reincarnate with by an additional 20%." }, { "Ancestral Healing", "spell_nature_undyingstrength", 3, 1, 3, "", "Increases your target's armor value by 25% for 15 sec after getting a critical effect from one of your healing spells." }, { "Healing Focus", "spell_nature_healingwavelesser", 3, 2, 3, "", "Gives your healing spells a 70% chance to not lose casting time when you take damage." }, { "Water Shield", "ability_shaman_watershield", 3, 3, 1, "", "The caster is surrounded by 3 globes of water. When a spell, melee, or ranged attack hits the caster or when one of the caster's spells gets a critical result, 2% of maximum mana is restored to the caster, expending one water globe. Only one globe will activate every few seconds. Lasts 10 min.\n\nOnly one Elemental Shield can be active on the Shaman at any one time." }, { "Tidal Mastery", "spell_nature_tranquility", 4, 1, 5, "", "Increases the critical effect chance of your healing spells by 5%." }, { "Restorative Totems", "spell_nature_manaregentotem", 4, 2, 5, "", "Increases the effect of your Mana Spring Totem by 25% and increases the effect of your Healing Stream Totem by 50%." }, { "Mana Tide Totem", "spell_frost_summonwaterelemental", 4, 3, 1, "", "Summons a Mana Tide Totem with 5 health at the feet of the caster for 12 sec that restores 88 mana every 3 seconds to group members within 30 yards." }, { "Healing Way", "spell_nature_healingway", 5, 2, 3, "", "Increases the amount healed by your Healing Wave spell by 25%." }, { "Nature's Swiftness", "spell_nature_ravenform", 5, 3, 1, "", "When activated, your next Nature spell with a casting time less than 10 sec. becomes an instant cast spell." }, { "Purification", "spell_frost_wizardmark", 6, 3, 5, "", "Increases the effectiveness of your healing spells by 10%." }, { "Riptide", "spell_nature_riptide", 7, 2, 1, "Healing Way", "Heals a friendly target for 445 over 15 sec, and increases the effectiveness of your Chain Heal casts directly on that target by 25%." } } } },
  warlock = { { "Affliction", { { "Improved Life Tap", "spell_shadow_burningspirit", 1, 1, 2, "", "Increases the amount of Mana awarded by your Life Tap spell by 20%." }, { "Suppression", "spell_shadow_unsummonbuilding", 1, 2, 5, "", "Improves your chance to hit by 5% and reduces all threat you generate by 20%." }, { "Improved Corruption", "spell_shadow_abominationexplosion", 1, 3, 5, "", "Reduces the casting time of your Corruption spell by 2 sec and increases the damage it deals by 10%." }, { "Grim Reach", "spell_shadow_callofbone", 2, 1, 2, "", "Increases the range of your Affliction spells by 20%." }, { "Soul Harvest", "inv_elemental_primal_shadow", 2, 2, 2, "", "Killing a non-trivial target afflicted by your Drain Soul increases your Mana regeneration by 100% for 10 sec and allows 100% of normal Mana regeneration to continue while casting." }, { "Improved Drains", "spell_shadow_haunting", 2, 3, 3, "", "Increases Health drained, damage done, or Mana drained by your Drain Life, Drain Soul, and Drain Mana spells by 20%." }, { "Improved Bane of Agony", "spell_shadow_curseofsargeras", 3, 1, 2, "", "Increases the damage done by your Bane of Agony by 10%." }, { "Fel Concentration", "spell_shadow_fingerofdeath", 3, 2, 3, "", "Gives your Drain Life, Drain Mana, Drain Soul, and Wrack spells a 70% chance to not lose casting time when you take damage." }, { "Amplify Curse", "spell_shadow_contagion", 3, 3, 1, "", "Increases the effect of your next Curse of Weakness or Bane of Agony by 50%, or your next Curse of Exhaustion by 20%. Lasts 30 sec." }, { "Pandemic", "spell_shadow_unstableaffliction_2", 3, 4, 3, "", "Increases the critical strike damage bonus of your Corruption, Bane of Agony, Bane of Doom, Drain Soul, Drain Life, Siphon Life, and Wrack spells by 100%." }, { "Malevolence", "spell_shadow_focusedpower", 4, 1, 5, "", "Increases the critical effect chance of your Shadow spells by 5%." }, { "Nightfall", "spell_shadow_twilight", 4, 2, 2, "", "Gives your Corruption, Drain Soul, Drain Life, and Wrack spells a 4% chance to cause you to enter a Shadow Trance after damaging the opponent. The Shadow Trance reduces the casting time of your next Shadow Bolt spell by 100%." }, { "Curse of Exhaustion", "spell_shadow_grimward", 4, 3, 1, "Amplify Curse", "Reduces the target's movement speed by 30% for 12 sec. Only one Curse per Warlock can be active on any one target." }, { "Siphon Life", "spell_shadow_requiem", 5, 2, 1, "", "Transfers 11 health from the target to the caster every 3 sec. Lasts 30 sec." }, { "Soul Siphon", "spell_shadow_lifedrain02", 5, 3, 3, "", "Increases the damage done or health drained by your Drain Life, Drain Soul, and Wrack spells by 12% per each of your Corruption, Siphon Life, and Bane of Agony effects active on the target, up to a maximum increase of 36%." }, { "Shadow Mastery", "spell_shadow_shadetruesight", 6, 3, 5, "", "Increases the damage dealt or life drained by your Shadow spells by 10%." }, { "Wrack", "ability_deathknight_hemorrhagicfever", 7, 2, 1, "Siphon Life", "Tears the target apart from within for 6 sec, inflicting 60 Shadow damage every 1 sec. While channeling, your Siphon Life, Corruption, and Bane of Agony effects on the target deal their periodic damage 100% faster." } } }, { "Demonology", { { "Improved Health Funnel", "spell_shadow_lifedrain", 1, 1, 2, "", "Increases the amount of health transferred by your Health Funnel spell by 40%, reduces its health cost by 30%, and reduces all threat your Health Funnel generates by 100%. Allows Health Funnel to be used regardless of your demon's health." }, { "Improved Imp", "spell_shadow_summonimp", 1, 2, 3, "", "Increases the damage of your Imp's Firebolt spell by 30% and the effect of its Fire Shield spell by 30%." }, { "Demonic Embrace", "spell_shadow_metamorphosis", 1, 3, 5, "", "Increases your total Stamina by 15%." }, { "Unholy Power", "spell_shadow_shadowworddominate", 1, 4, 5, "", "Increases all damage done by your Imp, Voidwalker, Succubus, Incubus, and Felhunter pets by 10%." }, { "Demonic Aegis", "spell_shadow_ragingscream", 2, 1, 2, "", "Increases the effectiveness of your Demon Skin and Demon Armor spells by 30%." }, { "Improved Voidwalker", "spell_shadow_summonvoidwalker", 2, 2, 3, "", "Increases the effectiveness of your Voidwalker's Torment, Consume Shadows, Sacrifice, and Suffering spells by 30%." }, { "Fel Vitality", "spell_shadow_demonictactics", 2, 3, 3, "", "Increases the maximum health and Mana of your Imp, Voidwalker, Succubus, Incubus, and Felhunter by 15%, and increases your maximum Mana by 15%." }, { "Demonic Energies", "spell_shadow_felmending", 2, 4, 2, "", "You heal your pet for 15% of all spell damage you deal. When you gain Mana from Life Tap, your summoned demon gains 100% of the Mana you gain." }, { "Improved Sayaad", "ability_warlock_randomizesuccubusincubus", 3, 1, 3, "", "Increases the effect of your Succubus' and Incubus' Lash of Pain and Soothing Kiss spells by 30%, and increases the duration of your Succubus' and Incubus' Seduction and Lesser Invisibility spells by 30%." }, { "Demonic Sacrifice", "spell_shadow_psychicscream", 3, 2, 1, "", "When activated, sacrifices your summoned Demon to enhance the opposing aspect of your power, granting you an effect that lasts 2 hr. The effect is canceled if any Demon is summoned.\n\nImp: Increases your Shadow damage by 15%.\n\nVoidwalker: Restores 2% of your total Mana every 4 sec.\n\nSuccubus/Incubus: Increases your Fire damage by 15%.\n\nFelhunter: Restores 3% of your total Health every 4 sec." }, { "Master Summoner", "spell_shadow_impphaseshift", 3, 3, 2, "", "Reduces the casting time of your Imp, Voidwalker, Succubus, Incubus, and Felhunter Summoning spells by 4 sec and the Mana cost by 40%." }, { "Decimation", "spell_fire_fireball02", 4, 1, 2, "", "Reduces the cooldown of your Soul Fire spell by 90%. When you cast Shadow Bolt or Searing Pain on an enemy below 35% health, they deal 6% increased damage, and for the next 10 sec your Soul Fire spell has its cast time reduced by 40% and costs no Soul Shards." }, { "Fel Domination", "spell_nature_removecurse", 4, 3, 1, "Master Summoner", "Your next Imp, Voidwalker, Succubus, Incubus, or Felhunter Summon spell has its casting time reduced by 5.5 sec and its Mana cost reduced by 50%." }, { "Demonic Brand", "ability_demonhunter_chaoticimprint_fire", 4, 4, 3, "", "Your Searing Pain generates 50% less threat and brands the target for 10 sec. Your pet's next 6 attacks against the target deal 1 to 1 Fire or Shadow damage based on the pet. If Shadow damage is dealt, it has high threat." }, { "Improved Felhunter", "spell_shadow_summonfelhunter", 5, 1, 3, "", "Increases the Attack Power reduction of your Felhunter's Tainted Blood, the healing of its Devour Magic, and the detection level of its Paranoia by 30%, and reduces the cooldown of its Spell Lock by 6 sec." }, { "Soul Link", "spell_shadow_gathershadows", 5, 2, 1, "Demonic Sacrifice", "When active, 30% of all damage taken by the caster is taken by your Imp, Voidwalker, Succubus, Incubus, or Felhunter Demon instead. In addition, both the Demon and the master will inflict 3% more damage. Lasts as long as the Demon is active." }, { "Demonic Knowledge", "spell_shadow_improvedvampiricembrace", 5, 3, 3, "", "Increases your spell damage and your Demon pet's spell damage by up to 100% of your level while you have a summoned Demon pet active." }, { "Master Demonologist", "spell_shadow_shadowpact", 6, 3, 5, "", "Grants both the Warlock and the summoned demon an effect as long as that demon is active.\n\nImp - Increases Fire damage done by 10%.\n\nVoidwalker - Reduces Physical damage taken by 10%.\n\nSuccubus/Incubus - Increases Shadow damage done by 10%.\n\nFelhunter - Reduces Magic damage taken by 10%." }, { "Demonic Pact", "inv_ability_soulharvesterwarlock_demonicsoul", 7, 2, 1, "Soul Link", "Your Demonic Sacrifice effect is no longer cancelled by summoning a different Demon pet. Resummoning the sacrificed pet will still cancel the effect." } } }, { "Destruction", { { "Destructive Reach", "spell_shadow_corpseexplode", 1, 1, 2, "", "Increases the range of your Destruction spells by 20%." }, { "Improved Shadow Bolt", "spell_shadow_shadowbolt", 1, 2, 5, "", "Your Shadow Bolt critical strikes increase Shadow damage taken by the target from your attacks by 20% for 12 sec." }, { "Bane", "spell_shadow_deathpact", 1, 3, 5, "", "Reduces the casting time of your Shadow Bolt, Immolate, and Incinerate spells by 0.5 sec and your Soul Fire spell by 2 sec." }, { "Molten Skin", "ability_mage_moltenarmor", 2, 1, 5, "", "Reduces all damage taken by 10%." }, { "Cataclysm", "spell_fire_windsofwoe", 2, 2, 3, "", "Reduces the Mana cost of your Destruction spells by 10%." }, { "Aftermath", "spell_fire_fire", 2, 3, 5, "", "Increases the initial damage of your Immolate spell by 50% and your Conflagrate spell has a 100% chance to Daze the target, reducing the target's movement speed by 50% for 5 sec." }, { "Ruin", "spell_shadow_shadowwordpain", 3, 2, 5, "", "Increases the critical strike damage bonus of your Destruction spells by 100%." }, { "Shadowburn", "spell_shadow_scourgebuild", 3, 3, 1, "", "Instantly blasts the target for 65 to 74 Shadow damage. If a non-trivial target dies within 8 sec of being hit with Shadowburn, the caster gains a Soul Shard." }, { "Intensity", "spell_fire_lavaspawn", 4, 1, 3, "", "Gives your Destruction spells a 70% chance to not lose casting time when you take damage." }, { "Agonizing Flames", "spell_fire_soulburn", 4, 2, 3, "", "Increases the critical strike chance of your Searing Pain spell by 10% and the damage done by all your Destruction spells by 10%." }, { "Conflagrate", "spell_fire_fireball", 4, 3, 1, "", "Ignites a target that is already afflicted by your Immolate spell, dealing 88 to 111 Fire damage and consuming your Immolate effect." }, { "Pyroclasm", "spell_fire_volcano", 5, 1, 2, "Intensity", "Gives your Soul Fire spell a 26% chance to Stun the target for 3 sec, and your Rain of Fire and Hellfire spells a 26% chance over their duration to Stun targets they damage for 3 sec." }, { "Bane of Havoc", "ability_warlock_baneofhavoc", 5, 2, 1, "", "Afflicts the target for 5 min, causing 15% of all damage done by the Warlock to other targets to also be dealt to the cursed target. Bane of Havoc is limited to 1 target, and only one Bane per Warlock can be active on any one target." }, { "Fire and Brimstone", "spell_fire_meteorstorm", 5, 3, 3, "Conflagrate", "Increases the critical strike chance of your Conflagrate spell by 25%." }, { "Shadow and Flame", "spell_fire_playingwithfire", 6, 3, 5, "", "Hitting an enemy with Conflagrate increases all Shadow damage you deal by 20% for 20 sec, and hitting an enemy with Shadowburn increases all Fire damage you deal by 20% for 20 sec. In addition, Conflagrate has a 100% chance not to consume Immolate, and Shadowburn has a 100% chance to instantly refund a Soul Shard." }, { "Incinerate", "spell_fire_burnout", 7, 2, 1, "Bane of Havoc", "Deals 100 to 114 Fire damage to your target and an additional 25% damage if the target is afflicted by Immolate." } } } },
  warrior = { { "Arms", { { "Improved Heroic Strike", "ability_rogue_ambush", 1, 1, 3, "", "Reduces the cost of your Heroic Strike ability by 3 Rage." }, { "Deflection", "ability_parry", 1, 2, 5, "", "Increases your Parry chance by 5%." }, { "Improved Rend", "ability_gouge", 1, 3, 3, "", "Increases the Bleed damage done by your Rend ability by 35%." }, { "Improved Charge", "ability_warrior_charge", 2, 1, 2, "", "Increases the Rage generated by your Charge ability by 6." }, { "Improved Tactical Mastery", "spell_nature_enchantarmor", 2, 2, 3, "", "Tactical Mastery lets you retain up to an additional 15 Rage when you change stances." }, { "Improved Overpower", "inv_sword_05", 2, 4, 2, "", "Increases the critical strike chance of your Overpower ability by 50%." }, { "Anger Management", "spell_holy_blessingofstamina", 3, 2, 1, "Improved Tactical Mastery", "Generates 1 Rage every 3 sec while in combat, and reduces Rage loss while out of combat by 30%." }, { "Deep Wounds", "ability_backstab", 3, 3, 3, "Improved Rend", "Your critical strikes cause your opponent to Bleed, dealing 60% of your melee weapon's average damage over 12 sec." }, { "Spearing Strike", "inv_spear_01", 4, 1, 1, "", "A brutal attack that deals 75% weapon damage. Deals an additional 75% weapon damage against Giants, Dragonkin, and mounted targets. Mounted targets are dismounted." }, { "Two-Handed Weapon Specialization", "inv_axe_09", 4, 2, 3, "", "Increases the damage you deal with two-handed melee weapons by 6%." }, { "Impale", "ability_searingarrow", 4, 3, 2, "Deep Wounds", "Increases the critical strike damage bonus of your abilities by 20%." }, { "Bloodthrill", "inv_sword_01", 5, 1, 2, "", "Grants your Main Hand melee attacks against enemies afflicted by your Rend a 20% chance to allow an activation of Overpower." }, { "Sweeping Strikes", "ability_rogue_slicedice", 5, 2, 1, "", "Your next 5 melee attacks strike an additional nearby opponent." }, { "Weaponmaster", "garrison_weaponupgrade", 5, 3, 5, "", "Gives your melee weapon attacks a benefit depending on the weapon.\n\nAxe/Polearm: Increases your\ncritical strike chance by 5%.\n\nMace/Staff: Your attacks ignore\n15% of your target's armor.\n\nSword: Your successful melee\nattacks have a 5% chance to\ntrigger an extra attack on the\ntarget." }, { "Improved Slam", "ability_warrior_decisivestrike", 6, 1, 2, "", "Reduces the cooldown of your Slam ability by 5.0 sec, the cast time and global cooldown by 0.50 sec, and Slam no longer interrupts or delays your melee swing." }, { "Improved Hamstring", "ability_shockwave", 6, 3, 3, "", "Gives your Hamstring ability a 15% chance to immobilize the target for 5 sec." }, { "Mortal Strike", "ability_warrior_savageblow", 7, 2, 1, "Sweeping Strikes", "A vicious strike that deals weapon damage plus 85 and wounds the target, reducing the effectiveness of any healing by 50% for 10 sec." } } }, { "Fury", { { "Booming Voice", "spell_nature_purge", 1, 2, 5, "", "Increases the area of effect of your Shouts by 50% and reduces the Rage cost by of your Shouts and Howls by 25%." }, { "Cruelty", "ability_rogue_eviscerate", 1, 3, 5, "", "Improves your chance to get a critical strike with melee attacks by 5%." }, { "Lingering Rage", "ability_warrior_secondwind", 2, 2, 5, "", "Increases the time before your Rage begins to decay after leaving combat by 10 sec." }, { "Unbridled Wrath", "spell_nature_stoneclawtotem", 2, 3, 5, "", "Gives you a 60% chance to generate 1 additional Rage when you deal melee damage with a weapon." }, { "Furious Precision", "ability_warrior_incite", 3, 1, 3, "", "Increases your chance to hit with off-hand attacks by 10%." }, { "Piercing Howl", "spell_shadow_deathscream", 3, 2, 1, "", "Causes all enemies within 10 yds to be Dazed, reducing movement speed by 50% for 6 sec." }, { "Blood Craze", "spell_shadow_summonimp", 3, 3, 3, "", "Regenerates 3% of your total Health over 6 sec after being the victim of a critical strike or suffering more than 20% of your maximum Health from a single attack." }, { "Enrage", "spell_shadow_unholyfrenzy", 3, 4, 5, "", "Gives you a 30% chance to deal 10% increased Physical damage for 12 sec after being the victim of any damaging attack." }, { "Dual Wield Specialization", "ability_dualwield", 4, 1, 5, "", "Increases the damage done by your off-hand weapon by 25% and the Rage generated by your off-hand attacks by 50%." }, { "Reckless Swings", "ability_warrior_bloodfrenzy", 4, 2, 1, "", "Your next 4 melee attacks generate 5 additional Rage. Lasts 8 sec." }, { "Improved Execute", "inv_sword_48", 4, 4, 2, "", "Reduces the Rage cost of your Execute ability by 5." }, { "Improved Berserker Rage", "spell_nature_ancestralguardian", 5, 1, 2, "", "Your Berserker Rage ability will instantly generate 10 Rage and has a 100% chance to remove all movement impairing effects when activated." }, { "Death Wish", "spell_shadow_deathpact", 5, 2, 1, "", "When activated, increases your Physical damage done by 20% and makes you immune to Fear effects, but increases all damage you take by 5%. Lasts 30 sec." }, { "Gore Drinker", "racial_troll_berserk", 5, 3, 2, "Blood Craze", "Your Enrage, Berserker Rage, Bloodrage, Death Wish, Reckless Swings, and Bloodthirst abilities cause your next 3 melee attacks to restore 1.0% of your maximum Health." }, { "Improved Intercept", "ability_rogue_sprint", 5, 4, 2, "", "Reduces the cooldown of your Intercept ability by 10 sec." }, { "Improved Whirlwind", "ability_whirlwind", 6, 1, 2, "", "Reduces the cooldown of your Whirlwind ability by 2 sec and increases the damage it deals to the closest enemy by 30%." }, { "Flurry", "ability_ghoulfrenzy", 6, 3, 3, "", "Increases your melee attack speed by 30% for your next 3 swings after dealing a melee critical strike." }, { "Bloodthirst", "spell_nature_bloodlust", 7, 2, 1, "Death Wish", "Instantly attack the target causing damage equal to 45% of your Attack Power plus 30 and increasing your movement speed by 10% for 10 sec." } } }, { "Protection", { { "Improved Bloodrage", "ability_racial_bloodrage", 1, 1, 2, "", "Increases all the Rage generated by your Bloodrage ability by 50%." }, { "Shield Specialization", "inv_shield_06", 1, 2, 5, "", "Increases your chance to Block attacks with your shield by 5% and grants you a 100% chance to generate 5 Rage when you Block." }, { "Iron Will", "spell_magic_magearmor", 1, 3, 5, "", "Reduces the duration of Stun and Fear effects inflicted on you by 15%." }, { "Anticipation", "spell_nature_mirrorimage", 2, 1, 5, "", "Increases your Defense Skill by 20." }, { "Improved Revenge", "ability_warrior_revenge", 2, 3, 3, "", "Increases damage dealt by your Revenge ability by 60%." }, { "Improved Thunder Clap", "ability_thunderclap", 2, 4, 3, "", "Reduces the Rage cost of your Thunder Clap ability by 6." }, { "Last Stand", "spell_holy_ashestoashes", 3, 1, 1, "", "When activated, this ability temporarily grants you 30% of your maximum health for 20 sec. After the effect expires, the health is lost." }, { "Master of Defense", "ability_warrior_shieldguard", 3, 2, 2, "Shield Specialization", "Grants you a 100% chance to generate 5 Rage when you Dodge or Parry while a shield is equipped." }, { "Improved Disarm", "ability_warrior_disarm", 3, 3, 3, "", "Reduces the cooldown of your Disarm ability by 20 secs." }, { "Defiance", "ability_warrior_innerrage", 3, 4, 3, "", "Increases all threat generated in Defensive stance by an additional 20% while a shield is equipped." }, { "Improved Sunder Armor", "ability_warrior_sunder", 4, 1, 3, "", "Reduces the Rage cost of your Sunder Armor ability by 3." }, { "Vanguard", "ability_warrior_shieldcharge", 4, 2, 1, "", "Your Charge ability is now usable while in Defensive Stance." }, { "Improved Shield Bash", "ability_warrior_shieldbash", 4, 3, 2, "", "Gives your Shield Bash ability a 100% chance to Silence the target for 3 sec." }, { "Improved Shield Wall", "ability_warrior_shieldwall", 5, 1, 2, "", "Reduces the cooldown of your Shield Wall ability by 11.0 min." }, { "Concussion Blow", "ability_thunderbolt", 5, 2, 1, "", "Stuns the target for 5 sec." }, { "Focused Rage", "ability_warrior_focusedrage", 5, 3, 3, "", "Reduces the Rage cost of your offensive abilities by 3." }, { "Bastion", "inv_shield_04", 6, 3, 5, "", "Increases all damage you deal by 10% while a shield is equipped." }, { "Shield Slam", "inv_shield_05", 7, 2, 1, "Concussion Blow", "Slam the target with your shield, causing 421 to 439 damage, increased by your Block Value, and has a 50% chance of dispelling 1 magic effect on the target. Causes a very high amount of threat." } } } },
}
ForeverPathfinderClass = {
 it = {
  druid = { why = { ["Ferocity"] = "Costo di Maul, Swipe, Claw e Rake 5 Rage/Energy a 5/5: in Bear Form più Maul, in Cat Form rotazione molto più economica. Unanimità delle fonti: primo talent.", ["Feral Instinct"] = "Swipe +30% e stealth come +3 livelli: con Swipe (16) è il tuo AoE da Bear nel 10–19 (Mobalytics bear + wowforever.be).", ["Feral Swiftness"] = "+30% velocità in Cat Form (anche indoor) e +4% Dodge: 'uno dei migliori talent per il leveling' (Mobalytics, games.gg, Warcraft Tavern).", ["Feral Charge"] = "Da Bear: root + interrupt 4 s; da Cat: salto dietro il bersaglio (apre con Shred, CD 30 s). Il pezzo di mobilità del 20.", ["Savage Fury"] = "+10% danno a Claw, Rake, Shred, Maul, Swipe: danno puro su tutto il kit (prerequisito di Lacerate).", ["Shredding Attacks"] = "Shred costa 18 Energy in meno a 3/3 (e Lacerate 3 Rage): Shred diventa la tua rotazione da dietro il mob.", ["Sharpened Claws"] = "+6% crit in Bear e Cat Form a 2/2: più crit = più Combo Point extra con Blood Frenzy (prerequisito).", ["Lacerate"] = "Bleed stackabile fino a 5 (10% weapon damage per stack), tanta threat: utile come Bear in dungeon; in solo cat vale poco ( scelta di wowforever.be).", ["Predatory Discipline"] = "Ferocious Bite non converte più Energy extra ma fa danno extra in base all'Energy in eccesso: finisher più semplice.", ["Leader of the Pack"] = "+3% crit a te e al party in Cat/Bear Form, ora su tutti i crit (hotfix 30 ott). Il talent del 30 per tutte le fonti.", ["Natural Instinct"] = "+20% crit damage delle abilità melee a 2/2 (e healing da Intellect).", ["Blood Frenzy"] = "100% di +5 Rage sui crit in Bear Form; da Cat i crit dei builder danno un Combo Point extra al 100%.", ["Furor"] = "Cambiare forma ti dà 10 Rage in Bear e ti ridà l'Energy in Cat: passi da una forma all'altra senza perdere ritmo (yumytv, 13–17).", ["Primal Bite"] = "Morso con 42/62/77 di danno extra e tanta threat (hotfix 30 ott), spostato a riga 7: serve 30 punti nell'albero, quindi arriva al 40.", ["Shifting Power"] = "Converte 55% del Base Mana in 40 Energy (CD 8 s dopo hotfix 30 ott): Mana come seconda barra Energy. Riga 7 = livello 41 nel client.", ["Brutal Impact"] = "Bash e Pounce stunnano +1 s e Bash 30 s di CD: controllo extra per i pull difficili.", ["Heart of the Wild"] = "+10% Intellect, +20% Stamina in Bear, +10% Strength in Cat a 5/5. Dopo l'hotfix è nell'albero Restoration, perciò arriva dopo il 44.", ["Natural Shapeshifter"] = "30% costo mana di tutte le trasformazioni: meno tempo a bere se cambi forma spesso.", ["Naturalist"] = "+10% a tutto il danno che infliggi (e Healing Touch/Wild Growth più veloci): danno extra gratis nel Resto.", ["Reflection"] = "Fino al 50% della rigenerazione mana continua mentre lanci: aiuta heal e shift.", ["Swiftmend"] = "Heal istantaneo che consuma il tuo Rejuvenation/Regrowth: capstone del 60 per curarti in solo.", ["Predatory Strikes"] = "Attack Power in Cat e Bear Form pari al 150% del tuo livello (3/3): più danno senza gear." },
   summary = "Feral (Cat dal 20, Bear se serve) è la spec di leveling in solo più consigliata: Warcraft Tavern (Luxrah) 'Feral cats will have the smoothest route', Method (BirraGzeez) 'la scelta più veloce e popolare', mmonster (tier list del 5 nov) e Mobalytics. Dal 6 nov la build A è quella di Mobalytics {yumytv} (299 , guida Druid 1–60 aggiornata dopo il lancio): Ferocity, Furor 5 (Energy e Rage quando cambi forma), Feral Swiftness, Sharpened Claws e Savage Fury, Feral Charge al 24, Leader of the Pack al 30, Shifting Power al 40; poi Balance (Genesis, Nature's Majesty) e Restoration (Heart of the Wild, Naturalist), 9/31/11 al 60. wowforever.be (dati client) fa 0/34/17.", bsum = { b = "Ti piace giocare caster con root e kiting dal range; non per il leveling più rapido." }, rot = { { "1–9 · Caster (nessuna forma)", { { "spell_nature_thorns", "Thorns (dal 6)" }, { "spell_nature_abolishmagic", "Wrath (pull)" }, { "spell_nature_starfall", "Moonfire" }, { "spell_nature_abolishmagic", "Wrath" }, { "ability_meleedamage", "Auto-attack" } }, "Thorns su di te. Wrath per ingaggiare, Moonfire per il DoT, Wrath finché hai mana, poi finisci in melee. Rejuvenation su di te quando serve. Con Moonfire puoi tenere il DoT su 2 mob (games.gg). Mana finito = auto-attack. Fonti: Warcraft Tavern, games.gg, Method." }, { "10–19 · Bear Form", { { "spell_nature_resistnature", "Heal pre-pull" }, { "ability_racial_bearform", "Bear Form" }, { "ability_druid_enrage", "Enrage" }, { "ability_druid_demoralizingroar", "Demoralizing Roar" }, { "ability_druid_maul", "Maul / Swipe" } }, "Prima del pull curati (Rejuvenation, Regrowth, Healing Touch), poi Wrath x2 + Moonfire da lontano e Bear Form quando il mob arriva (Method). Enrage per Rage subito, Demoralizing Roar solo su mob fisici, Maul su singolo, Swipe (16) su 2+ mob. Feral Charge arriva solo al 20 sulla build client (games.gg la anticipava: obsoleto). Non pullare più di 2 mob." }, { "20–29 · Cat Form", { { "ability_ambush", "Prowl" }, { "ability_druid_disembowel", "Rake" }, { "spell_shadow_vampiricaura", "Shred (da dietro)" }, { "ability_druid_rake", "Claw" }, { "ability_druid_ferociousbite", "Ferocious Bite (24, 5 CP)" } }, "Rejuvenation prima del pull, aspetta qualche secondo in Cat Form per riempire l'Energy. Prowl, poi Feral Charge dietro al mob o Shred da dietro; Faerie Fire per tirare da lontano; Rake se il mob vive più di ~6 s; Shred (Claw se non sei dietro) per i Combo Point; Dal 24 Ferocious Bite a 5 Combo Point con l'Energy piena (Mobalytics); Rip solo se il mob vive ancora 10 s. Dal 24 Tiger's Fury . Dash per spostarti. Non servono finisher sui mob che muoiono in 3 colpi. Fonti: Tavern, Method, games.gg." }, { "30–39 · Cat evoluto", { { "ability_ambush", "Prowl" }, { "ability_druid_ravage", "Ravage / Pounce" }, { "spell_nature_faeriefire", "Faerie Fire" }, { "ability_druid_disembowel", "Rake" }, { "ability_druid_ferociousbite", "Ferocious Bite (5 CP)" } }, "Ravage (32) o Pounce (36) da Prowl, Faerie Fire, Rake, Shred/Claw fino a 5 Combo Point, Ferocious Bite (con Predatory Discipline)." }, { "40–60 · Rotazione completa", { { "ability_ambush", "Prowl" }, { "ability_druid_ravage", "Ravage" }, { "spell_nature_faeriefire", "Faerie Fire" }, { "ability_druid_disembowel", "Rake" }, { "spell_druid_displacement", "Shifting Power" }, { "ability_druid_rake", "Claw" }, { "ability_druid_ferociousbite", "Ferocious Bite (5 CP)" } }, "Prowl dietro al mob, Ravage, Faerie Fire, Rake, Shifting Power (40: trasforma il Mana in 40 Energy), Claw fino a 5 Combo Point; a 5 punti aspetta l'Energy piena e usa Ferocious Bite, anche prima se finisce il mob. Shifting Power una volta per mob, così a fine combattimento il Mana si rigenera. Thorns e Mark of the Wild sempre attivi (Mobalytics – yumytv, 14 nov). Dal 40 Dire Bear Form per i dungeon e per più mob (Method)." }, { "AoE / pull multipli", { { "ability_racial_bearform", "Bear Form" }, { "ability_druid_enrage", "Enrage" }, { "ability_druid_demoralizingroar", "Demoralizing Roar" }, { "inv_misc_monsterclaw_03", "Swipe" } }, "Più di 2 mob: Bear Form, Enrage, Roar (solo fisici), Swipe (Feral Instinct +30%). Entangling Roots tiene fuori un extra; Nature's Grasp per scappare; Bash per fermare un mob. Da Cat non c'è AoE: con 3+ mob passa a Bear." } },
   brot = { b = { { "Single target · Eclipse", { { "spell_nature_abolishmagic", "Wrath" }, { "spell_arcane_starfire", "Starfire" }, { "spell_nature_starfall", "Moonfire" }, { "spell_nature_insectswarm", "Insect Swarm" } }, "Build Eclipse (Tavern): Starfire e Wrath single target. Moonfire e Insect Swarm tengono il DoT; Insect Swarm dal 25." }, { "Mob in arrivo · Root e kiting", { { "spell_nature_stranglevines", "Entangling Roots" }, { "spell_nature_starfall", "Moonfire" } }, "Root dal range e kiting: Tavern: il kiting è un punto forte del Druid; rootare dal range fa perdere al mob tempo senza farti danno." } } },
   notes = { { "Risorse e downtime", "• {Mana} continua a rigenerare in forma ma è nascosto: attiva 'Personal Resource Display' in Options, Combat (Tavern). Il Mana serve per tornare in forma (lo shift costa Mana; Natural Shapeshifter 30%) e per Shifting Power.\n• Energy e Rage si rigenerano in continuo; in Bear l'Energy non rigenera, e Powershifting/Bear Weaving non convengono più (Tavern). Furor ridà la risorsa quando cambi forma.\n• Pozioni, bende e cibo si usano senza uscire dalla forma (1–8 ott); la maggior parte di oggetti e NPC è usabile in forma, ma heal e utility (Rebirth, Innervate, Cure Poison) richiedono di uscirne.\n• Heal tra un pull e l'altro: Rejuvenation (Swiftmend solo al 60). Porta acqua adatta al livello (nuova ogni ~10 livelli).\n• Il cambio forma toglie root e slow: shifta invece di aspettare.\n• Idol of Shifting Tides (quest Aquatic Form): meno mana per shapeshift." }, { "Posizione e Combo Point", "Shred richiede di stare dietro al mob; da dietro non vieni parato né colpito dagli attacchi frontali. Feral Charge da Cat ti mette dietro automaticamente. Combo Point: Tavern dice che non si trasferiscono tra target, games.gg (17 set) che sì: verifica in gioco. I bleed ignorano l'armor: ottimi contro mob corazzati." } }, stats = "Priorità Feral: Strength / Agility / Attack Power > Stamina / Intellect / Spirit > Armor (Tavern, Mid-level Feral); games.gg: Strength > Agility = Stamina > Intellect > Spirit; wow.gg: Weapon Damage > Hit/Expertise > Crit. Prima del 10 (e da Balance): Intellect/Spell Damage. In Forever gli attacchi in Cat/Bear scalano con il DPS dell'arma (velocità 1.0 o 2.5 s a seconda della forma): l'arma col DPS più alto è il miglior upgrade. Polearms dal 20; anche Daggers, Fist Weapons, One/Two-Handed Maces, Staves (trainer arma a Ironforge, Thunder Bluff, Orgrimmar, Undercity, Stormwind). Item citati: Wolfshead Helm (Leatherworking), Manual Crowd Pummeler (Gnomeregan 29–38), Embrace of the Viper (set, Wailing Caverns 17–24, trasforma anche la Cat Form), Idol of Shifting Tides (quest Aquatic Form). Livelli e requisiti dei crafting non letti .", forever = { "30 ott (build 70707; wowforever.be news 31 ott, GitHub #455, Tactyks 15.8k views 31 ott): albero Druid rimescolato: Berserk rimosso, Furor/Heart of the Wild scambiati d'albero, Primal Bite 42/62/77 spostato a riga 7, Shifting Power CD 8 s, Leader of the Pack su tutti i crit, nuovi Lacerate/Predatory Discipline/Bloom.", "Pozioni e consumabili (anche Thistle Tea e mana potion) usabili in Bear/Cat senza uscire dalla forma; enchant arma e proc funzionano in forma; immuni a Disarm (1–8 ott, wofwforever 15 ott).", "Auto-attack da forma usa il DPS dell'arma (1.0 s Cat / 2.5 s Bear); Polearms nuovi al 20.", "Powershifting e Bear Weaving non più convenienti; Furor ridà il 100% dell'Energy al cambio (Tavern, 15 ott).", "Nature's Grasp (10), Revive (12), Omen of Clarity (20, passiva), Faerie Fire e Shred (20, 15 ott) base; Dual Talent Specialization al 40.", "Claw ~110% weapon damage (come Mangle), Shred 155% (da 225%), Tiger's Fury +15% danno 6 s , Enrage 30 Rage totali, Frenzied Regeneration a %, tutti i DoT possono fare crit (KamiLabs, 26 set; non riverificato sul client).", "Cat Form non abbassa più gli HP massimi (8 ott), +50% threat da Bear (8 ott), Faerie Fire senza costo e 6 s CD in forma con threat (15 ott).", "Talented (Legacy): talent point dal livello 5 invece del 10 (client spell 1225474; Tavern: fino a 5 livelli prima).", "Nuova race Skyborne (Zephras Isle 3–12, trainer Druid in loco) con quest di forme dedicate.", "Al lancio (note Blizzard del 3 nov): Claw 140% del danno dell'arma, Shred 200%, Ravage 435%; Rip, Rake, Pounce e Ferocious Bite circa +25%; Starfire circa +40%; Dire Bear Form +115% di threat; Rend and Tear fino al 15%." },
   races = { ["nightelf"] = "Alleanza. Elune's Light (+10% crit per 15 s, burst), Shadowmeld, Quickness (+1% Dodge, +2% velocità), Wisp Spirit. games.gg: 'il migliore per parse, vicino al Tauren'; Method: scelta all-around dell'Alleanza. Quest druid a Darnassus.", ["tauren"] = "Horde. War Stomp (stun 2 s su 5 nemici, CD 90 s, usabile in forma ), Cultivation (duplica un'erba, CD 15 min), Plainsrunning (+1% velocità ogni 5 s fino a +30%, +3% mounted), Endurance (+5% HP e +1% Hit). games.gg: 'la più forte' per Druid; Method: ideale per Bear tank e PvP. Quest a Thunder Bluff.", ["skyborne_a"] = "High Order (Alleanza). Walk on Air (slow fall, CD 90 s), Wind Blessed (+1–2% haste numeri discordanti), Elemental Insight (+5% danno vs Elemental), Read Ley Line (+50%/100% regen HP e Mana per 15 s, CD 2 min, non si somma a Innervate: riduce il downtime tra i pull). Si parte a Zephras Isle (3–12).", ["skyborne_h"] = "Windshaper (Horde). Walk on Air, Wind Blessed, Elemental Insight, Skysight (+10–15% velocità, 15 s, CD 2 min numeri discordanti). Method: Windshaper ottimo per Feral Cat e Balance grazie all'haste. Zephras Isle, poi trainer a Dalaran (Alfina Nightgaze) per la Horde." },
   spells = { { 1, "Mark of the Wild", "spell_nature_regeneration", "Buff stats e resistenze a te e al party; tienilo sempre su (funziona anche sui pet).", false }, { 1, "Wrath", "spell_nature_abolishmagic", "Danno Nature con cast; il tuo attacco da pull fino al 10.", false }, { 1, "Healing Touch", "spell_nature_healingtouch", "Heal con cast: cura fuori forma tra un pull e l'altro.", false }, { 4, "Moonfire", "spell_nature_starfall", "Danno Arcane + DoT, può fare crit (anche il DoT). Tienilo su 2 mob.", false }, { 4, "Rejuvenation", "spell_nature_rejuvenation", "HoT: ti curi prima di ogni pull.", false }, { 6, "Thorns", "spell_nature_thorns", "Danni a chi ti colpisce; scala con lo spell power. Tienilo sempre su di te.", false }, { 8, "Entangling Roots", "spell_nature_stranglevines", "Root a distanza per tenere lontano un mob extra.", false }, { 10, "Bear Form", "ability_racial_bearform", "Class quest (vedi tappe). Armor e HP alti, Rage come risorsa; un po' meno HP che in Classic.", false }, { 10, "Growl", "ability_physical_taunt", "Taunt singolo (dalla quest di Bear Form).", false }, { 10, "Maul", "ability_druid_maul", "Il tuo spender di Rage a bersaglio singolo (dalla quest).", false }, { 10, "Demoralizing Roar", "ability_druid_demoralizingroar", "Debuff che riduce il danno dei mob fisici; non usarlo sui caster.", false }, { 10, "Nature's Grasp", "spell_nature_natureswrath", "Ora base al 10: roota il prossimo che ti colpisce in melee, per scappare.", false }, { 10, "Teleport: Moonglade", "spell_arcane_teleportmoonglade", "Class quest: teletrasporto a Moonglade (trainer Loganaar a Nighthaven).", false }, { 12, "Regrowth", "spell_nature_resistnature", "Heal + HoT, più veloce di Healing Touch.", false }, { 12, "Revive", "spell_nature_reincarnation", "Ora base al 12: resuscita un giocatore fuori combattimento.", false }, { 12, "Enrage", "ability_druid_enrage", "10 Rage subito + 20 in 10 s (totale 30), CD 1 min; da Bear.", false }, { 14, "Cure Poison", "spell_nature_nullifypoison", "Class quest 'Lessons Anew': rimuove un Poison.", false }, { 14, "Bash", "ability_druid_bash", "Stun da Bear; con Brutal Impact stunna più a lungo e ha CD più corto.", false }, { 16, "Aquatic Form", "ability_druid_aquaticform", "Class quest 'A Lesson to Learn': nuoto veloce e respiro infinito. Ricompensa: Idol of Shifting Tides.", false }, { 16, "Swipe", "inv_misc_monsterclaw_03", "Il tuo AoE da Bear; Feral Instinct +30%.", false }, { 18, "Faerie Fire", "spell_nature_faeriefire", "Base (niente talent): debuff armor, pull a distanza; in forma costa 0, CD 6 s e dà threat (15 ott).", false }, { 18, "Hibernate", "spell_nature_sleep", "Crowd control su Beast e Dragonkin (dato Classic).", false }, { 20, "Cat Form", "ability_druid_catform", "Class quest 'The Great Cat Spirit': DPS melee con Energy e Combo Point. Non abbassa più gli HP massimi.", false }, { 20, "Claw", "ability_druid_rake", "Builder Combo Point (dalla quest); ora ~110% weapon damage come Mangle (KamiLabs, 26 set).", false }, { 20, "Prowl", "ability_ambush", "Stealth in Cat Form: scegli tu quando ingaggiare.", false }, { 20, "Rip", "ability_ghoulfrenzy", "Finisher bleed (dalla quest); usalo solo se il mob vive abbastanza.", false }, { 20, "Shred", "spell_shadow_vampiricaura", "Rank 1 al 20 (era 22, 15 ott): builder da dietro, ~155% weapon damage.", false }, { 20, "Starfire", "spell_arcane_starfire", "Danno Arcane con cast lungo (per Balance, raramente per Feral).", false }, { 20, "Rebirth", "spell_nature_reincarnation", "Resurrezione in combattimento: consuma un reagente (dipende dal Rank).", false }, { 20, "Omen of Clarity", "spell_nature_crystalball", "Ora passiva base: proc di spell/abilità gratis, anche su tick di DoT/HoT.", false }, { 20, "Polearms", "ability_meleedamage", "Nuova arma per i Druid: Woo Ping (Stormwind) / Archibald (Undercity).", false }, { 22, "Soothe Animal", "ability_hunter_beastsoothe", "Calma un animale (dato Classic).", false }, { 24, "Remove Curse", "spell_nature_removecurse", "Rimuove un Curse.", false }, { 24, "Rake", "ability_druid_disembowel", "Builder + bleed: usalo se il mob vive più di ~6 s.", false }, { 24, "Tiger's Fury", "ability_mount_jungletiger", "(KamiLabs 26 set, non in Tavern/Method): +15% a tutto il danno per 6 s, DoT inclusi; livello da verificare.", false }, { 24, "Ferocious Bite", "ability_druid_ferociousbite", "Finisher da Cat; con Predatory Discipline fa danno extra sull'Energy in eccesso.", false }, { 24, "Feral Charge", "ability_hunter_pet_bear", "Bear: charge + root + interrupt 4 s; Cat: salta dietro il bersaglio (CD 30 s).", true }, { 26, "Dash", "ability_druid_dash", "Sprint in Cat Form.", false }, { 26, "Abolish Poison", "spell_nature_nullifypoison_02", "Poison rimosso nel tempo.", false }, { 28, "Cower", "ability_druid_cower", "Meno threat da Cat (utile in gruppo).", false }, { 28, "Challenging Roar", "ability_druid_challangingroar", "Taunt AoE da Bear, CD 10 min.", false }, { 30, "Travel Form", "ability_druid_travelform", "Corsa +40% all'aperto senza mount: sostituisce il mount fino al 40.", false }, { 30, "Tranquility", "spell_nature_tranquility", "Heal di gruppo in channel.", false }, { 30, "Leader of the Pack", "spell_nature_unyeildingstamina", "+3% crit a te e al party in Cat/Bear Form (aura).", true }, { 32, "Ravage", "ability_druid_ravage", "Opener da stealth da dietro (Cat).", false }, { 32, "Track Humanoids", "ability_tracking", "Tracking degli umanoidi in Cat Form.", false }, { 36, "Pounce", "ability_druid_supriseattack", "Opener da Prowl con stun.", false }, { 36, "Frenzied Regeneration", "ability_bullrush", "Converte Rage in HP in percentuale (10 Rage = 10% HP).", false }, { 40, "Dire Bear Form", "ability_racial_bearform", "Forma da Bear migliorata (trainer).", false }, { 40, "Innervate", "spell_nature_lightning", "Mana regen potente; esci dalla forma per lanciarlo.", false }, { 40, "Hurricane", "spell_nature_cyclone", "Senza cooldown (Balance).", false }, { 40, "Feline Grace", "ability_druid_catform", "Passiva da Cat (trainer, dato Tavern; effetto non letto ).", false }, { 40, "Dual Talent Specialization", "inv_misc_book_09", "Seconda spec (es. Feral + Restoration per i dungeon).", false }, { 40, "Shifting Power", "spell_druid_displacement", "55% del Base Mana in 40 Energy, CD 8 s (da Cat).", true }, { 44, "Barkskin", "spell_nature_stoneclawtotem", "Riduzione danno in ogni forma.", false } },
   bsp = { b = { { 1, "Mark of the Wild", "spell_nature_regeneration", "Buff stats e resistenze a te e al party; tienilo sempre su (funziona anche sui pet).", false }, { 1, "Wrath", "spell_nature_abolishmagic", "Danno Nature con cast; il tuo attacco da pull fino al 10.", false }, { 1, "Healing Touch", "spell_nature_healingtouch", "Heal con cast: cura fuori forma tra un pull e l'altro.", false }, { 4, "Moonfire", "spell_nature_starfall", "Danno Arcane + DoT, può fare crit (anche il DoT). Tienilo su 2 mob.", false }, { 4, "Rejuvenation", "spell_nature_rejuvenation", "HoT: ti curi prima di ogni pull.", false }, { 6, "Thorns", "spell_nature_thorns", "Danni a chi ti colpisce; scala con lo spell power. Tienilo sempre su di te.", false }, { 8, "Entangling Roots", "spell_nature_stranglevines", "Root a distanza per tenere lontano un mob extra.", false }, { 10, "Bear Form", "ability_racial_bearform", "Class quest (vedi tappe). Armor e HP alti, Rage come risorsa; un po' meno HP che in Classic.", false }, { 10, "Growl", "ability_physical_taunt", "Taunt singolo (dalla quest di Bear Form).", false }, { 10, "Maul", "ability_druid_maul", "Il tuo spender di Rage a bersaglio singolo (dalla quest).", false }, { 10, "Demoralizing Roar", "ability_druid_demoralizingroar", "Debuff che riduce il danno dei mob fisici; non usarlo sui caster.", false }, { 10, "Nature's Grasp", "spell_nature_natureswrath", "Ora base al 10: roota il prossimo che ti colpisce in melee, per scappare.", false }, { 10, "Teleport: Moonglade", "spell_arcane_teleportmoonglade", "Class quest: teletrasporto a Moonglade (trainer Loganaar a Nighthaven).", false }, { 12, "Regrowth", "spell_nature_resistnature", "Heal + HoT, più veloce di Healing Touch.", false }, { 12, "Revive", "spell_nature_reincarnation", "Ora base al 12: resuscita un giocatore fuori combattimento.", false }, { 12, "Enrage", "ability_druid_enrage", "10 Rage subito + 20 in 10 s (totale 30), CD 1 min; da Bear.", false }, { 14, "Cure Poison", "spell_nature_