, { 24, "Rake", "ability_druid_disembowel", "Builder + bleed: use it if the mob lives longer than ~6 s.", false }, { 24, "Tiger's Fury", "ability_mount_jungletiger", "(KamiLabs Sep 26, not in Tavern/Method): +15% to all damage for 6 s, DoTs included; level to be verified.", false }, { 24, "Ferocious Bite", "ability_druid_ferociousbite", "Finisher from Cat; with Predatory Discipline it deals extra damage based on excess Energy.", false }, { 25, "Insect Swarm (talent)", "spell_nature_insectswarm", "", true }, { 26, "Dash", "ability_druid_dash", "Sprint in Cat Form.", false }, { 26, "Abolish Poison", "spell_nature_nullifypoison_02", "Removes Poison over time.", false }, { 28, "Cower", "ability_druid_cower", "Less threat from Cat (useful in groups).", false }, { 28, "Challenging Roar", "ability_druid_challangingroar", "AoE taunt from Bear, 10 min CD.", false }, { 30, "Travel Form", "ability_druid_travelform", "+40% outdoor running speed without a mount: replaces a mount until 40.", false }, { 30, "Tranquility", "spell_nature_tranquility", "Group heal in a channel.", false }, { 32, "Ravage", "ability_druid_ravage", "Stealth opener from behind (Cat).", false }, { 32, "Track Humanoids", "ability_tracking", "Humanoid tracking in Cat Form.", false }, { 36, "Pounce", "ability_druid_supriseattack", "Opener from Prowl with stun.", false }, { 36, "Frenzied Regeneration", "ability_bullrush", "Converts Rage into HP as a percentage (10 Rage = 10% HP).", false }, { 40, "Dire Bear Form", "ability_racial_bearform", "Improved Bear Form (trainer).", false }, { 40, "Innervate", "spell_nature_lightning", "Powerful mana regen; leave form to cast it.", false }, { 40, "Hurricane", "spell_nature_cyclone", "No cooldown (Balance).", false }, { 40, "Feline Grace", "ability_druid_catform", "Cat passive (trainer, Tavern data; effect not read ).", false }, { 40, "Dual Talent Specialization", "inv_misc_book_09", "Second spec (e.g. Feral + Restoration for dungeons).", false }, { 40, "Moonkin Form (talent)", "spell_nature_forceofnature", "", true }, { 44, "Barkskin", "spell_nature_stoneclawtotem", "Damage reduction in every form.", false } } } },
  hunter = { why = { ["Deadly Aspects"] = "With Aspect of the Hawk active, Auto Shot has 2% per rank (10% at rank 5) to give +30% ranged attack speed for 12 s: it's your base damage. All good sources take it first.", ["Focused Fire"] = "+1% per rank (2% max) to all your and your Pet's damage while the Pet is active.", ["Improved Revive Pet"] = "Revive Pet 3/6 s faster and 20/40% Mana: after your Pet dies you lose less time. The 2nd point is where sources diverge (Method: yes, for survival).", ["Endurance Training"] = "+3% per rank (15% max) to Pet Health and Armor. It also serves as a legal \"filler\": Unleashed Fury (row 3) requires 10 points already spent in the tree (wowforever.be and Method do it this way).", ["Unleashed Fury"] = "+3% per rank (15% max) to Pet and Hawk damage: the talent that raises total leveling damage the most.", ["Summon Hawk"] = "Level 25: dive-bomb (32 + 5% RAP) and hawk for 18 s, max 2 hawks; 6 s cooldown shared with Arcane Shot. Becomes your main attack (Method, Zockify).", ["Ferocity"] = "+2% per rank (10% max) to Pet and Hawk crit; required by Frenzy.", ["Bestial Swiftness"] = "+30% speed for the Pet: it reaches the mob sooner. Prerequisite for Intimidation.", ["Intimidation"] = "3 s stun on the Pet's next hit (+100% crit on that hit) and lots of threat: useful to pull back aggro from a mob running at you.", ["Improved Mend Pet"] = "Mend Pet has a 15/50% chance to dispel a debuff (Curse, Disease, Magic, Poison) and costs less Mana (Oct 15 patch).", ["Frenzy"] = "After a crit, the Pet has a 20% per rank (100% at rank 5) chance for +30% attack speed for 8 s. Requires Ferocity.", ["Bestial Wrath"] = "Level 40: Pet +50% damage for 18 s (2 min cooldown), immune to CC. Tree capstone (31st point).", ["Lethal Attacks"] = "+1% per rank (5% max) crit with all attacks: first step of the 31/20/0.", ["Careful Aim"] = "Converts 20% per rank (100% max) of your Intellect into Attack Power. Mobalytics (Crix) skips it in 1–30 because Intellect is low; at 46–50 it makes more sense.", ["Hawk Eye"] = "+2 yd per rank (6 yd max) to ranged weapon range: more time to shoot before melee.", ["Rapid Killing"] = "Rapid Fire 1/2 min cooldown; after a kill, the next Shot does +10/20%.", ["Trueshot Aura"] = "Level 56 in this build: +15 RAP to party and raid within 45 yd (raid-wide from Oct 15); useful in groups and dungeons.", ["Mortal Shots"] = "+6% per rank (30% max) to crit damage of all ranged abilities.", ["Pathfinding"] = "Faster Aspect of the Cheetah and Aspect of the Pack (+6% at 2/2): less running between mobs. It is on row 3: you take it after 10 points in Beast Mastery (Feor at 20–21).", ["Bestial Discipline"] = "Your Pet regenerates Focus 20% faster and 50% of your Mana regeneration continues while casting (at 2/2): fewer breaks to drink." },
   summary = "Beast Mastery is the most comfortable spec for solo leveling: Warcraft Tavern, Method (Celz, Oct 21), Zockify (Oct 25) and the most voted Hunter guide on Mobalytics (Feor, {775 }, Verified, updated Nov 18) all pick it, and Feor gives the order level by level from 10 to 60. The Pet holds threat while you shoot from range: few deaths and little downtime. The build follows Feor: Pathfinding at 20–21, Summon Hawk at 25, Intimidation at 30, Bestial Wrath at 40, then 20 points in Marksmanship (31 BM + 20 MM). Recommended Pets: Cat (damage) or Boar (toughness), tamed by level and zone.", bsum = { b = "You want more damage from standing still at range and you accept kiting more: not for the calmer leveling." }, rot = { { "1–9 · Kiting without a Pet", { { "ability_hunter_aspectofthemonkey", "Aspect of the Monkey" }, { "ability_hunter_snipershot", "Hunter's Mark" }, { "ability_whirlwind", "Auto Shot" }, { "ability_hunter_quickshot", "Serpent Sting" }, { "ability_impalingbolt", "Arcane Shot" }, { "spell_frost_stun", "Concussive Shot" }, { "ability_meleedamage", "Raptor Strike" } }, "Open from max distance: Auto Shot (standing still 0.5 s), Serpent Sting only if the mob lives long enough, Arcane Shot on cooldown. After each shot take a step back and resume; Concussive Shot from 8 to slow. If it reaches melee: Raptor Strike. One mob at a time (Warcraft Tavern, Zockify)." }, { "10–19 · The Pet holds the mob", { { "ability_hunter_beastcall", "Call Pet" }, { "ability_physical_taunt", "Pet: Growl" }, { "spell_nature_ravenform", "Aspect of the Hawk" }, { "ability_hunter_snipershot", "Hunter's Mark" }, { "ability_whirlwind", "Auto Shot" }, { "ability_impalingbolt", "Arcane Shot" }, { "ability_hunter_mendpet", "Mend Pet" } }, "Send the Pet in first and let it use Growl; then Hunter’s Mark, Auto Shot and Arcane Shot. Aspect of the Hawk always active in combat. From 18, Multi-Shot on 2+ mobs. Mend Pet when it drops. If the mob reaches you: Wing Clip (12) or Concussive Shot and resume at range (Method)." }, { "20–24 · Aimed Shot and Freezing Trap", { { "ability_hunter_beastcall", "Pet in front" }, { "ability_hunter_quickshot", "Serpent Sting" }, { "inv_spear_07", "Aimed Shot" }, { "ability_impalingbolt", "Arcane Shot" }, { "spell_frost_chainsofice", "Freezing Trap" } }, "Aimed Shot (2 s cast) on the single target; Multi-Shot if there are 2–3 mobs. Aimed Shot and Multi-Shot share 6 s: one per cycle; Arcane Shot has its own timer. Freezing Trap on the extra mob (10 s). Aspect of the Cheetah (20) to move, but switch back to Hawk before the pull." }, { "25–39 · Summon Hawk, 2 hawks always up", { { "ability_hunter_animalhandler", "Summon Hawk" }, { "ability_hunter_animalhandler", "Summon Hawk" }, { "inv_spear_07", "Aimed Shot" }, { "ability_impalingbolt", "Arcane Shot" }, { "ability_hunter_runningshot", "Rapid Fire" } }, "From 25, keep 2 hawks and the Pet on every mob that lives more than a few seconds (they last 18 s: don't recast before the last second). Summon Hawk shares 6 s with Arcane Shot: use Arcane Shot every third cast or on a nearly dead mob (Method). Rapid Fire (26) on difficult pulls, Intimidation (30) if the mob turns toward you, Feign Death (30) to reset." }, { "40+ · Bestial Wrath", { { "ability_hunter_snipershot", "Hunter's Mark" }, { "ability_hunter_quickshot", "Serpent Sting" }, { "ability_hunter_animalhandler", "Summon Hawk ×2" }, { "inv_spear_07", "Aimed Shot" }, { "ability_druid_ferociousbite", "Bestial Wrath (elite)" }, { "ability_whirlwind", "Auto Shot" } }, "Hunter's Mark before the pull and the Pet attacks first; then Serpent Sting, 2 hawks with Summon Hawk, Aimed Shot on cooldown and Auto Shot. Bestial Wrath (40, +50% Pet damage for 18 sec) and Rapid Fire on elites and big mobs; Intimidation if the mob turns to you, Disengage if you pull aggro. With plenty of Mana and 2 hawks up for another 6 sec: Arcane Shot (Icy Veins). To level faster keep 2 mobs: Auto Shot on the far one, the Pet and Raptor Strike or Wing Clip on the close one, Multi-Shot when they are together (Mobalytics – Feor, Nov 14)." }, { "AoE · multiple pulls", { { "spell_frost_freezingbreath", "Frost Trap" }, { "spell_frost_chainsofice", "Freezing Trap" }, { "ability_upgrademoonglaive", "Multi-Shot" }, { "ability_devour", "Intimidation" }, { "ability_rogue_feigndeath", "Feign Death" } }, "Frost Trap (28) slows the group by 60%; Freezing Trap on one mob. Multi-Shot on 3 targets (costs a lot of Mana). If the Pet loses threat: Intimidation (30) or Distracting Shot; if the mob reaches you, Wing Clip and back off. Traps can be placed in combat (30 s cooldown, a Fire and an Ice together from Oct 15) but always at your feet: back up toward the trap." } },
   brot = { b = { { "10–24 · Hawk Eye, Lethal Attacks, Careful Aim", { { "ability_whirlwind", "Auto Shot" }, { "ability_impalingbolt", "Arcane Shot" }, { "ability_townwatch", "Hawk Eye" } }, "Auto Shot standing still (0.5 s) as the base; Arcane Shot on cooldown. Hunter's Mark and Serpent Sting remain in the kit, but the sources don't detail the MM rotation." }, { "25–40 · Trueshot Aura and Aimed Shot", { { "spell_nature_ravenform", "Aspect of the Hawk" }, { "ability_trueshot", "Trueshot Aura" }, { "inv_spear_07", "Aimed Shot" } }, "Tavern: Aspect of the Hawk and Trueshot Aura on you always. Aimed Shot is base from 20 (wowforever.gg): use it on mobs that remain." } } },
   notes = { { "Pet management and threat", "• The Pet does most of the damage and holds threat: send it first, {Growl} on autocast (turn it off in dungeons if there's a tank).\n• {Aspect of the Hawk} always in combat; {Cheetah} only while traveling (if they hit you, you're Dazed for 4 s).\n• Happiness: Happy 125% damage, Content 100%, Unhappy 75%. Use Feed Pet out of combat with food from its diet (beta bug: only drops when the Pet dies).\n• The Pet takes 25% of mob XP (green or higher mobs only) and stops at your level.\n• Ranged abilities don't work within 8 yd of the enemy: keep the Pet in front." }, { "Mana and downtime", "• Mana is your resource (Pets use Focus). Aimed Shot, Multi-Shot and Summon Hawk cost a lot: don't spend it all, keep a reserve for Feign Death and traps (Warcraft Tavern).\n• If it runs low: let the Pet and Auto Shot work, no mana-costing abilities until it regenerates; drink between pulls.\n• Mana in combat depends on Spirit: {Bestial Discipline} (BM), Rapid Recuperation (MM) and Resourcefulness (Survival) help.\n• Legacy: {Thrill of Adventure} gives some Health and Mana for each non-trivial kill (wowforeverguides)." }, { "Chain pull and Feign Death", "The Hunter excels at chain pulling: you move to the next mob while the previous one dies to DoTs or traps, but watch out for live mobs wandering toward other packs (Warcraft Tavern). {Feign Death} (30) resets a bad pull: put the Pet on passive and call it back first, then stay down until the mobs wander off (Zockify). Before 30, use Scare Beast, Freezing Trap or Distracting Shot." } }, stats = "Priority (Warcraft Tavern): Agility > Attack Power > Critical Strike > Intellect > Stamina/Spirit > Strength > Armor. Before 10: Agility, AP, Intellect, Stamina/Spirit, Armor. Spirit matters for Mana in combat (Bestial Discipline). The ranged weapon is your first upgrade; then melee for stats. Ranged (Warcraft Tavern): Barbaric Crossbow (13–16, Ragefire Chasm), Calibrated Blunderbuss (13–16, quest Hall of Thanes, Alliance only), Venomstrike (19–22, Wailing Caverns), Naga Heartpiercer (22–29, Blackfathom Deeps), Fallenroot Longbow (23–29, Blackfathom Deeps), Quilboar Blaster (29–30, quest Razorfen Kraul), Master Hunter’s Bow (30, quest Big Game Hunter). Crafted and dungeon: Brawler’s Leather Hood, Dark Leather Boots, Stalker’s Leather Belt, Bloodied Chestwraps, Triprunner Dungarees. Mail from 40, Dual Wield from 20 ( client, wowforeverguides).", forever = { "Aimed Shot is base at level 20 (2 s cast, 6 s cooldown shared with Multi-Shot): Blizzard deep dive Sep 30, client.", "Summon Hawk, new BM talent (level 25 with all points in BM): max 2 hawks, 6 s cooldown shared with Arcane Shot; from Oct 15 the hawk appears on the target and stays there.", "New talents: Focused Fire, Careful Aim (20–100% Int -> AP), Lone Wolf, Rapid Killing; changed Deadly Aspects, Ferocity and Unleashed Fury (now also apply to Hawks). Intimidation requires Bestial Swiftness.", "Traps usable in combat (30 s cooldown), a Fire and an Ice together, and Fire trap scaling with AP (Oct 15).", "Pets: gain stats from the Hunter's equip (10% AP, 100% crit), each family has a unique ability, Bite or Claw and Dash or Dive, Fox is new; they inherit the highest crit and benefit from Expertise (Oct 15).", "Sep 24: Tame Beast doesn't work on beasts above your level; Furious Howl 40%. Oct 15: Dismember 25%/6 s, Sonic Blast +30% cast time/1 min cooldown, Mine! 3 s/90 s; Improved Mend Pet reduces Mana cost.", "Oct 15: Auto Shot requires 0.5 s standing still; new Auto Attack/Auto Shot option. Scorpid Sting now 2% hit; Aspect of the Beast gives melee AP; Disengage reduces threat twice as much.", "Humans and Skyborne (Alliance and Horde) can be Hunters. Oct 26–27: Orc Command +5% damage to Pets, Human Ruthless 1%, Skyborne Wind Blessed 2%.", "Dungeons: quest XP reduced by 50% from Oct 1; Excavation Site: Wetlands is new.", "At launch (Blizzard notes and hotfix of 3 Nov): Arcane Shot and Serpent Sting get more Attack Power and deal more, Aspect of the Hawk is back to Classic values, Trueshot Aura gives up to 100 ranged attack power, Barrage and Lightning Reflexes as in Classic; all traps share one 30 sec cooldown." },
   races = { ["human"] = "New combination. Ruthless +1% crit (was 2%, halved on Oct 26), The Human Spirit +10% Spirit (doubled), Will to Survive (removes stuns), Perception. Method recommends it, but its numbers predate the patch.", ["dwarf"] = "Big Game Hunter: +5% damage vs Beasts (many leveling mobs) ; Artisan’s Precision +1% Hit; Stoneform. Great, but no racial for the Pet.", ["nightelf"] = "Shadowmeld (stealth while standing still, useful for drinking), Elune’s Light (+10% crit for 15 s, Method), Quickness (+1% Dodge, +2% speed), Wisp Spirit. Method: among the best Alliance races.", ["skyborne_a"] = "High Order (Alliance): Wind Blessed +2% Haste (was 3% before Oct 26), Walk on Air, Elemental Insight +5% vs Elementals, Read Ley Line (regenerates Health and Mana +50% for 15 s, 100% if Attuned to a Ley Line). They start at Zephras Isle (3–12) with the new Hunter quest and the Fox Vuldren Alpha.", ["orc"] = "Command: Pets deal +5% damage (back on Oct 26, for BM); Blood Fury +10% AP for 15 s with 2 min cooldown; Hardiness (stun 20%); Shatter Curse. According to Method the best Horde race, but Savage has been removed.", ["tauren"] = "War Stomp (2 s stun to escape), Endurance (5% Health), Plainsrunning (+2% speed every 5 s, max 60%), Cultivation (duplicates herbs). No offensive bonus.", ["troll"] = "Beast Slaying +5% damage to Beasts (great for leveling) ; Berserking +10% haste for 10 s; Regeneration; Rapid Regeneration (channel, 50% Health). With the Orc, it's the most sensible choice for a Horde Hunter.", ["skyborne_h"] = "Windshaper (Horde): same Wind Blessed, Walk on Air and Elemental Insight; instead of Read Ley Line they have Skysight (+15% speed for 15 s, 30% with Charged to an elemental convergence). They start at Zephras Isle with the same Hunter quest." },
   spells = { { 1, "Raptor Strike", "ability_meleedamage", "Melee strike: only needed when the mob reaches you. After 10 it loses almost all its value (Method).", false }, { 1, "Auto Shot", "ability_whirlwind", "Your main damage. From Oct 15 you have to stand still 0.5 s before shooting; it keeps going while you cast Aimed Shot.", false }, { 1, "Track Beasts", "ability_tracking", "Shows beasts on the minimap: needed to find Pets to tame.", false }, { 4, "Serpent Sting", "ability_hunter_quickshot", "Nature DoT, no immediate damage: don't use it on mobs that die right away.", false }, { 4, "Aspect of the Monkey", "ability_hunter_aspectofthemonkey", "+8% Dodge: keeps you alive before 10, when you don't have a Pet yet.", false }, { 6, "Arcane Shot", "ability_impalingbolt", "Instant Arcane shot, 6 s cooldown. From 25 it shares the cooldown with Summon Hawk.", false }, { 6, "Hunter's Mark", "ability_hunter_snipershot", "Increases Ranged Attack Power of whoever attacks the target: including the Pet (scales with your AP).", false }, { 8, "Concussive Shot", "spell_frost_stun", "Ranged slow (12 s cooldown): your kiting tool before the Pet.", false }, { 10, "Aspect of the Hawk", "spell_nature_ravenform", "+Ranged Attack Power and the base of Deadly Aspects: always active in combat.", false }, { 10, "Track Humanoids", "spell_holy_prayerofhealing", "Humanoid tracking.", false }, { 10, "Tame Beast / Beast Training / Feed Pet / Revive Pet / Call Pet / Dismiss Pet", "ability_hunter_beasttaming", "From the level 10 class quest (Taming the Beast + Training the Beast). You can't tame beasts above your level, or with an active Pet.", false }, { 12, "Mend Pet", "ability_hunter_mendpet", "Heals the Pet in a channel (5 s): essential vs elites or groups.", false }, { 12, "Wing Clip", "ability_rogue_trip", "Melee slow (40 Mana): if the mob gets on you.", false }, { 12, "Distracting Shot", "spell_arcane_blink", "Instant ranged threat.", false }, { 14, "Scare Beast", "ability_druid_cower", "Fear on a Beast (10 s): careful, the mob can run into other groups.", false }, { 14, "Eyes of the Beast / Eagle Eye", "ability_eyeoftheowl", "Exploration: control your Pet or zoom out from a distance; Eyes of the Beast lets you pull from far away.", false }, { 16, "Immolation Trap", "spell_fire_flameshock", "Fire trap (DoT): usable in combat and scales with AP (Oct 15).", false }, { 16, "Mongoose Bite", "ability_hunter_swiftstrike", "Melee strike: mainly useful for Survival.", false }, { 18, "Multi-Shot", "ability_upgrademoonglaive", "AoE on 3 targets; shares the cooldown (6 s) with Aimed Shot.", false }, { 20, "Aimed Shot", "inv_spear_07", "Base for all Hunters (a talent in Classic Era): 2 s cast, 6 s cooldown shared with Multi-Shot. Your single-target shot.", false }, { 20, "Freezing Trap", "spell_frost_chainsofice", "10 s CC on the first mob that passes (broken by damage); usable in combat. 30 s cooldown shared with Frost Trap.", false }, { 20, "Aspect of the Cheetah", "ability_mount_jungletiger", "+30% speed out of combat: if you get hit you stay Dazed.", false }, { 20, "Disengage", "ability_rogue_feint", "Reduces threat on the target ( double from Oct 8).", false }, { 22, "Scorpid Sting", "ability_hunter_criticalshot", "Changed: 2% chance for it to hit you for 20 s (no longer reduces Strength and Agility).", false }, { 24, "Track Hidden", "ability_stealth", "Detects stealthed units on the minimap (Method: \"incredible\" for quests).", false }, { 24, "Beast Lore", "ability_physical_taunt", "Beast information: useful to know what a Pet to tame will teach.", false }, { 25, "Summon Hawk", "ability_hunter_animalhandler", "BM talent (16th point): hawk that attacks for 18 s, max 2; 11% of base Mana (Nov 10 hotfix), 6 s cooldown shared with Arcane Shot.", true }, { 26, "Rapid Fire", "ability_hunter_runningshot", "5 min cooldown: +40% ranged and melee attack speed for 15 s. Use it on difficult pulls.", false }, { 26, "Track Elementals", "spell_frost_summonwaterelemental", "Elemental tracking.", false }, { 28, "Frost Trap", "spell_frost_freezingbreath", "Area that slows by 60% for 30 s: essential for multiple pulls.", false }, { 30, "Feign Death", "ability_rogue_feigndeath", "Leaves combat (can miss): put the Pet on passive first.", false }, { 30, "Aspect of the Beast", "ability_mount_pinktiger", "Gives Melee Attack Power and makes you untrackable: for when the mob reaches you.", false }, { 30, "Intimidation", "ability_devour", "BM talent: requires Bestial Swiftness; 3 s stun on the Pet's next attack, +100% crit on that hit.", true }, { 32, "Flare", "spell_fire_flare", "Reveals stealth and invisible within 10 yd. Track Demons at the same level (Warcraft Tavern).", false }, { 34, "Explosive Trap", "spell_fire_selfdestruct", "Fire AoE trap. Serpent Sting 5 and Disengage 2 at the same level.", false }, { 36, "Viper Sting", "ability_hunter_aimedshot", "Drains mana from the target. At the same level: Summon Hawk 2, Aimed Shot 3, Arcane Shot 5, Mend Pet 4.", false }, { 40, "Aspect of the Pack", "ability_mount_whitetiger", "+30% speed to the whole group. Volley, Track Giants, Freezing Trap 2, Apprentice Riding and Dual Specialization at the same level.", false }, { 40, "Bestial Wrath", "ability_druid_ferociousbite", "BM talent (31st point): Pet +50% damage for 18 s, 2 min cooldown.", true }, { 46, "Aspect of the Wild", "spell_nature_protectionformnature", "Nature resistance to the group.", false }, { 50, "Track Dragonkin", "ability_tracking", "Dragonkin tracking.", false }, { 56, "Trueshot Aura", "ability_trueshot", "MM talent of the level 60 build: +RAP to party and raid within 45 yd.", true }, { 60, "Tranquilizing Shot", "spell_nature_drowsy", "Removes a Frenzy/Enrage effect from the enemy.", false } },
   bsp = { b = { { 1, "Raptor Strike", "ability_meleedamage", "Melee strike: only needed when the mob reaches you. After 10 it loses almost all its value (Method).", false }, { 1, "Auto Shot", "ability_whirlwind", "Your main damage. From Oct 15 you have to stand still 0.5 s before shooting; it keeps going while you cast Aimed Shot.", false }, { 1, "Track Beasts", "ability_tracking", "Shows beasts on the minimap: needed to find Pets to tame.", false }, { 4, "Serpent Sting", "ability_hunter_quickshot", "Nature DoT, no immediate damage: don't use it on mobs that die right away.", false }, { 4, "Aspect of the Monkey", "ability_hunter_aspectofthemonkey", "+8% Dodge: keeps you alive before 10, when you don't have a Pet yet.", false }, { 6, "Arcane Shot", "ability_impalingbolt", "Instant Arcane shot, 6 s cooldown. From 25 it shares the cooldown with Summon Hawk.", false }, { 6, "Hunter's Mark", "ability_hunter_snipershot", "Increases Ranged Attack Power of whoever attacks the target: including the Pet (scales with your AP).", false }, { 8, "Concussive Shot", "spell_frost_stun", "Ranged slow (12 s cooldown): your kiting tool before the Pet.", false }, { 10, "Aspect of the Hawk", "spell_nature_ravenform", "+Ranged Attack Power and the base of Deadly Aspects: always active in combat.", false }, { 10, "Track Humanoids", "spell_holy_prayerofhealing", "Humanoid tracking.", false }, { 10, "Tame Beast / Beast Training / Feed Pet / Revive Pet / Call Pet / Dismiss Pet", "ability_hunter_beasttaming", "From the level 10 class quest (Taming the Beast + Training the Beast). You can't tame beasts above your level, or with an active Pet.", false }, { 12, "Mend Pet", "ability_hunter_mendpet", "Heals the Pet in a channel (5 s): essential vs elites or groups.", false }, { 12, "Wing Clip", "ability_rogue_trip", "Melee slow (40 Mana): if the mob gets on you.", false }, { 12, "Distracting Shot", "spell_arcane_blink", "Instant ranged threat.", false }, { 14, "Scare Beast", "ability_druid_cower", "Fear on a Beast (10 s): careful, the mob can run into other groups.", false }, { 14, "Eyes of the Beast / Eagle Eye", "ability_eyeoftheowl", "Exploration: control your Pet or zoom out from a distance; Eyes of the Beast lets you pull from far away.", false }, { 16, "Immolation Trap", "spell_fire_flameshock", "Fire trap (DoT): usable in combat and scales with AP (Oct 15).", false }, { 16, "Mongoose Bite", "ability_hunter_swiftstrike", "Melee strike: mainly useful for Survival.", false }, { 18, "Multi-Shot", "ability_upgrademoonglaive", "AoE on 3 targets; shares the cooldown (6 s) with Aimed Shot.", false }, { 20, "Aimed Shot", "inv_spear_07", "Base for all Hunters (a talent in Classic Era): 2 s cast, 6 s cooldown shared with Multi-Shot. Your single-target shot.", false }, { 20, "Freezing Trap", "spell_frost_chainsofice", "10 s CC on the first mob that passes (broken by damage); usable in combat. 30 s cooldown shared with Frost Trap.", false }, { 20, "Aspect of the Cheetah", "ability_mount_jungletiger", "+30% speed out of combat: if you get hit you stay Dazed.", false }, { 20, "Disengage", "ability_rogue_feint", "Reduces threat on the target ( double from Oct 8).", false }, { 22, "Scorpid Sting", "ability_hunter_criticalshot", "Changed: 2% chance for it to hit you for 20 s (no longer reduces Strength and Agility).", false }, { 24, "Track Hidden", "ability_stealth", "Detects stealthed units on the minimap (Method: \"incredible\" for quests).", false }, { 24, "Beast Lore", "ability_physical_taunt", "Beast information: useful to know what a Pet to tame will teach.", false }, { 25, "Trueshot Aura", "ability_trueshot", "MM talent of the level 60 build: +RAP to party and raid within 45 yd.", true }, { 26, "Rapid Fire", "ability_hunter_runningshot", "5 min cooldown: +40% ranged and melee attack speed for 15 s. Use it on difficult pulls.", false }, { 26, "Track Elementals", "spell_frost_summonwaterelemental", "Elemental tracking.", false }, { 28, "Frost Trap", "spell_frost_freezingbreath", "Area that slows by 60% for 30 s: essential for multiple pulls.", false }, { 30, "Feign Death", "ability_rogue_feigndeath", "Leaves combat (can miss): put the Pet on passive first.", false }, { 30, "Aspect of the Beast", "ability_mount_pinktiger", "Gives Melee Attack Power and makes you untrackable: for when the mob reaches you.", false }, { 32, "Flare", "spell_fire_flare", "Reveals stealth and invisible within 10 yd. Track Demons at the same level (Warcraft Tavern).", false }, { 34, "Explosive Trap", "spell_fire_selfdestruct", "Fire AoE trap. Serpent Sting 5 and Disengage 2 at the same level.", false }, { 36, "Viper Sting", "ability_hunter_aimedshot", "Drains mana from the target. At the same level: Summon Hawk 2, Aimed Shot 3, Arcane Shot 5, Mend Pet 4.", false }, { 40, "Aspect of the Pack", "ability_mount_whitetiger", "+30% speed to the whole group. Volley, Track Giants, Freezing Trap 2, Apprentice Riding and Dual Specialization at the same level.", false }, { 40, "Sniper Shot (talent)", "hunter_pvp_snipershot", "", true }, { 46, "Aspect of the Wild", "spell_nature_protectionformnature", "Nature resistance to the group.", false }, { 50, "Track Dragonkin", "ability_tracking", "Dragonkin tracking.", false }, { 60, "Tranquilizing Shot", "spell_nature_drowsy", "Removes a Frenzy/Enrage effect from the enemy.", false } } } },
  mage = { why = { ["Improved Frostbolt"] = "Faster Frostbolt: it's 90% of your casts.", ["Precision"] = "No “Resisted”: with 2 talent points, no Misses on mobs of your level.", ["Frostbite"] = "Free Freezes: time for Wand and a combo with Ice Lance.", ["Ice Lance"] = "The big hit on Frozen targets.", ["Ice Shards"] = "Doubles the Frost crit bonus.", ["Shatter"] = "Near-guaranteed crits on Frozen targets.", ["Ice Block"] = "Saves your life when the pull goes wrong.", ["Fingers of Frost"] = "Randomly makes the target “Frozen”: Ice Lance strong even at range.", ["Permafrost"] = "Longer and stronger Chill: easier to kite.", ["Improved Cone of Cold"] = "More damage to Cone of Cold on multiple pulls." },
   summary = "Frost up to 48, then Arcane for Mana: it's the build of the most-saved mage guide on Mobalytics (Asuna_qt, {496 }, upd. Nov 25), with the full 10–60 order. Up to 30 it's almost the same as {wowforever.be} (read from the client): Precision 3/3 right away (no Misses on mobs of your level), Ice Lance at 20, Ice Block at 25, Shatter and Fingers of Frost. Warcraft Tavern calls it “the strongest Frost build at 30”.", bsum = { b = "If you want to play Arcane all the way to 60: Arcane Blast until Missile Barrage procs, then free Arcane Missiles, and Arcane Wrath for burst. From 41 Precision in Frost, from 45 points in Fire (Accelerant, Ignite, Pyroblast)." }, rot = { { "1–9 · Before talents", { { "spell_frost_frostbolt02", "Frostbolt" }, { "inv_wand_01", "Wand (Shoot)" } }, "Open from max distance with Frostbolt (Fireball before 4), finish with the Wand (Shoot). Fire Blast if you're moving." }, { "10–19 · Kiting", { { "spell_frost_frostbolt02", "Frostbolt" }, { "spell_frost_frostnova", "Frost Nova" }, { "spell_frost_frostbolt02", "Frostbolt" } }, "If the mob reaches you: Frost Nova, take a few steps back, resume with Frostbolt. Each Frostbite is free time for Wand or Frostbolt." }, { "20+ · Frostbite triggers at range", { { "spell_frost_frostbolt02", "Frostbolt" }, { "spell_frost_frostblast", "+ Ice Lance" } }, "Cast Frostbolt and queue Ice Lance right after: they arrive together on the Frozen target. If Ice Lance is on cooldown, use Cone of Cold (from 26)." }, { "20+ · The mob is in melee", { { "spell_frost_frostnova", "Frost Nova" }, { "spell_arcane_blink", "Step back" }, { "spell_frost_frostbolt02", "Frostbolt" }, { "spell_frost_frostblast", "+ Ice Lance" } }, "Only one Ice Lance per Nova (8 s cooldown). Then Frostbolt while it's Frozen, and start over." }, { "30 · Fingers of Frost", { { "ability_mage_wintersgrasp", "Proc" }, { "spell_frost_frostblast", "Ice Lance" } }, "With 1 talent point you have 1 charge: spend it on Ice Lance. If Ice Lance is on cooldown, Frostbolt + Ice Lance as soon as it's back. With 2 talent points (31): Frostbolt on the first charge, Frostbolt + Ice Lance on the second (Icy Veins)." }, { "40+ · Ice Barrier and Missile Barrage", { { "spell_ice_lament", "Ice Barrier" }, { "spell_frost_frostbolt02", "Frostbolt" }, { "spell_frost_frostblast", "Ice Lance (proc)" }, { "ability_mage_missilebarrage", "Arcane Missiles (54)" } }, "Always keep {Ice Barrier} up (40): while the shield holds your Frost damage goes up by 15% plus another 5%, and you don't lose cast time when you are hit (game tooltip). Frostbolt over and over. When Fingers of Frost procs cancel your cast and spend it with Ice Lance (Frostbolt would consume it); with Frostbite, Ice Lance right after your next Frostbolt, so they land together and benefit from Shatter. From 54, when Missile Barrage procs use Arcane Missiles (free and faster). While moving Fire Blast; out of Mana use a mana gem, potion or Evocation, then the Wand (Mobalytics – Asuna_qt)." }, { "AoE · 3+ mobs", { { "spell_frost_frostnova", "Frost Nova" }, { "spell_fire_selfdestruct", "Flamestrike" }, { "spell_nature_wispsplode", "Arcane Expl." }, { "spell_frost_glacier", "Cone of Cold" } }, "Solo: Nova, then close-range AoE. Blizzard only if you're safe (in a group). Costs a lot of mana: drink afterwards." } },
   brot = { b = { { "Single target", { { "spell_frost_frostbolt02", "Frostbolt" }, { "ability_mage_netherwindpresence", "Arcane Wrath" }, { "spell_arcane_blast", "Arcane Blast ×1–3" }, { "ability_mage_missilebarrage", "Arcane Missiles (proc)" } }, "From max range: Frostbolt to slow, Arcane Wrath, then Arcane Blast 1–3 times until Missile Barrage procs, and Arcane Missiles. Each Arcane Blast costs twice the previous one: let the buff drop or you run out of mana. If the mob reaches you: Frost Nova, Arcane Wrath, Fire Blast; finish nearly dead mobs with the Wand (Icy Veins)." }, { "AoE · 3+ mobs", { { "spell_frost_frostnova", "Frost Nova" }, { "spell_frost_glacier", "Cone of Cold" }, { "spell_nature_wispsplode", "Arcane Explosion" } }, "Gather the mobs, Frost Nova to hold them, Cone of Cold if you have it, then Arcane Explosion. With 3 mobs or fewer it is usually not worth it: it costs too much mana (Icy Veins)." } } },
   notes = { { "Pre-launch news : Ice Lance with cooldown", "Ice Lance now has an {8 second cooldown} (client 70707, Wowhead, change noted by Icy Veins on Oct 30). You can no longer spam it during Frost Nova: {one} Ice Lance per Freeze, well placed. Damage on Frozen targets: +300% according to the client (Icy Veins says +200%: the tooltip is the authority)." }, { "What is “spell batching” and why it matters", "As in Classic, the server processes actions in small intervals. If you press Ice Lance right after a Frostbolt starts, the two hits arrive together: both find the target still Frozen and benefit from Shatter. Freeze breaks on damage, even your own. Ice Lance “snapshots” the Frozen state at the moment of the cast (Icy Veins)." }, { "Mana: the rules that save the most time", "• {5-second rule:} mana only regenerates after 5 s without spending any. Finish mobs with the Wand.\n• Don't waste a high-Rank Frostbolt on a nearly dead mob: use Fire Blast or Wand.\n• On login, spend mana on Conjure Food, Conjure Water and Mana Gem (from 28).\n• Get a Wand as soon as possible: Lesser Magic Wand (lvl 5) and Greater Magic Wand (lvl 13), from Enchanting or the Auction House. Enchanters make them to level up their skill: they cost little." } }, stats = "Intellect and Spirit for mana, Stamina to survive; Frost spell damage when it arrives. The weapon matters: Wand (Shoot) and Staff.", forever = { "Ice Lance talent at 20: 8 s cooldown, +300% on Frozen targets (client 70707, Oct 30).", "Fingers of Frost at 30 (talent).", "Elemental Precision -> Precision, 3 ranks of 2% (Oct 16 hotfix, KamiLabs/Venruki); Piercing Ice removed.", "Frost Blast at 24: fast Chill.", "At launch (Blizzard notes of 3 Nov): Ignite also triggers from Flamestrike's ticks, Missile Barrage is spent when Arcane Missiles starts and Arcane Missiles can give Clearcasting again; a rank learned more than 12 levels below yours has a lower chance to trigger Arcane Concentration, Frostbite and Fingers of Frost." },
   races = { ["gnome"] = "Expansive Mind (+Intellect) and Escape Artist to free yourself from roots.", ["human"] = "Extra Spirit (The Human Spirit) to regenerate mana.", ["skyborne_a"] = "Skyborne racial: Haste and mana regen (High Order) .", ["orc"] = "Blood Fury for burst; stun resistance.", ["undead"] = "Will of the Forsaken against Fear/Charm; Cannibalize reduces downtime.", ["troll"] = "Berserking for burst; faster Health regeneration." },
   spells = { { 1, "Frost Armor", "spell_frost_frostarmor02", "Always active: applies Chill to whoever hits you in melee and can trigger Frostbite.", false }, { 1, "Arcane Intellect", "spell_holy_magicalsentry", "Always active.", false }, { 1, "Fireball", "spell_fire_flamebolt", "Your attack until 4.", false }, { 4, "Frostbolt", "spell_frost_frostbolt02", "The filler: damage + Chill (slow).", false }, { 4, "Conjure Water", "inv_drink_06", "Free water.", false }, { 6, "Fire Blast", "spell_fire_fireball", "Instant: to finish or while moving.", false }, { 6, "Conjure Food", "inv_misc_food_10", "Free food.", false }, { 8, "Polymorph", "spell_nature_polymorph", "Takes the second mob out of combat.", false }, { 8, "Arcane Missiles", "spell_nature_starfall", "Useful only with Missile Barrage (Icy Veins build).", false }, { 10, "Frost Nova", "spell_frost_frostnova", "Freeze (root) on whoever is near you. Rank 1 lasts the same and costs less.", false }, { 14, "Arcane Explosion", "spell_nature_wispsplode", "AoE around you.", false }, { 16, "Flamestrike", "spell_fire_selfdestruct", "Ground AoE; open group pulls.", false }, { 20, "Blizzard", "spell_frost_icestorm", "Channeled AoE when you're safe.", false }, { 20, "Blink", "spell_arcane_blink", "Escape, breaks roots and stuns; +20% speed if used while running.", false }, { 20, "Evocation", "spell_nature_purge", "Restores most of your mana in 8 s.", false }, { 20, "Teleport (faction capitals)", "spell_arcane_teleportstormwind", "Back to the Trainer in an instant.", false }, { 20, "Ice Lance (talent)", "spell_frost_frostblast", "8 s cooldown, +300% on Frozen targets.", true }, { 24, "Counterspell", "spell_frost_iceshock", "Interrupts casters (especially healers).", false }, { 24, "Frost Blast", "spell_frost_frostblast", "Fast Chill (1.5 s cast, 40% slow for 9 s): replaces Frostbolt Rank 1.", false }, { 25, "Ice Block (talent)", "spell_frost_frost", "Immune 10 s, cooldown 5 min.", true }, { 26, "Cone of Cold", "spell_frost_glacier", "Instant AoE with Chill: your “backup Nova”.", false }, { 28, "Conjure Mana Agate", "inv_misc_gem_emerald_01", "Mana Gem for long pulls.", false }, { 30, "Ice Armor", "spell_frost_frostarmor02", "Replaces Frost Armor.", false }, { 30, "Teleport (third capital)", "spell_arcane_teleportdarnassus", "An extra Teleport.", false } },
   bsp = { b = { { 1, "Frost Armor", "spell_frost_frostarmor02", "Always active: applies Chill to whoever hits you in melee and can trigger Frostbite.", false }, { 1, "Arcane Intellect", "spell_holy_magicalsentry", "Always active.", false }, { 1, "Fireball", "spell_fire_flamebolt", "Your attack until 4.", false }, { 4, "Frostbolt", "spell_frost_frostbolt02", "The filler: damage + Chill (slow).", false }, { 4, "Conjure Water", "inv_drink_06", "Free water.", false }, { 6, "Fire Blast", "spell_fire_fireball", "Instant: to finish or while moving.", false }, { 6, "Conjure Food", "inv_misc_food_10", "Free food.", false }, { 8, "Polymorph", "spell_nature_polymorph", "Takes the second mob out of combat.", false }, { 8, "Arcane Missiles", "spell_nature_starfall", "Useful only with Missile Barrage (Icy Veins build).", false }, { 10, "Frost Nova", "spell_frost_frostnova", "Freeze (root) on whoever is near you. Rank 1 lasts the same and costs less.", false }, { 14, "Arcane Explosion", "spell_nature_wispsplode", "AoE around you.", false }, { 16, "Flamestrike", "spell_fire_selfdestruct", "Ground AoE; open group pulls.", false }, { 20, "Blizzard", "spell_frost_icestorm", "Channeled AoE when you're safe.", false }, { 20, "Blink", "spell_arcane_blink", "Escape, breaks roots and stuns; +20% speed if used while running.", false }, { 20, "Evocation", "spell_nature_purge", "Restores most of your mana in 8 s.", false }, { 20, "Teleport (faction capitals)", "spell_arcane_teleportstormwind", "Back to the Trainer in an instant.", false }, { 20, "Arcane Blast (talent)", "spell_arcane_blast", "", true }, { 24, "Counterspell", "spell_frost_iceshock", "Interrupts casters (especially healers).", false }, { 24, "Frost Blast", "spell_frost_frostblast", "Fast Chill (1.5 s cast, 40% slow for 9 s): replaces Frostbolt Rank 1.", false }, { 25, "Arcane Wrath (talent)", "ability_mage_netherwindpresence", "", true }, { 26, "Cone of Cold", "spell_frost_glacier", "Instant AoE with Chill: your “backup Nova”.", false }, { 28, "Conjure Mana Agate", "inv_misc_gem_emerald_01", "Mana Gem for long pulls.", false }, { 30, "Ice Armor", "spell_frost_frostarmor02", "Replaces Frost Armor.", false }, { 30, "Teleport (third capital)", "spell_arcane_teleportdarnassus", "An extra Teleport.", false }, { 30, "Presence of Mind (talent)", "spell_nature_enchantarmor", "", true }, { 40, "Arcane Power (talent)", "spell_nature_lightning", "", true }, { 55, "Pyroblast (talent)", "spell_fire_fireball02", "", true } } } },
  paladin = { why = { ["Benediction"] = "10% mana on all spells and instant abilities (Seal, Judgement, Holy Strike, Consecration): mana is the real limit for Paladins, not damage.", ["Improved Judgement"] = "Judgement's cooldown is 2 s shorter: more Judgements per mob.", ["Conviction"] = "+6% crit with all attacks and spells (3 ranks after the Oct 31 hotfix).", ["Seal of Command"] = "The main Seal with a slow Two-Handed: 70% extra weapon damage as Holy. Taken at 20 and unlocks Vengeance.", ["Sanctified Judgement"] = "Judgement returns 60% of the judged Seal's mana: mana sustainability.", ["Pursuit of Justice"] = "+15% speed (also while mounted): per sources, the most important travel talent up to 60.", ["Sacred Arbiter"] = "Holy Strike +20% damage and refreshes all Judgements on the target.", ["Vindication"] = "Chance to reduce the mob's Attack Power (after the hotfix it no longer raises your AP).", ["Vengeance"] = "After a non-periodic crit: +3% Physical and Holy damage per stack (3 stacks, 30 s). Requires Seal of Command.", ["Two-Handed Weapon Specialization"] = "+6% to all Physical and Holy damage while you wield a Two-Handed, not just weapon attacks (Nov 18 hotfix), and 20% threat.", ["Repentance"] = "Incapacitates a Humanoid for 6 s: separates two mobs. Prerequisite for Unsealed Wrath.", ["Champion of the Light"] = "Spell damage equal to 12% (rank 1) up to 60% (rank 5) of Intellect: Intellect becomes a damage stat from around 43.", ["Unsealed Wrath"] = "(formerly Twist of Light) Melee hits keep a copy of the active Seal: Forever's simplified seal twisting.", ["Divine Strength"] = "+10% Strength (5 ranks, Holy tree): pure damage, after 40.", ["Improved Seals"] = "+15% to Seal and Judgement damage (5 ranks after the hotfix).", ["Holy Conduit"] = "40% mana for Consecration, Holy Wrath, Exorcism and Hammer of Wrath: sustainable Consecration.", ["Divine Intellect"] = "+10% Intellect (now in the Protection tree): more mana and more damage with Champion of the Light.", ["Precision"] = "+3% Hit with all attacks: eliminates Misses on mobs of your level.", ["Deflection"] = "More Parry in the early levels: take less damage and eat less between pulls." },
   summary = "Retribution with a slow Two-Handed: it's the consensus for solo leveling. The talent order is that of the most voted Paladin guide, {Mobalytics yumytv (554 , upd. Nov 12)}: Deflection 10–14, Conviction, Improved Judgement, Pursuit of Justice and Seal of Command at 22, then Sanctified Judgement and Two-Handed Weapon Specialization; final split 12 Holy / 8 Protection / 31 Retribution, same as Zockify. Maxroll, Conquest Capped and Icy Veins also agree on the spec. wowforever.be (client data) instead opens in Holy: you'll find it as build B.", bsum = { b = "Pick B over A if you want to heal dungeons: Retribution up to 21 (Benediction, Conviction, Pursuit of Justice), then Holy from 22 with Illumination and Holy Shock. No data says B levels faster than A." }, rot = { { "1–9 · Seal, Judgement and Holy Strike", { { "spell_holy_fistofjustice", "Blessing of Might" }, { "ability_thunderbolt", "Seal of Righteousness" }, { "spell_holy_righteousfury", "Judgement" }, { "classicon_paladin", "Holy Strike (from 6)" }, { "spell_holy_holybolt", "Holy Light after the kill" } }, "Before the pull: Blessing of Might (4) and Seal of Righteousness. While running toward the mob, cast Judgement (from 4), then hit; Holy Strike on cooldown from 6. Hammer of Justice from 8 on casters. After the kill, Holy Light if health is below 60%." }, { "10–19 · Mana first", { { "spell_holy_auraoflight", "Retribution Aura (16)" }, { "ability_thunderbolt", "Seal of Righteousness" }, { "spell_holy_righteousfury", "Judgement" }, { "classicon_paladin", "Holy Strike" }, { "spell_holy_sealofmight", "Hammer of Justice" } }, "With Benediction, mana lasts longer. Order: Seal -> Judgement -> Holy Strike on cooldown, auto-attack in between. Retribution Aura from 16. Lay on Hands (10) and Divine Protection (6) are the emergencies; Redemption (12) for companions. Solo, leave Righteous Fury off: it's only threat." }, { "22–39 · Seal of Command and Consecration", { { "spell_holy_holysmite", "Seal of the Crusader (tough mobs)" }, { "spell_holy_righteousfury", "Judgement" }, { "ability_warrior_innerrage", "Seal of Command" }, { "classicon_paladin", "Holy Strike" }, { "spell_holy_innerfire", "Consecration (2+ mobs)" } }, "With a slow Two-Handed (3.3 s or more per Mobalytics and Maxroll): on tough mobs open with Seal of the Crusader -> Judgement -> Seal of Command; on easy mobs only Seal of Command. Judgement and Holy Strike on cooldown, even in a macro. With Sacred Arbiter (26), Holy Strike also refreshes Judgements. Exorcism only on Undead and Demons. With a fast Two-Handed, a 1H or lots of spell power, stay on Seal of Righteousness (Warcraft Tavern, Maxroll)." }, { "40+ · Unsealed Wrath", { { "spell_holy_holysmite", "Seal of the Crusader (tough mobs)" }, { "spell_holy_righteousfury", "Judgement" }, { "ability_warrior_innerrage", "Seal of Command" }, { "spell_holy_blessedresillience", "Unsealed Wrath ×3" }, { "ability_thunderbolt", "Seal of Righteousness + swing" } }, "Retribution Aura and Blessing of Wisdom always on. On mobs that live 20 sec or longer: Seal of the Crusader -> Judgement, then Seal of Command. Judgement and Holy Strike on cooldown, Exorcism on Undead and Demons, Consecration on 3 or more mobs. Unsealed Wrath (40) stores a copy of your Seal with every hit, up to 3: at 3 stacks switch to Seal of Righteousness and swing, so each of the 3 Seal of Command copies gets its own chance to activate; then go back to Seal of Command. If the mob is nearly dead stay on Righteousness and finish it with auto-attacks: that way Mana regeneration starts (Mobalytics – yumytv, Nov 12)." }, { "AoE / multiple pulls", { { "spell_holy_prayerofhealing", "Repentance (1 Humanoid)" }, { "spell_holy_innerfire", "Consecration" }, { "classicon_paladin", "Holy Strike" }, { "spell_holy_sealofmight", "Hammer of Justice" } }, "Two mobs: Repentance on a Humanoid (talent, 36) or Hammer of Justice and kill one mob at a time. Three or more: Consecration in the center (the first 4 enemies take more damage), then Holy Strike and Judgement. Consecration costs a lot of mana (coefficient lowered from 0.095 to 0.042 on Oct 15): use it only when needed; Holy Conduit removes 40% of the cost. From 40, Hammer of the Righteous hits up to 4 targets." }, { "Mana and downtime", { { "spell_holy_sealofwisdom", "Blessing of Wisdom" }, { "spell_holy_righteousnessaura", "Seal of Wisdom (38)" }, { "spell_holy_healingaura", "Seal of Light (30)" } }, "Sanctified Judgement returns 60% of the Seal's cost on each Judgement; Benediction 10% on instants. Solo, use Blessing of Kings (base at 20) and leave the rest to Camp (Mana Well, Lodestone). Only heal if mana is above 50% (wowforeverbuilds). From 38, judge a mob with Seal of Wisdom to recover mana." } },
   brot = { b = { { "Healing · dungeon", { { "spell_holy_flashheal", "Flash of Light" }, { "spell_holy_holybolt", "Holy Light" }, { "spell_holy_searinglight", "Holy Shock" }, { "ability_paladin_judgementofthepure", "Light's Vigil" } }, "Flash of Light is the most efficient heal; Holy Light when heavy damage comes and mana allows; instant Holy Shock in emergencies. Light's Vigil on an ally, then Holy Shock on them: it heals the whole party, but costs a lot (Icy Veins)." }, { "Damage · solo", { { "spell_holy_innerfire", "Consecration" }, { "ability_thunderbolt", "Seal of Righteousness" }, { "spell_holy_righteousfury", "Judgement" }, { "classicon_paladin", "Holy Strike" }, { "spell_holy_excorcism_02", "Exorcism" } }, "Consecration on the mobs while mana allows; Seal of Righteousness and Judgement as often as you can; Holy Strike on cooldown; Exorcism on Undead and Demons. Always keep mana to heal yourself (Icy Veins)." } } },
   notes = { { "Combat tips", "• Judgement {no longer consumes the Seal} : the Seal stays active for 30 s; renew it only when it expires.\n• Holy Strike and Judgement in a macro: fewer clicks, less dead time (Mobalytics, wowforeverbuilds).\n• Hammer of Justice is the only control: the Paladin {has no interrupt or slow} (Blizzard).\n• Emergency: Divine Protection (6) or Divine Shield (34) + two Holy Lights can turn a bad pull around (Conquest Capped); Lay on Hands as a last resort.\n• From 40 with Unsealed Wrath: switch Seal right after a Judgement, the old Seal also applies to the next hit. Costs mana: only if you have some.\n• Best zones: Undead and Demons (Exorcism, Holy Wrath, Turn Undead)." }, { "Blessing and Aura solo", "Blessing of Might and Retribution Aura for damage (yumytv on Mobalytics). Blessing of Kings is base from 20. Camp Lodestone replaces Might and Mana Well replaces Wisdom (Maxroll): in that case cast Kings on yourself." } }, stats = "Weapon damage first (Mobalytics and Maxroll: wide damage range and slow weapon, 3.3 speed or more); then Strength and Hit (Precision gives +3%); Stamina and Intellect to survive and for mana (Intellect matters more from 43 with Champion of the Light). Mail up to 40, Plate after. Weapon (slow 2H with the most DPS): Northshire Hammer (Q7), Ironforge Greathammer (Hall of Thanes, 13), Rhahk'Zor's Hammer (Deadmines, 16–22), Smite's Mighty Hammer (Deadmines, 18), Verigan's Fist / Wolfsbane (class quest 20), Scepter of the Abandoned (Ruins of Lordaeron, 17–25), The Stitcher (Horde, 20–25), Corpsemaker (Razorfen Kraul, 29), Ravager (Scarlet Monastery, 37; classicwowforever lists Bonebiter), Abandoned Ferocity / Scavenged Magram Armament (Desolace, Q42), Diabolic Skiver (Zul'Farrak, 44), Princess Theradras' Scepter (Maraudon, 49), Thorium Poleaxe (BS 260, 52), Legionite Glaive (BS 300, 58). Sources: Zockify, Maxroll, classicwowforever, Conquest Capped.", forever = { "Holy Strike (6, 10 s cooldown), Seal of Fury (10), Hammer of the Righteous (40) and Revoke (26) are new; Righteous Fury drops from 16 to 10 (client, Bind on Forever).", "Judgement no longer consumes the Seal (Blizzard deep dive, Sep 30; Method, Oct 10).", "Blessing of Kings and Consecration are base at 20; Consecration hits the first 4 enemies harder (coefficient 0.095 -> 0.042, Oct 15).", "Oct 31 hotfix (216 changes, Playfulls datamining): Twist of Light renamed Unsealed Wrath (requires Repentance); Conviction 3 ranks, 6% crit on everything; Champion of the Light 5 ranks; Holy Conduit in the Holy tree; Divine Intellect in the Protection tree; Improved Seals 5 ranks; Instrument of Law removed; Turn Evil new.", "Benediction now 10% on all instants (was 15% on Seal and Judgement only); Sacred Arbiter +20% (beta, Sep 24).", "Salvation is no longer a Blessing (Oct 15); Blessing of Light, Salvation and Revoke haven't responded on Wowhead since Oct 31 .", "Lay on Hands 20 min (was 1 hour); Resistance Aura on the whole raid; no baseline seal twisting.", "Vindication no longer raises your AP (Oct 31). Retribution Aura bug fix Oct 8. Human Ruthless and Dwarf Earth Fury Oct 15. Two-Handed Weapon Specialization: Sep 24 at 2/4/6%, now 6% to all Physical and Holy damage with a Two-Handed (since Nov 18, not just attacks) and 20% threat.", "Blizzard Oct 8: dungeon XP will be close to quest XP but won't return to Classic levels; Legacy Talented gives talents from 5.", "At launch (Blizzard notes of 3 Nov): Vengeance stacks up to 5 times (15% at rank 3 instead of 9%), Two-Handed Weapon Specialization raises Holy damage too (up to 6%), Templar's Bulwark's shield is now a Magic effect that can be dispelled." },
   races = { ["human"] = "Ruthless +2% crit on all spells and attacks ( replaces Sword Specialization, Oct 15), Will to Survive (removes stuns), Perception, The Human Spirit (+Spirit). Maxroll recommends it.", ["dwarf"] = "Stoneform; Earth Fury +2% crit damage and healing ( replaces Mace Specialization, Leprestore). Conquest Capped also cites Artisan's Precision and Big Game Hunter . Starts from Coldridge Valley.", ["undead"] = "First time Horde Paladins. Will of the Forsaken (removes Charm/Fear/Sleep, with no immunity afterwards), Cannibalize (restores health and mana), Touch of the Grave (20% drain, 25 s cooldown from Oct 15). Conquest Capped and Maxroll list it as the best for leveling. Starts from Deathknell/Brill; trainers Aramis Hammerhand, Shari Stilwell, Hilda the Breaker (Bandarion Keep)." },
   spells = { { 1, "Seal of Righteousness", "ability_thunderbolt", "Base Seal: extra Holy damage on every hit, stronger with slow weapons and spell power.", false }, { 1, "Holy Light", "spell_holy_holybolt", "Your main heal between pulls.", false }, { 1, "Devotion Aura", "spell_holy_devotionaura", "+Armor for you and the group.", false }, { 4, "Blessing of Might", "spell_holy_fistofjustice", "+Attack Power for 1 hour: always active.", false }, { 4, "Judgement", "spell_holy_righteousfury", "Releases the Seal's effect without consuming it (10 s cooldown, 6% mana). Use it on cooldown.", false }, { 6, "Holy Strike", "classicon_paladin", "New: instant hit with weapon damage + Holy, 10 s cooldown, 5 Mana. Your second on-cooldown button.", false }, { 6, "Divine Protection", "spell_holy_restoration", "Immune to physical damage and spells for 6 s (you can't attack). Applies Forbearance.", false }, { 6, "Seal of the Crusader", "spell_holy_holysmite", "Opening Seal: +AP and faster attacks; its Judgement increases Holy damage on the mob.", false }, { 8, "Hammer of Justice", "spell_holy_sealofmight", "3 s stun: stops casters and fleeing mobs.", false }, { 8, "Purify", "spell_holy_purify", "Removes diseases and Poison.", false }, { 10, "Lay on Hands", "spell_holy_layonhands", "Heals for your max health, drains your mana to zero. 20 min cooldown (was 1 hour).", false }, { 10, "Blessing of Protection", "spell_holy_sealofprotection", "Immune to physical damage for 6 s (Forbearance).", false }, { 10, "Righteous Fury", "spell_holy_sealoffury", "Now at 10 (was 16): only needed for tanking; solo, keep it off.", false }, { 10, "Seal of Fury", "spell_holy_retributionaura", "New tank Seal: fixed Holy per hit and shield absorb; Judgement taunts. Not needed for Retribution.", false }, { 12, "Redemption", "spell_holy_resurrection", "Resurrection. Unlocked via the class quest (Tome of Divinity / A Lesson in Divinity).", false }, { 14, "Blessing of Wisdom", "spell_holy_sealofwisdom", "Mana every 5 s.", false }, { 16, "Retribution Aura", "spell_holy_auraoflight", "Holy damage to whoever hits you, scales with spell power: the leveling aura.", false }, { 18, "Blessing of Freedom", "spell_holy_sealofvalor", "Immune to root and slow for 10 s.", false }, { 20, "Blessing of Kings", "spell_magic_magearmor", "Now base (was a Protection talent): +10% to all stats for 1 hour.", false }, { 20, "Consecration", "spell_holy_innerfire", "Now base (was a Holy talent): deals more damage to the first 4 enemies that enter. Costs a lot of mana.", false }, { 20, "Exorcism", "spell_holy_excorcism_02", "Instant Holy damage vs Undead and Demons.", false }, { 20, "Flash of Light", "spell_holy_flashheal", "Fast heal (1.5 s).", false }, { 22, "Concentration Aura", "spell_holy_mindsooth", "Less pushback when healing.", false }, { 22, "Seal of Justice", "spell_holy_sealofwrath", "Chance-based stun; Judgement prevents escape.", false }, { 22, "Seal of Command", "ability_warrior_innerrage", "Seal talent: 65 Mana, 70% extra weapon damage as Holy. Its Judgement deals 69–73 Holy (138–146 if the target is stunned).", true }, { 24, "Turn Undead", "spell_holy_turnundead", "Fear on Undead (with Turn Evil also on Demons).", false }, { 26, "Salvation", "spell_holy_sealofsalvation", "No longer a Blessing (Oct 15, Blizzard); the Wowhead tooltip hasn't responded since Oct 31.", false }, { 26, "Revoke", "spell_holy_sealofsalvation", "Removes Salvation from allies; Wowhead tooltip not responding.", false }, { 28, "Shadow Resistance Aura", "spell_shadow_sealofkings", "Shadow resistance for the group.", false }, { 28, "Sacred Arbiter", "inv_sword_08", "Passive: Holy Strike +20% damage and refreshes all Judgements on the target.", true }, { 30, "Divine Intervention", "spell_nature_timestop", "You sacrifice yourself to save an ally; requires Symbol of Divinity.", false }, { 30, "Seal of Light", "spell_holy_healingaura", "Seal with a chance-based heal.", false }, { 32, "Frost Resistance Aura", "spell_frost_wizardmark", "Resist Frost.", false }, { 33, "Repentance", "spell_holy_prayerofhealing", "Incapacitates a Humanoid for 6 s, 60 Mana, 1 min cooldown.", true }, { 34, "Divine Shield", "spell_holy_divineintervention", "Immune to everything for 10 s, damage 50%, Forbearance. Life saver.", false }, { 36, "Fire Resistance Aura", "spell_fire_sealoffire", "Resist Fire.", false }, { 38, "Seal of Wisdom", "spell_holy_righteousnessaura", "Mana Seal: judge a mob to recover mana.", false }, { 40, "Hammer of the Righteous", "ability_paladin_hammeroftherighteous", "New: hits the target and up to 3 nearby enemies.", false }, { 40, "Blessing of Light", "spell_holy_prayerofhealing02", "Level from Bind on Forever and Tavern; Wowhead tooltip not responding.", false }, { 40, "Unsealed Wrath", "spell_holy_blessedresillience", "Melee hits keep a copy of the active Seal for 15 s (up to 3 stacks): Forever's seal twisting. Until Oct 31 it was called Twist of Light.", true }, { 42, "Cleanse", "spell_holy_renew", "Removes Poison, diseases and Magic.", false }, { 44, "Hammer of Wrath", "ability_thunderclap", "Finisher below 20% health.", false }, { 46, "Blessing of Sacrifice", "spell_holy_sealofsacrifice", "Transfers damage from an ally to you.", false }, { 50, "Holy Wrath", "spell_holy_excorcism", "AoE on Undead and Demons with stun.", false }, { 52, "Greater Blessing of Might", "spell_holy_greaterblessingofkings", "Group version; requires the Symbol of Kings reagent.", false }, { 54, "Greater Blessing of Wisdom", "spell_holy_greaterblessingofwisdom", "Same.", false }, { 60, "Greater Blessing of Kings", "spell_magic_greaterblessingofkings", "Same.", false }, { 60, "Mass Salvation", "spell_holy_greaterblessingofsalvation", "Raid version of Salvation.", false }, { 60, "Greater Blessing of Light", "spell_holy_greaterblessingoflight", "Group version of Blessing of Light.", false } },
   bsp = { b = { { 1, "Seal of Righteousness", "ability_thunderbolt", "Base Seal: extra Holy damage on every hit, stronger with slow weapons and spell power.", false }, { 1, "Holy Light", "spell_holy_holybolt", "Your main heal between pulls.", false }, { 1, "Devotion Aura", "spell_holy_devotionaura", "+Armor for you and the group.", false }, { 4, "Blessing of Might", "spell_holy_fistofjustice", "+Attack Power for 1 hour: always active.", false }, { 4, "Judgement", "spell_holy_righteousfury", "Releases the Seal's effect without consuming it (10 s cooldown, 6% mana). Use it on cooldown.", false }, { 6, "Holy Strike", "classicon_paladin", "New: instant hit with weapon damage + Holy, 10 s cooldown, 5 Mana. Your second on-cooldown button.", false }, { 6, "Divine Protection", "spell_holy_restoration", "Immune to physical damage and spells for 6 s (you can't attack). Applies Forbearance.", false }, { 6, "Seal of the Crusader", "spell_holy_holysmite", "Opening Seal: +AP and faster attacks; its Judgement increases Holy damage on the mob.", false }, { 8, "Hammer of Justice", "spell_holy_sealofmight", "3 s stun: stops casters and fleeing mobs.", false }, { 8, "Purify", "spell_holy_purify", "Removes diseases and Poison.", false }, { 10, "Lay on Hands", "spell_holy_layonhands", "Heals for your max health, drains your mana to zero. 20 min cooldown (was 1 hour).", false }, { 10, "Blessing of Protection", "spell_holy_sealofprotection", "Immune to physical damage for 6 s (Forbearance).", false }, { 10, "Righteous Fury", "spell_holy_sealoffury", "Now at 10 (was 16): only needed for tanking; solo, keep it off.", false }, { 10, "Seal of Fury", "spell_holy_retributionaura", "New tank Seal: fixed Holy per hit and shield absorb; Judgement taunts. Not needed for Retribution.", false }, { 12, "Redemption", "spell_holy_resurrection", "Resurrection. Unlocked via the class quest (Tome of Divinity / A Lesson in Divinity).", false }, { 14, "Blessing of Wisdom", "spell_holy_sealofwisdom", "Mana every 5 s.", false }, { 16, "Retribution Aura", "spell_holy_auraoflight", "Holy damage to whoever hits you, scales with spell power: the leveling aura.", false }, { 18, "Blessing of Freedom", "spell_holy_sealofvalor", "Immune to root and slow for 10 s.", false }, { 20, "Blessing of Kings", "spell_magic_magearmor", "Now base (was a Protection talent): +10% to all stats for 1 hour.", false }, { 20, "Consecration", "spell_holy_innerfire", "Now base (was a Holy talent): deals more damage to the first 4 enemies that enter. Costs a lot of mana.", false }, { 20, "Exorcism", "spell_holy_excorcism_02", "Instant Holy damage vs Undead and Demons.", false }, { 20, "Flash of Light", "spell_holy_flashheal", "Fast heal (1.5 s).", false }, { 22, "Concentration Aura", "spell_holy_mindsooth", "Less pushback when healing.", false }, { 22, "Seal of Justice", "spell_holy_sealofwrath", "Chance-based stun; Judgement prevents escape.", false }, { 24, "Turn Undead", "spell_holy_turnundead", "Fear on Undead (with Turn Evil also on Demons).", false }, { 26, "Salvation", "spell_holy_sealofsalvation", "No longer a Blessing (Oct 15, Blizzard); the Wowhead tooltip hasn't responded since Oct 31.", false }, { 26, "Revoke", "spell_holy_sealofsalvation", "Removes Salvation from allies; Wowhead tooltip not responding.", false }, { 28, "Shadow Resistance Aura", "spell_shadow_sealofkings", "Shadow resistance for the group.", false }, { 30, "Divine Intervention", "spell_nature_timestop", "You sacrifice yourself to save an ally; requires Symbol of Divinity.", false }, { 30, "Seal of Light", "spell_holy_healingaura", "Seal with a chance-based heal.", false }, { 32, "Frost Resistance Aura", "spell_frost_wizardmark", "Resist Frost.", false }, { 34, "Divine Shield", "spell_holy_divineintervention", "Immune to everything for 10 s, damage 50%, Forbearance. Life saver.", false }, { 36, "Fire Resistance Aura", "spell_fire_sealoffire", "Resist Fire.", false }, { 37, "Oath of Light (talent)", "spell_holy_greaterblessingoflight", "", true }, { 38, "Seal of Wisdom", "spell_holy_righteousnessaura", "Mana Seal: judge a mob to recover mana.", false }, { 40, "Hammer of the Righteous", "ability_paladin_hammeroftherighteous", "New: hits the target and up to 3 nearby enemies.", false }, { 40, "Blessing of Light", "spell_holy_prayerofhealing02", "Level from Bind on Forever and Tavern; Wowhead tooltip not responding.", false }, { 42, "Cleanse", "spell_holy_renew", "Removes Poison, diseases and Magic.", false }, { 42, "Holy Shock (talent)", "spell_holy_searinglight", "", true }, { 44, "Hammer of Wrath", "ability_thunderclap", "Finisher below 20% health.", false }, { 45, "Divine Favor (talent)", "spell_holy_heal", "", true }, { 46, "Blessing of Sacrifice", "spell_holy_sealofsacrifice", "Transfers damage from an ally to you.", false }, { 50, "Holy Wrath", "spell_holy_excorcism", "AoE on Undead and Demons with stun.", false }, { 52, "Greater Blessing of Might", "spell_holy_greaterblessingofkings", "Group version; requires the Symbol of Kings reagent.", false }, { 52, "Light's Vigil (talent)", "ability_paladin_judgementofthepure", "", true }, { 54, "Greater Blessing of Wisdom", "spell_holy_greaterblessingofwisdom", "Same.", false }, { 60, "Greater Blessing of Kings", "spell_magic_greaterblessingofkings", "Same.", false }, { 60, "Mass Salvation", "spell_holy_greaterblessingofsalvation", "Raid version of Salvation.", false }, { 60, "Greater Blessing of Light", "spell_holy_greaterblessingoflight", "Group version of Blessing of Light.", false } } } },
  priest = { why = { ["Wand Specialization"] = "+25% Wand damage at 2/2: early on the wand does more damage than any spell except Shadow Word: Pain (DoubleZug: “by far the most impactful talent for the early game”).", ["Spirit Tap"] = "After every kill: +100% Spirit for 15 s and mana regen even while casting. It's the engine of Priest leveling (nearly infinite mana), but you need to land the killing blow yourself.", ["Improved Shadow Word: Pain"] = "+6 s duration (24 s): +33% damage on the main DoT, but only if it reaches the end of its duration -> better to pull more mobs.", ["Shadow Focus"] = "+1%/rank Shadow hit (5/5 = +5%): the hit cap against mobs of your level is low, but it's needed against mobs 3+ levels above (DoubleZug). Icy Veins prefers Blackout.", ["Shadow Reach"] = "+10/20% Shadow spell range: SW:P from farther away to pull one mob at a time and a safer multi-DoT (DoubleZug).", ["Mind Flay"] = "Talent at 24 (3 s channel, 63 damage, 50% slow): from 24–42 it's needed to stop fleeing mobs; it becomes filler only with Improved Mind Flay + Shadowform (DoubleZug).", ["Improved Mind Flay"] = "Each Mind Flay tick does +10%/20% more than the previous one.", ["Vampiric Embrace"] = "Heals the party for 20% of Shadow damage: nearly free self-healing, perfect pair with Devouring Plague; great in dungeons and for triggering Spirit Tap in a group.", ["Shadow Weaving"] = "+2% Shadow damage per stack, up to 5 stacks (10%): efficient points, don't let it drop between mobs.", ["Silence"] = "Silences for 5 s and interrupts for 3 s (225 Mana, 45 s CD): casters do a lot of damage in Forever; also useful for moving mobs (DoubleZug).", ["Devouring Contagion"] = "25/50% mana on Devouring Plague and the DoT jumps to 2 nearby enemies when the target dies: helps multi-DoT.", ["Improved Mind Blast"] = "0.5 s/rank Mind Blast cooldown: for Flay ×2 -> Mind Blast needs 4/5 (DoubleZug, here 1 point).", ["Darkness"] = "+2%/rank Shadow damage (5/5 = +10%).", ["Shadowform"] = "The big jump at 42 (or 40): +10% Shadow damage, 50% Shadow spell mana, crit ×2, 15% physical damage taken; Mind Blast and Mind Flay become competitive with the wand. In form no healing (Heal/Renew break the form, PW:S doesn't).", ["Twin Disciplines"] = "+1%/rank damage/healing of instant spells (SW:P, Renew): small but needed for the 10 Disc points required for Meditation/IPWS.", ["Mental Strength"] = "+2%/rank Intellect: 3 points to bring the Disc branch to 10 and unlock Meditation/Inner Focus (as in DoubleZug's final 17/3/31 grid).", ["Meditation"] = "Up to 50% of continuous mana regen while casting: “extremely powerful” (DoubleZug). Now you can spam Flay/Blast in Shadowform.", ["Improved Power Word: Shield"] = "+7%/rank absorption (20% at 3/3) and less pushback; in row 3 from Oct 15.", ["Twilight Focus"] = "Holy: now protects from pushback on all spells, not just healing (DoubleZug): useful with Flay/Blast under melee.", ["Inner Focus"] = "Next spell free and +25% crit (not on DoTs); you use it on heals or Mind Blast and it doesn't interrupt the 5SR regen.", ["Mental Agility"] = "10% at 3/3 on the mana cost of Smite, Holy Fire and instant spells (SW:P, Renew, PW:S): the last points, to keep pulling longer without drinking." },
   summary = "Deep Shadow build: the most preferred by Forever guides for the Priest. Mobalytics DoubleZug ({250 }, Verified, upd. Nov 9), Twicks 147 and Kargoz 8 are Shadow; Warcraft Tavern, Icy Veins (“Deep Shadow”), wowforever.gg and wow4evernews go Shadow up to 30. All sources agree on 10–18: Wand Specialization 2/2, Spirit Tap 5/5, Improved Shadow Word: Pain 2/2; then Shadow Focus, Mind Flay at 22, Vampiric Embrace at 27, Shadow Weaving (28–30) and Shadowform at 42, without respec. The Disc hybrid with Meditation (wowforever.be = Method, Amaxagon, upd. Oct 29; ConquestCapped) remains the alternative: Disc up to 39 (only 7 Shadow points, NOT “Disc up to ~23”) and Shadow respec at 40. DoubleZug himself says the two paths perform “very similarly”; Shadow avoids the respec.", bsum = { b = "Pick B over A only if you want wowforever.be's order: Discipline with Meditation and Mental Strength up to 39, Shadow respec at 40. No reliable source says it levels faster than A." }, rot = { { "1–9 · Smite + DoT + melee", { { "spell_holy_holysmite", "Smite ×1–2" }, { "spell_shadow_shadowwordpain", "SW:P (from 4)" }, { "spell_holy_powerwordshield", "PW:S (from 6)" }, { "inv_wand_01", "Wand (from 5, craft)" } }, "1–3: Smite until the mob is low or out of mana, then melee. From 4: Smite -> Shadow Word: Pain -> Smite -> melee. If someone contests your tag, open with SW:P (DoTs tag immediately). From 6, put PW:S up before the pull. As soon as you have a Lesser Magic Wand (level 5, Enchanting, see professions), Smite almost disappears: the wand costs 0 mana and doesn't break regen." }, { "10–19 · Pre-shield, Mind Blast, DoT, wand", { { "spell_holy_powerwordshield", "PW:S" }, { "spell_shadow_unholyfrenzy", "Mind Blast" }, { "spell_shadow_shadowwordpain", "SW:P" }, { "inv_wand_01", "Wand" }, { "spell_holy_renew", "Renew (between pulls)" } }, "Pre-cast PW:S and Mind Blast (if big mob), SW:P on 2–3 mobs (not too many: DoTs need to reach ~24 s), then wand; tab-target with the wand to avoid wasting ticks. Between pulls use excess mana for Renew, Inner Fire and Power Word: Fortitude. Psychic Scream if you're in trouble and the mobs don't flee toward others (open spaces, beasts). Stop after each kill to trigger Spirit Tap." }, { "20–41 · Multi-DoT + Devouring Plague + Vampiric Embrace", { { "spell_holy_powerwordshield", "PW:S" }, { "spell_holy_searinglight", "Holy Fire / Mind Blast" }, { "spell_shadow_shadowwordpain", "SW:P" }, { "spell_shadow_devouringplague", "Devouring Plague" }, { "spell_shadow_unsummonbuilding", "Vampiric Embrace (27+)" }, { "inv_wand_01", "Wand" } }, "Prepull: PW:S, Renew, Inner Fire (and Shadowguard if Troll). Open with Holy Fire (3.5 s, efficient) or Mind Blast on tough mobs, SW:P on 2–3 mobs, Devouring Plague + Vampiric Embrace on the toughest mob and let it live until the DoT ends (strong heal). Wand as filler, tab-target to avoid overkill. Mind Flay (from 24) only to snare a fleeing mob: before 28 + Improved Mind Flay it doesn't beat DoT+wand (DoubleZug). With Devouring Contagion (33–34) put DP on the target to kill first and let the DoT jump." }, { "AoE / multiple pulls", { { "spell_shadow_shadowwordpain", "SW:P ×3" }, { "spell_shadow_psychicscream", "Psychic Scream" }, { "spell_shadow_devouringplague", "DP on the tough mob" }, { "inv_wand_01", "Wand in rotation" } }, "No real AoE (Method: “No AoE”). Multi-DoT: SW:P on 3–4 mobs (2–3 safe, unprotected), one DP on the toughest mob, wand in rotation to avoid overkill. From 33 Devouring Contagion: DP on the target to kill first and the DoT jumps. Psychic Scream if mobs reach melee; one kill to trigger Spirit Tap, then heal with PW:S/Renew." }, { "42+ · Shadowform: Mind Blast + Flay", { { "spell_shadow_shadowform", "Shadowform" }, { "spell_holy_powerwordshield", "PW:S" }, { "spell_shadow_unholyfrenzy", "Mind Blast" }, { "spell_shadow_shadowwordpain", "SW:P" }, { "spell_shadow_devouringplague", "Devouring Plague" }, { "spell_shadow_siphonmana", "Mind Flay ×2 -> Blast" } }, "Shadowform before the pull, PW:S, open with Mind Blast, SW:P, Devouring Plague on the key mob, VE if health is low; filler Mind Flay ×2 -> Mind Blast (DoubleZug), with Shadow Word: Death (trainer 32) and Mind Blast on CD. In form Heal/Renew break the form: heal with PW:S. If you don't have PW:S active and can't reapply it, use the wand (no pushback)." } },
   brot = {  },
   notes = { { "Mana and 5-second rule (DoubleZug)", "• Spirit regen stops 5 s after spending mana (including instant spells), but {not} with free spells (Inner Focus, racials at 0 cost).\n• Cast your spells all together at the start of the pull: long ones first (Holy Fire), then instants.\n• With Spirit Tap and Meditation the 5SR matters less but isn't irrelevant." }, { "DoT efficiency", "• Let SW:P and Devouring Plague run to the end of their duration: better to pull a second mob than to kill the first one too early (DoubleZug).\n• DoTs/HoTs in Forever update dynamically (no snapshot) and can crit (Warcraft Tavern, DoubleZug)." }, { "Wand in Forever", "• From Oct 15 you need to stand still 0.5 s before the wand fires (ConquestCapped); according to CC it no longer scales with spell power, but Scriblet/KamiLabs (Sep 23) saw it scale ~0.3 conflict: verify after launch." } }, stats = "Spell power and Spirit first (DoubleZug: Spirit > Spell Power > Intellect > crit/mp5 > Stamina > Hit > Haste; ConquestCapped: spell power first, Spirit equal or higher after 40–50 SP for Spirit Tap; WT: Int/Spell Damage > Stamina/Spirit > Armor). Wands are the main weapon: Lesser Magic Wand (5) -> Greater Magic Wand (13) -> Sizzle Stick (15, WC) -> Gravestone Scepter (18, BFD) -> Wand of Eventide (27, BoE) -> Greater Mystic Wand (30). Melee weapons: staff/weapon with spell power from dungeon quests (Ragefire Chasm at 10, Wailing Caverns at 15; DoubleZug: “keeping the weapon updated is MUCH more important than in Classic”). Maxroll “dungeon chase list” (names): Deadmines Emberstone Staff/Cookie’s Stirring Rod, Shadowfang Keep Odo’s Ley Staff, Stockade Kam’s Walking Stick, Blackfathom Deeps Rod of the Sleepwalker ( stats not verified). Weapon skill: Daggers, Maces, Staves, Wands (WT; trainers: Woo Ping Stormwind, Ilyenia Moonfire Darnassus, Bixi Wobblebonk Ironforge; Horde Sayoc/Hanashi Orgrimmar, Ansekhwa Thunder Bluff, Archibald Undercity).", forever = { "New spells for Priest: Penance (Disc talent, 150 Mana, 12 s CD), Prayer of Mending (Holy talent, 40), Binding Heal (Holy talent 25), Devouring Plague and Fear Ward now base at 20 (Blizzard Watch, Oct 9; WT).", "Each race has 2 racial spells (10 and 20); Gnome is new; Elune’s Grace/Starshards/Dwarf Chastise/Dark Sacrifice recreated (Blizzard Watch, Oct 9).", "SW:P and Renew can crit; DoTs update dynamically without snapshot (WT, DoubleZug).", "Beta Oct 15 (WT/ConquestCapped/wowforeverguides): Improved Power Word: Shield moved to row 3; Improved Fade removed; the wand requires 0.5 s standing still before firing (CC).", "Beta Oct 1: changes to Devouring Plague, SW:D, Inner Focus, Shadow Weaving (wowforeverguides ).", "Oct 26: The Human Spirit raised to +10% Spirit (ConquestCapped).", "Relevant new/changed talents: Wand Specialization (13/25%), Twin Disciplines, Mental Agility, Improved Inner Fire (+charges), Silent Resolve, Holy Binding, Devouring Contagion, Early Demise, Dark Inspiration, Improved Mind Flay (wf client).", "Spirit Tap: +100% Spirit and +50% regen while casting for 15 s after a non-trivial kill or an enemy death with Vampiric Embrace (wf client).", "Legacy (Talented) from levels 25/45/60 (wowforeverguides ); Thrill of Adventure and The Quick and the Dead recommended (ConquestCapped).", "At launch (Blizzard notes of 3 Nov): Power Word: Shield can be replaced by one of equal or higher rank, Shadow Word: Death no longer hurts you when it misses, Vampiric Embrace heals can no longer crit, Dark Sacrifice no longer breaks crowd control." },
   races = { ["human"] = "Alliance. The Human Spirit (+10% Spirit, upd. Oct 26) and Ruthless (+1% crit): great with Spirit Tap/Meditation. Racials: Divine Grace (10, heals ally <50% and removes Weakened Soul, NO self) and Feedback (20). DoubleZug: Human/Gnome are second-best for leveling; CC: “Weak” for leveling.", ["dwarf"] = "Alliance. Desperate Prayer (10, self-heal 146–181, 10 min CD), Chastise ( 20, 2 s root on humanoids); Stoneform / Artisan’s Precision (+1% hit, wowclassicforever.info). CC: “Average”.", ["nightelf"] = "Alliance. Starshards (10, 162 Arcane damage over 6 s, 30 s CD ) and Elune’s Grace (20, 50% chance to be hit for 15 s ), Shadowmeld usable in combat, 2% movement, Wisp Spirit, Elune’s Light. DoubleZug: “quite strong for leveling”, his first Alliance pick; CC: “Good”.", ["gnome"] = "Alliance ( new for Priest). Confounding Flash (10, confuses 5 enemies for 3 s, 2 min CD ) and Contingency Plan (20, 30 s ward: below 35% absorbs + HoT, 5–10 min CD ); Escape Artist, Expansive Mind, Eureka!. DoubleZug: Human/Gnome are close seconds; CC: “Good”.", ["undead"] = "Horde. Touch of Weakness (10) and Dark Sacrifice ( 20: lose health, gain mana + Spirit), Cannibalize (usable in combat: very strong sustain), Will of the Forsaken, Touch of the Grave (30% drain on casters). DoubleZug: “Undead/Troll” for Horde leveling; CC: “Best”.", ["troll"] = "Horde. Hex of Weakness (10, 43 AP, 20% healing received) and Shadowguard (20, 3 charges 10 min), Berserking (+10% cast speed 15 s), Beast Slaying (“gains a lot of value while leveling”, DoubleZug), Rapid Regeneration. CC: “Best”." },
   spells = { { 1, "Smite", "spell_holy_holysmite", "Holy damage with 1.5 s cast: your attack until 5 (Rank 2 at 6, 3 at 14, 4 at 22, 5 at 30).", false }, { 1, "Lesser Heal", "spell_holy_lesserheal", "Base heal (Rank 2 at 4, Rank 3 at 10); replaced by Heal at 16.", false }, { 1, "Power Word: Fortitude", "spell_holy_wordfortitude", "1 h Stamina buff on you and the group (Rank 2 at 12, 3 at 24, 4 at 36).", false }, { 4, "Shadow Word: Pain", "spell_shadow_shadowwordpain", "Your main DoT (18 s, 24 s with Imp. SW:P); tags mobs on the fly. Rank 2 at 10, 3 at 18, 4 at 26, 5 at 34.", false }, { 6, "Power Word: Shield", "spell_holy_powerwordshield", "Absorbs damage and prevents pushback while active; “Weakened Soul” 15 s. Rank 2 at 12, 3 at 18, 4 at 24, 5 at 30, 6 at 36.", false }, { 8, "Fade", "spell_magic_lesserinvisibilty", "Reduces threat for 10 s; only useful in a group (Rank 2 at 20, 3 at 30).", false }, { 8, "Renew", "spell_holy_renew", "Can crit in Forever; 15 s HoT, your base heal between pulls (Rank 2 at 14, 3 at 20, 4 at 26, 5 at 32).", false }, { 10, "Mind Blast", "spell_shadow_unholyfrenzy", "Shadow hit 1.5 s, 8 s CD: open with this on big mobs. Rank 2 at 16, 3 at 22, 4 at 28, 5 at 34.", false }, { 10, "Resurrection", "spell_holy_resurrection", "Resurrects a player out of combat (Rank 2 at 22, 3 at 34).", false }, { 10, "Racial 1 (class quest)", "inv_misc_note_01", "Racial spell at 10: Divine Grace (Human), Desperate Prayer (Dwarf), Starshards (Night Elf), Confounding Flash (Gnome), Touch of Weakness (Undead), Hex of Weakness (Troll). See races.", false }, { 12, "Inner Fire", "spell_holy_innerfire", "+315 armor, 20 charges (consumed with every hit taken): keep it always active, PW:S protects the charges. Rank 2 at 20, 3 at 30.", false }, { 14, "Psychic Scream", "spell_shadow_psychicscream", "Fear on 2 enemies within 8 yd (8 s), 30 s CD. DON’T skip it (DoubleZug): the Priest's emergency. Watch out for adds.", false }, { 14, "Cure Disease", "spell_holy_nullifydisease", "Removes 1 disease: Forever has some annoying ones (DoubleZug).", false }, { 16, "Heal", "spell_holy_heal", "3 s cast heal (260–300 Rank 1): the “heavy” heal only when you're under shield/fear. Rank 2 at 22, 3 at 28.", false }, { 18, "Dispel Magic", "spell_holy_dispelmagic", "Removes 1 buff from an enemy or 1 debuff from an ally; usually better to just kill faster.", false }, { 20, "Devouring Plague", "spell_shadow_devouringplague", "Now base for everyone (was Undead): 24 s DoT for 128 that heals you for the damage; 24 s CD in the client (Blizzard Watch, Oct 9: 1 min). Rank 2 at 28, 3 at 36.", false }, { 20, "Fear Ward", "spell_holy_excorcism", "Now base for everyone (was Dwarf): 3 min duration, 3 min CD.", false }, { 20, "Flash Heal", "spell_holy_flashheal", "Fast 1.5 s heal for emergencies (Rank 2 at 26, 3 at 32).", false }, { 20, "Holy Fire", "spell_holy_searinglight", "3.5 s cast: 53–65 Holy + 20 DoT; more efficient than Mind Blast but long (Rank 2 at 24, 3 at 30).", false }, { 20, "Mind Soothe", "spell_holy_mindsooth", "Reduces by 10 yd the range from which a humanoid (40) attacks you, 15 s (utility).", false }, { 20, "Shackle Undead", "spell_nature_slow", "Shackles an undead for 30 s (useful CC in Tirisfal/Duskwood/Silverpine).", false }, { 20, "Racial 2 (class quest)", "inv_misc_note_01", "Racial spell at 20: Feedback (Human), Chastise (Dwarf), Elune’s Grace (Night Elf), Contingency Plan (Gnome), Dark Sacrifice (Undead), Shadowguard (Troll).", false }, { 22, "Mind Vision", "spell_holy_mindvision", "See through the target's eyes (utility).", false }, { 22, "Mind Flay", "spell_shadow_siphonmana", "Shadow talent: 3 s channel, 63 damage, 50% slow (stop fleeing mobs). Filler with Improved Mind Flay + Shadowform.", true }, { 24, "Mana Burn", "spell_shadow_manaburn", "Burns mana of an enemy caster (3 s cast); can be skipped in PvE.", false }, { 25, "Binding Heal", "spell_holy_blindingheal", "Holy talent (not in the build): heals target + you. Rank 2 at 32.", false }, { 27, "Vampiric Embrace", "spell_shadow_unsummonbuilding", "Shadow talent: heals the party for 20% of Shadow damage over 30 s, 30 s CD.", true }, { 30, "Divine Spirit", "spell_holy_divinespirit", "1 h Spirit buff (+17 Rank 1): great with Spirit Tap/Meditation; requires a Spirit-friendly party.", false }, { 30, "Mind Control", "spell_shadow_shadowworddominate", "Controls a humanoid until 44 (PvE: CC/utility).", false }, { 30, "Prayer of Healing", "spell_holy_prayerofhealing02", "3 s group heal (dungeons only).", false }, { 30, "Shadow Protection", "spell_shadow_antishadow", "Shadow resist +30 for 10 min.", false }, { 30, "Penance", "spell_holy_penance", "New spell (Disc talent, 150 Mana, 12 s CD; the client lists it as Lv 30): 45 Holy ×3 or 134 heal ×3. Not in the Shadow build: only in Disc/hybrid variants (Penance at 37). Rank 2 at 40, 3 at 50, 4 at 60.", false }, { 32, "Shadow Word: Death", "spell_shadow_demonicfortitude", "New Trainer skill at 32 (Method, WT ): instant Shadow hit, 12 s CD; Early Demise boosts it.", false }, { 32, "Abolish Disease", "spell_nature_nullifydisease", "Cures diseases over time.", false }, { 32, "Silence", "spell_shadow_impphaseshift", "Shadow talent: silences for 5 s and interrupts for 3 s, 225 Mana, 45 s CD.", true }, { 34, "Levitate", "spell_holy_layonhands", "Reagent Light Feather: float, fall more slowly, walk on water.", false }, { 40, "Greater Heal", "spell_holy_greaterheal", "Big 3 s heal (819–920 Rank 1); at 40 also Mind Blast Rank 6, Mind Flay Rank 3, Inner Fire Rank 4, PW:Fortitude/Divine Spirit Rank 2; talents Power Infusion (Disc, +20% spell) and Prayer of Mending (Holy).", false }, { 42, "Power Word: Shield (Rank 7)", "spell_holy_powerwordshield", "Rank 7 at 42, 8 at 48, 9 at 54, 10 at 60; SW:P Rank 6 at 42, 7 at 50, 8 at 58.", false }, { 42, "Shadowform", "spell_shadow_shadowform", "Shadow talent (capstone): +10% Shadow damage, 50% mana, crit ×2, 15% physical damage; no healing in form.", true }, { 48, "Prayer of Fortitude", "spell_holy_prayeroffortitude", "Group Stamina buff (Rank 2 at 60). Prayer of Spirit at 60.", false }, { 60, "Prayer of Spirit", "spell_holy_prayerofspirit", "Group Spirit buff; at 60 also Penance Rank 4, Mind Flay Rank 6.", false }, { 60, "Inner Focus", "spell_frost_windwalkon", "Disc talent: next spell free and +25% crit, 3 min CD.", true } },
   bsp = { b = { { 1, "Smite", "spell_holy_holysmite", "Holy damage with 1.5 s cast: your attack until 5 (Rank 2 at 6, 3 at 14, 4 at 22, 5 at 30).", false }, { 1, "Lesser Heal", "spell_holy_lesserheal", "Base heal (Rank 2 at 4, Rank 3 at 10); replaced by Heal at 16.", false }, { 1, "Power Word: Fortitude", "spell_holy_wordfortitude", "1 h Stamina buff on you and the group (Rank 2 at 12, 3 at 24, 4 at 36).", false }, { 4, "Shadow Word: Pain", "spell_shadow_shadowwordpain", "Your main DoT (18 s, 24 s with Imp. SW:P); tags mobs on the fly. Rank 2 at 10, 3 at 18, 4 at 26, 5 at 34.", false }, { 6, "Power Word: Shield", "spell_holy_powerwordshield", "Absorbs damage and prevents pushback while active; “Weakened Soul” 15 s. Rank 2 at 12, 3 at 18, 4 at 24, 5 at 30, 6 at 36.", false }, { 8, "Fade", "spell_magic_lesserinvisibilty", "Reduces threat for 10 s; only useful in a group (Rank 2 at 20, 3 at 30).", false }, { 8, "Renew", "spell_holy_renew", "Can crit in Forever; 15 s HoT, your base heal between pulls (Rank 2 at 14, 3 at 20, 4 at 26, 5 at 32).", false }, { 10, "Mind Blast", "spell_shadow_unholyfrenzy", "Shadow hit 1.5 s, 8 s CD: open with this on big mobs. Rank 2 at 16, 3 at 22, 4 at 28, 5 at 34.", false }, { 10, "Resurrection", "spell_holy_resurrection", "Resurrects a player out of combat (Rank 2 at 22, 3 at 34).", false }, { 10, "Racial 1 (class quest)", "inv_misc_note_01", "Racial spell at 10: Divine Grace (Human), Desperate Prayer (Dwarf), Starshards (Night Elf), Confounding Flash (Gnome), Touch of Weakness (Undead), Hex of Weakness (Troll). See races.", false }, { 12, "Inner Fire", "spell_holy_innerfire", "+315 armor, 20 charges (consumed with every hit taken): keep it always active, PW:S protects the charges. Rank 2 at 20, 3 at 30.", false }, { 14, "Psychic Scream", "spell_shadow_psychicscream", "Fear on 2 enemies within 8 yd (8 s), 30 s CD. DON’T skip it (DoubleZug): the Priest's emergency. Watch out for adds.", false }, { 14, "Cure Disease", "spell_holy_nullifyd