ForeverPathfinderProfs = {
 it = { ranks = { { 75, "Journeyman", 10, 50 }, { 150, "Expert", 20, 125 }, { 225, "Artisan", 35, 200 } }, src = "Percorsi: wowforever.be, calcolati dai dati del client (build 1.60.1.70862, 7 nov 2026) con le ricette del trainer. Le ricette gialle e verdi non danno sempre un punto: i conteggi hanno un margine, potrebbero servirne meno. Skinning: Warcraft Tavern.",
  picks = { warrior = "Mining + Blacksmithing in leveling: barre proprie e armi e armature crafted. Endgame Engineering + Mining (Gfinity: 'At max level, Engineering is a must'). Fonti: Gfinity (6 ott).", paladin = "Mining + Blacksmithing per Prot e Ret. Holy: Herbalism + Alchemy (Gfinity), per il consumo di mana. Fonti.", hunter = "Skinning + Leatherworking in leveling (cuoio sempre pronto). Endgame Engineering + Mining (Gfinity: 'peak synergy with Hunters'). Fonti.", rogue = "Skinning + Leatherworking: cuoio dalle bestie mentre fai quest (Gfinity). PvP: Engineering + Mining . Fonti.", priest = "Tailoring + Enchanting in leveling. Endgame Tailoring + Engineering (Gfinity: movement speed e difensivi da Engineering). Fonti.", shaman = "Skinning + Leatherworking in leveling (Gfinity). Resto ed Elemental: Herbalism + Alchemy . Fonti.", mage = "Tailoring + Enchanting in leveling. Dungeon e speedrun: Engineering + Mining con granate (Gfinity). Fonti.", warlock = "Tailoring + Enchanting in leveling. Economia e raid: Herbalism + Alchemy (Gfinity). Fonti.", druid = "Skinning + Leatherworking in leveling (Gfinity). Open world: Herbalism + Alchemy, raccolta in Travel Form (Gfinity). Fonti." },
  order = { "Mining", "Herbalism", "Alchemy", "Blacksmithing", "Enchanting", "Engineering", "Leatherworking", "Skinning", "Tailoring", "Cooking", "First Aid", "Fishing" },
  list = {
   ["Mining"] = { icon = "trade_mining", type = "gathering", altTitle = "Oppure fondendo (fino a 185)", how = {  },
    route = { { 1, 65, "Copper Vein", 0, "inv_ore_copper_01", 0, {  }, "Qualsiasi zona iniziale" }, { 65, 125, "Copper Vein, Tin Vein, Silver Vein", 0, "inv_stone_16", 0, {  }, "Ashenvale, Redridge Mountains, The Barrens, Thousand Needles" }, { 125, 175, "Tin Vein, Silver Vein, Iron Deposit, Gold Vein", 0, "inv_ore_gold_01", 0, {  }, "Arathi Highlands, Desolace, Stranglethorn Vale, Thousand Needles" }, { 175, 225, "Gold Vein, Mithril Deposit, Truesilver Deposit", 0, "inv_ore_truesilver_01", 0, {  }, "Azshara, Tanaris, The Hinterlands" }, { 225, 245, "Mithril Deposit, Truesilver Deposit, Dark Iron Deposit", 0, "inv_ore_mithril_01", 0, {  }, "Searing Gorge, Burning Steppes, Badlands, The Hinterlands" }, { 245, 275, "Truesilver Deposit, Small Thorium Vein", 0, "inv_ore_thorium_02", 0, {  }, "Un'Goro Crater, Winterspring, Silithus, Feralas, Eastern e Western Plaguelands" }, { 275, 300, "Small Thorium Vein, Rich Thorium Vein", 0, "inv_ore_thorium_02", 0, {  }, "Un'Goro Crater, Winterspring, Burning Steppes, Eastern e Western Plaguelands" } },
    alt = { { 1, 65, "Smelt Copper", 0, "inv_ingot_02", 130, { { 130, "Copper Ore", 2770, "inv_ore_copper_01", 0 } }, "" }, { 65, 75, "Smelt Tin", 0, "inv_ingot_05", 60, { { 60, "Tin Ore", 2771, "inv_ore_tin_01", 0 } }, "" }, { 75, 100, "Smelt Bronze", 0, "inv_ingot_bronze", 60, { { 60, "Copper Bar", 2840, "inv_ingot_02", 0 }, { 60, "Tin Bar", 3576, "inv_ingot_05", 0 } }, "" }, { 100, 125, "Smelt Silver", 0, "inv_ingot_01", 70, { { 70, "Silver Ore", 2775, "inv_stone_16", 0 } }, "" }, { 125, 140, "Smelt Iron", 0, "inv_ingot_iron", 35, { { 35, "Iron Ore", 2772, "inv_ore_iron_01", 0 } }, "" }, { 140, 155, "Solo minando: nessuna barra dà skill qui", 0, "trade_mining", 0, {  }, "" }, { 155, 185, "Smelt Gold", 0, "inv_ingot_03", 60, { { 60, "Gold Ore", 2776, "inv_ore_gold_01", 0 } }, "" } },
    forever = { "Lodestone (Mining 20): camp object con fino a 90 Attack Power in mischia, come Blessing of Might (wowforever.be camping; Warcraft Tavern concorda).", "Rock Garden (140, blueprint) e Molten Foundry (300, blueprint): camp Tier 2 e 3. Il Rock Garden fa comparire minerale comune col tempo; la Molten Foundry serve per le fusioni alte (wowforever.be).", "Perk Legacy Made of Metal: salute totale +5% e minerale in più dai nodi (wowforever.be hub, da immagini BlizzCon: numeri non definitivi) .", "Nuovi minerali endgame: Heavy Thorium Ore, Legionite Bar, Azerothium Bar (smelt a 275, istruttore) (wowforever.be).", "Materiali Scarce: a volte minando si ottengono Pyrite, Bauxite o Pitchblende (wowforever.be)." }, camp = "Lodestone (Mining 20): Attack Power in mischia fino a 90 per chi siede vicino. Tier 2 Rock Garden (140), Tier 3 Molten Foundry (300).", gold = "Vendi i grezzi in AH: ore e barre sono usate da fabbri, ingegneri, incantatori e sarti (wowforever.be). Prezzi di vendita: non trovati nelle fonti lette. Le barre endgame (Legionite, Heavy Thorium, Azerothium) non hanno prezzi verificati.", tips = { "Fondi fino a 185, poi mina: dopo 185 la fusione non dà più skill (wowforever.be).", "Non deviare per Tin dopo 165 o per Silver dopo 175: non danno più skill.", "Il percorso 225–300 non è ancora documentato: controlla in gioco." } },
   ["Herbalism"] = { icon = "trade_herbalism", type = "gathering", altTitle = "", how = {  },
    route = { { 1, 70, "Peacebloom, Silverleaf, Earthroot (da 15)", 0, "inv_misc_herb_07", 0, {  }, "Qualsiasi zona iniziale" }, { 70, 115, "Mageroyal, Briarthorn, Stranglekelp", 0, "inv_misc_herb_11", 0, {  }, "Darkshore, Loch Modan, Silverpine Forest" }, { 115, 170, "Stranglekelp, Bruiseweed, Wild Steelbloom, Kingsblood (da 125), Liferoot (da 150)", 0, "inv_misc_root_02", 0, {  }, "Hillsbrad Foothills, Wetlands, Stonetalon Mountains" }, { 170, 205, "Kingsblood, Liferoot, Fadeleaf, Goldthorn, Khadgar's Whisker (da 185)", 0, "inv_misc_herb_08", 0, {  }, "Stranglethorn Vale, Arathi Highlands" }, { 205, 225, "Fadeleaf, Goldthorn, Khadgar's Whisker, Wintersbite, Firebloom, Purple Lotus", 0, "inv_misc_herb_17", 0, {  }, "Alterac Mountains, Tanaris, Searing Gorge" }, { 225, 270, "Purple Lotus, Firebloom, Sungrass (da 230), Ghost Mushroom (da 245), Gromsblood (da 250), Golden Sansam (da 260)", 0, "inv_misc_herb_sansamroot", 0, {  }, "The Hinterlands, Tanaris, Searing Gorge" }, { 270, 300, "Golden Sansam, Dreamfoil, Mountain Silversage (da 280), Plaguebloom (da 285), Icecap (da 290)", 0, "inv_misc_herb_icecap", 0, {  }, "Felwood, Un'Goro Crater, Winterspring, Eastern e Western Plaguelands" } },
    alt = {  },
    forever = { "Goldthorn Tea: +15 Herbalism per un po', nuovo in Forever (wowforever.be).", "Greenhouse (140) e Seed Hybridizer (300): camp Tier 2 fa crescere erbe da semi, Tier 3 moltiplica i semi o ne crea di più rari (wowforever.be camping).", "Semi di erba: Commonplace, Uncommon, Unusual, Scarce Herb Seeds; materiali Scarce Frilled Lichen, Rosecap, Stranglevine (wowforever.be).", "Erbe endgame nuove: Marefoil, Demonsage, Death Lotus (wowforever.be; posizione e skill non noti).", "Tauren Cultivation: ora duplica un'erba vicina invece di dare un bonus fisso (wowforever.be).", "Perk di professione Natural Talent: più resistenza alle scuole di magia, più probabilità di loto raro e più erbe per nodo (wowforever.be hub; numeri non definitivi) ." }, camp = "Incense Candle (Herbalism 20, vedi common.json). Tier 2 Greenhouse (140) fa crescere erbe da semi. Tier 3 Seed Hybridizer (300) moltiplica i semi.", gold = "Vendi i grezzi in AH. WT: le erbe comuni calano di prezzo in fretta, le rare (es. Black Lotus) valgono di più. Prezzi specifici: non trovati. Alchemy è il consumatore principale delle erbe (WT, wowforever.be).", tips = { "Nessuno strumento necessario: attiva Find Herbs per vedere le erbe sulla minimappa (wowforever.be FAQ).", "Le erbe a volte danno anche semi: non buttarli, i livelli di camp li usano (wowforever.be).", "Cultivation dei Tauren richiede un livello minimo dal 27 settembre (wowforever.be)." } },
