    alt = {  },
    forever = { "No gathering node: dusts, essences and shards only come from Disenchanting Green or higher gear (WT). Wowforever.be lists it among the crafts.", "Enchants for rings, shard transmutation to a higher tier, rod crafting (wowforever.be overview).", "63 new recipes out of 239 (wowforever.be Enchanting).", "Novice's Practice Wand craftable at Enchanting 1; wands gain Spell Power from lvl 5 (WT)." }, camp = "Enchanted Lute (20): armor, stats and resistances like Mark of the Wild (wowforever.be; effect in common.json). Tier 2 Arcane Salvager (140): 2 Vision Dust and Lesser Nether Essence. Tier 3 Arcane Forge (300). The effect of disenchanting at the Salvager is not known yet.", gold = "The guides agree: farm the materials instead of buying them on AH (snippet, ). Arcane Dust is the bottleneck at every band (snippet, ). Sale prices: not found.", tips = { "Suggested pair with Tailoring: Tailoring provides cloth from humanoids, Enchanting recycles gear (WT, Gfinity).", "Disenchanting Green or higher gear gives materials: the material depends on the item's level (WT)." } },
