    forever = { "Camp: Reagent Bot (reagent vendor), Repair Bot (repairs), Anarchist's Workbench (WT, wowforever.be).", "Goblin or Gnomish specialization, with a quest chain after 200 (wowforever.be, WT).", "Gnome: Engineering Specialization reduces the chance gadgets break (WT).", "78 new recipes out of 252 total (wowforever.be Engineering)." }, camp = "Reagent Bot (20): no stat buff, only a reagent vendor. Repair Bot (140): reagents, selling and repairs. Anarchist's Workbench (300): station for certain schematics (wowforever.be camping).", gold = "Reagent Bot: vendor to buy and sell reagents at camp (WT). Gadgets and bombs: prices not found. Gadget prices: not found.", tips = { "Suggested pair with Mining for PvP, utility and fun (WT). For endgame Mage and Warrior: Engineering + Mining (Gfinity).", "The Reagent Bot is a reagent vendor: buys and sells at camp (WT)." } },
