   ["Fishing"] = { icon = "trade_fishing", type = "secondary", altTitle = "", how = { Expert = "the book Expert Fishing - The Bass and You, from Old Man Heming in Booty Bay", Artisan = "the quest Nat Pagle, Angler Extreme (from level 35)" },
    route = { { 1, 75, "Fishing", 0, "trade_fishing", 0, {  }, "Any starting zone. Below 25 skill use a Shiny Bauble" }, { 75, 150, "Fishing", 0, "trade_fishing", 0, {  }, "A capital: Stormwind, Ironforge or Darnassus (Alliance); Orgrimmar, Thunder Bluff or Undercity (Horde)" }, { 150, 225, "Fishing", 0, "trade_fishing", 0, {  }, "Dustwallow Marsh (easier for the Alliance) or Stranglethorn Vale (easier for the Horde); use lures" }, { 225, 300, "Fishing", 0, "trade_fishing", 0, {  }, "Not in the guide yet: the zones you can fish from 205 are Azshara, Feralas, The Hinterlands, Tanaris, Un’Goro Crater" } },
