    forever = { "Fishing Rack (140) and Fishing Hut (300): camp Tier 2 and 3 for baits and uncommon and rare fish (wowforever.be camping).", "Stronger fish-based food: Baked Salmon, Poached Sunscale Salmon, Plated Armorfish (wowforever.be Fishing).", "Legacy Luremaster: +25% chance of an extra fish with an active bait (WT, wowforever.be) ." }, camp = "Fish Bowl (8% to all stats, in common.json). Tier 2 Fishing Rack (140): uncommon baits and fish. Tier 3 Fishing Hut (300): rare baits and fish.", gold = "Raw fish sold on AH or used for Cooking (wowforever.be). Figures: not found.", tips = { "Shamans reach the fishing pools more easily with Far Sight and Water Walking; Hunters give raw fish to their pet (wowforever.be).", "Cooking + Fishing for everyone: +5% XP from food (WT)." } },
  } },
 es = { ranks = { { 75, "Journeyman", 10, 50 }, { 150, "Expert", 20, 125 }, { 225, "Artisan", 35, 200 } }, src = "Rutas: wowforever.be, calculadas a partir de los datos del cliente (build 1.60.1.70862, 7 nov 2026) con las recetas de los entrenadores. Las recetas amarillas y verdes no siempre dan punto: las cifras tienen un margen, puede que necesites menos. Skinning: Warcraft Tavern.",
  picks = { warrior = "Mining + Blacksmithing en la subida: tus propias barras y armas y armaduras fabricadas. Engineering + Mining de fin de partida (Gfinity: «Al nivel máximo, Engineering es imprescindible»). Fuentes: Gfinity (6 oct).", paladin = "Mining + Blacksmithing para Prot y Ret. Holy: Herbalism + Alchemy (Gfinity), por el consumo de maná. Fuentes.", hunter = "Skinning + Leatherworking en la subida (siempre hay cuero listo). Engineering + Mining de fin de partida (Gfinity: «sinergia máxima con Hunters»). Fuentes.", rogue = "Skinning + Leatherworking: cuero de bestias mientras haces misiones (Gfinity). PvP: Engineering + Mining. Fuentes.", priest = "Tailoring + Enchanting en la subida. Fin de partida Tailoring + Engineering (Gfinity: velocidad de movimiento y defensas de Engineering). Fuentes.", shaman = "Skinning + Leatherworking en la subida (Gfinity). Restoration y Elemental: Herbalism + Alchemy. Fuentes.", mage = "Tailoring + Enchanting en la subida. Mazmorras y speedrun: Engineering + Mining con granadas (Gfinity). Fuentes.", warlock = "Tailoring + Enchanting en la subida. Economía y bandas: Herbalism + Alchemy (Gfinity). Fuentes.", druid = "Skinning + Leatherworking en la subida (Gfinity). Mundo abierto: Herbalism + Alchemy, recolectando en Travel Form (Gfinity). Fuentes." },
  order = { "Mining", "Herbalism", "Alchemy", "Blacksmithing", "Enchanting", "Engineering", "Leatherworking", "Skinning", "Tailoring", "Cooking", "First Aid", "Fishing" },
