    alt = {  },
    forever = { "Repair All: repara todo tu equipo de una vez (wowforever.be).", "Hebillas que añaden un hueco al cinturón (wowforever.be).", "Strange Copper Boots y Glowing Copper Boots: mejores estadísticas para clases híbridas (WT).", "197 recetas nuevas de 462 en total (wowforever.be Blacksmithing)." }, camp = "Sharpening Wheel (20): Strength hasta 34, como Strength of Tótem de tierra. Yunque de nivel 2 (140): fabricar en cualquier sitio (5 Lingote de bronce, 2 Piedra de pulir burda, 2 Cuero medio). Forja maestra de nivel 3 (300): Corazón de gólem, 5 Lingote de torio, 2 Cuero basto.", gold = "WT: «Blacksmithing da una forma real de generar oro», vendiendo Rods & Keys y objetos Bind-on-Equip. Cifras: no encontradas. Method sugiere enviar armaduras y armas BoE a un alt de banco (ver alts).", tips = { "Elige Armorsmith o Weaponsmith según tu principal: la especialización se desbloquea tras 200 (WT).", "Los objetos BoE se venden en la AH solo si el precio supera al del vendedor (ver common.json)." } },
   ["Enchanting"] = { icon = "trade_engraving", type = "crafting", altTitle = "", how = {  },
