    forever = { "Casi toda la comida: +5% de XP de muertes mientras estás Well Fed (Cooking de wowforever.be, WT).", "Vara para remover galletas (Deadmines): cocina un 25% más rápido (wowforever.be).", "Recetas nuevas: Pez coraza de placas, Savory Whimsyfin Delight, Salmón al horno y Salmón escama de sol pochado mejorado (wowforever.be).", "Cooking enciende el fuego en cada campamento (campamento de wowforever.be)." }, camp = "Basic Campfire (Cooking 1, entrenador): 3 objetos. Journeyman Campfire (plano Cooking 90, cae de Deadmines y Cuevas de los Lamentos): 5 objetos. Expert Campfire (plano Cooking 200): 10 objetos. Nivel 2 Cookie's Feast (140): comida con buff de Stamina. Nivel 3 Iron Oven (300).", gold = "El pescado es la ruta más sencilla: recetas baratas, pescado crudo barato en la AH (wowforever.be). Cifras de venta de comida: no encontradas.", tips = { "Para Artesano: Carne de almeja sabrosa de la Almeja de boca grande (costa este de Tanaris) y Huevo gigante de los monstruos Sandfury (wowforever.be).", "Cooking y Fishing se recomiendan para todos; no ocupan las ranuras de profesión principal (WT)." } },
   ["First Aid"] = { icon = "inv_misc_bandage_01", type = "secondary", altTitle = "", how = { Expert = "el libro Primeros auxilios para expertos: Entre vendas", Artisan = "la misión Triage (desde nivel 35)" },
    route = { { 1, 44, "Venda de lino", 1251, "inv_misc_bandage_15", 48, { { 48, "Paño de lino", 2589, "inv_fabric_linen_01", 0 } }, "" }, { 44, 84, "Poción de curación menor", 118, "inv_potion_49", 62, { { 62, "Vial vacío", 3371, "inv_potion_84", 1 }, { 62, "Especias suaves", 2678, "inv_misc_food_wheat_02", 1 }, { 62, "Peacebloom", 2447, "inv_misc_flower_02", 0 } }, "" }, { 84, 129, "Venda de lana", 3530, "inv_misc_bandage_14", 80, { { 80, "Paño de lana", 2592, "inv_fabric_wool_01", 0 } }, "" }, { 129, 153, "Venda de lana pesada", 3531, "inv_misc_bandage_17", 39, { { 78, "Paño de lana", 2592, "inv_fabric_wool_01", 0 } }, "" }, { 153, 210, "Venda de seda", 6450, "inv_misc_bandage_01", 228, { { 228, "Paño de seda", 4306, "inv_fabric_silk_01", 0 } }, "" }, { 210, 252, "Venda de paño mágico", 8544, "inv_misc_bandage_19", 72, { { 72, "Tela de paño mágico", 4338, "inv_fabric_mageweave_01", 0 } }, "" }, { 252, 260, "Venda de paño mágico pesado", 8545, "inv_misc_bandage_20", 11, { { 22, "Tela de paño mágico", 4338, "inv_fabric_mageweave_01", 0 } }, "" }, { 260, 300, "Venda de paño rúnico", 14529, "inv_misc_bandage_11", 65, { { 65, "Runecloth", 14047, "inv_fabric_purplefire_01", 0 } }, "" } },
    alt = {  },
    forever = { "Crea pociones de curación, trasladadas desde Alchemy (wowforever.be First Aid, WT). Funcionan en combate: útil también para sanadores.", "Remedios para veneno, enfermedad y sangrado (nuevos para enfermedad y sangrado, no usables en combate) (wowforever.be).", "Toxin Study (140) y Plague Doctor's Laboratory (300): campamento de nivel 2 y 3 para pociones y cataplasmas (campamento de wowforever.be)." }, camp = "First Aid Kit (Stamina hasta 56, en common.json). Nivel 2 Toxin Study (140). Nivel 3 Plague Doctor's Laboratory (300).", gold = "Pociones de curación usadas varias veces en combate: demanda constante. Precios: no encontrados.", tips = { "Secundaria: no ocupa una de las dos ranuras principales, y cualquiera puede tenerla (WT).", "El libro Expert First Aid también está en la AH (wowforever.be)." } },
   ["Fishing"] = { icon = "trade_fishing", type = "secondary", altTitle = "", how = { Expert = "el libro Pesca para expertos: La lubina y tú, de Viejo Heming en Booty Bay", Artisan = "la misión Nat Pagle, pescador del extremo (desde nivel 35)" },
    route = { { 1, 75, "Pesca", 0, "trade_fishing", 0, {  }, "Cualquier zona inicial. Por debajo de 25 de habilidad usa un Adorno lustroso" }, { 75, 150, "Pesca", 0, "trade_fishing", 0, {  }, "Una capital: Stormwind, Forjaz o Darnassus (Alianza); Orgrimmar, Cima del Trueno o Entrañas (Horda)" }, { 150, 225, "Pesca", 0, "trade_fishing", 0, {  }, "Marjal Revolcafango (más fácil para la Alianza) o Vega de Tuercespina (más fácil para la Horda); usa cebos" }, { 225, 300, "Pesca", 0, "trade_fishing", 0, {  }, "Todavía no está en la guía: las zonas donde puedes pescar desde 205 son Azshara, Feralas, Tierras del Interior, Tanaris, Cráter de Un’Goro" } },
    alt = {  },
    forever = { "Fishing Rack (140) y Fishing Hut (300): campamento de nivel 2 y 3 para cebos y peces poco comunes y raros (campamento de wowforever.be).", "Comida de pescado más fuerte: Salmón al horno, Salmón escama de sol pochado, Pez coraza de placas (wowforever.be Fishing).", "Legacy Luremaster: +25% de probabilidad de un pez extra con un cebo activo (WT, wowforever.be) ." }, camp = "Fish Bowl (8% a todas las estadísticas, en common.json). Nivel 2 Fishing Rack (140): cebos y peces poco comunes. Nivel 3 Fishing Hut (300): cebos y peces raros.", gold = "Pescado crudo vendido en la AH o usado para Cooking (wowforever.be). Cifras: no encontradas.", tips = { "Los chamanes llegan a los estanques de pesca más fácilmente con Far Sight y Water Walking; los Hunters dan pescado crudo a su mascota (wowforever.be).", "Cooking + Fishing para todos: +5% de XP por la comida (WT)." } },
  } },
 fr = { ranks = { { 75, "Journeyman", 10, 50 }, { 150, "Expert", 20, 125 }, { 225, "Artisan", 35, 200 } }, src = "Itinéraires : wowforever.be, calculés à partir des données du client (build 1.60.1.70862, 7 nov. 2026) avec les recettes des entraîneurs. Les recettes jaunes et vertes ne donnent pas toujours un point : les chiffres ont une marge, il se peut que vous en ayez besoin de moins. Skinning : Warcraft Tavern.",
  picks = { warrior = "Minage + Forge en progression : vos propres barres, armes et armures fabriquées. Ingénierie + Minage en fin de jeu (Gfinity : « At max level, Engineering is a must »). Sources : Gfinity (6 oct.).", paladin = "Minage + Forge pour Prot et Ret. Holy : Herboristerie + Alchimie (Gfinity), pour la consommation de mana. Sources.", hunter = "Dépeçage + Travail du cuir en progression (le cuir est toujours prêt). Ingénierie + Minage en fin de jeu (Gfinity : « synergie maximale avec les Chasseurs »). Sources.", rogue = "Dépeçage + Travail du cuir : cuir des bêtes pendant les quêtes (Gfinity). PvP : Ingénierie + Minage. Sources.", priest = "Couture + Enchantement en progression. Fin de jeu Couture + Ingénierie (Gfinity : vitesse de déplacement et défensives grâce à l'Ingénierie). Sources.", shaman = "Dépeçage + Travail du cuir en progression (Gfinity). Restoration et Elemental : Herboristerie + Alchimie. Sources.", mage = "Couture + Enchantement en progression. Donjons et speedrun : Ingénierie + Minage avec des grenades (Gfinity). Sources.", warlock = "Couture + Enchantement en progression. Économie et raids : Herboristerie + Alchimie (Gfinity). Sources.", druid = "Dépeçage + Travail du cuir en progression (Gfinity). Monde ouvert : Herboristerie + Alchimie, récolte en Travel Form (Gfinity). Sources." },
  order = { "Mining", "Herbalism", "Alchemy", "Blacksmithing", "Enchanting", "Engineering", "Leatherworking", "Skinning", "Tailoring", "Cooking", "First Aid", "Fishing" },
  list = {
   ["Mining"] = { icon = "trade_mining", type = "gathering", altTitle = "Ou par fonte (jusqu’à 185)", how = {  },
    route = { { 1, 65, "Filon de cuivre", 0, "inv_ore_copper_01", 0, {  }, "N’importe quelle zone de départ" }, { 65, 125, "Filon de cuivre, Filon d'étain, Filon d'argent", 0, "inv_stone_16", 0, {  }, "Ashenvale, Les Carmines, Les Tarides, Mille pointes" }, { 125, 175, "Filon d'étain, Filon d'argent, Gisement de fer, Filon d'or", 0, "inv_ore_gold_01", 0, {  }, "Hautes-terres d'Arathi, Desolace, Vallée de Strangleronce, Mille pointes" }, { 175, 225, "Filon d'or, Gisement de mithril, Gisement de vrai-argent", 0, "inv_ore_truesilver_01", 0, {  }, "Azshara, Tanaris, Les Hinterlands" }, { 225, 245, "Gisement de mithril, Gisement de vrai-argent, Gisement de sombrefer", 0, "inv_ore_mithril_01", 0, {  }, "Gorge des Vents brûlants, Steppes ardentes, Terres ingrates, Les Hinterlands" }, { 245, 275, "Gisement de vrai-argent, Petit filon de thorium", 0, "inv_ore_thorium_02", 0, {  }, "Cratère d'Un'Goro, Berceau-de-l'Hiver, Silithus, Féralas, Maleterres de l'est et de l'ouest" }, { 275, 300, "Petit filon de thorium, Riche filon de thorium", 0, "inv_ore_thorium_02", 0, {  }, "Cratère d'Un'Goro, Berceau-de-l'Hiver, Steppes ardentes, Maleterres de l'est et de l'ouest" } },
    alt = { { 1, 65, "Smelt Copper", 0, "inv_ingot_02", 130, { { 130, "Minerai de cuivre", 2770, "inv_ore_copper_01", 0 } }, "" }, { 65, 75, "Smelt Tin", 0, "inv_ingot_05", 60, { { 60, "Minerai d'étain", 2771, "inv_ore_tin_01", 0 } }, "" }, { 75, 100, "Smelt Bronze", 0, "inv_ingot_bronze", 60, { { 60, "Barre de cuivre", 2840, "inv_ingot_02", 0 }, { 60, "Barre d'étain", 3576, "inv_ingot_05", 0 } }, "" }, { 100, 125, "Smelt Silver", 0, "inv_ingot_01", 70, { { 70, "Minerai d'argent", 2775, "inv_stone_16", 0 } }, "" }, { 125, 140, "Smelt Iron", 0, "inv_ingot_iron", 35, { { 35, "Minerai de fer", 2772, "inv_ore_iron_01", 0 } }, "" }, { 140, 155, "Mining seulement : aucune barre ne donne de compétence ici", 0, "trade_mining", 0, {  }, "" }, { 155, 185, "Smelt Gold", 0, "inv_ingot_03", 60, { { 60, "Minerai d'or", 2776, "inv_ore_gold_01", 0 } }, "" } },
    forever = { "Lodestone (Minage 20) : objet de camp avec jusqu'à 90 d'Attack Power en mêlée, comme Blessing of Might (camping wowforever.be ; Warcraft Tavern est d'accord).", "Rock Garden (140, plan) et Molten Foundry (300, plan) : camp Niveau 2 et 3. Le Rock Garden fait apparaître du minerai commun au fil du temps ; la Molten Foundry est nécessaire pour les fontes hautes (wowforever.be).", "Perk Legacy Made of Metal : PV totaux +5 % et plus de minerai des nœuds (hub wowforever.be, images BlizzCon : chiffres non définitifs) .", "Nouveaux minerais de fin de jeu : Minerai de thorium lourd, Barre de Légionite, Barre d'azérothium (fonte à 275, formateur) (wowforever.be).", "Matériaux rares : parfois le minage donne Pyrite, Bauxite ou Pitchblende (wowforever.be)." }, camp = "Lodestone (Minage 20) : Attack Power de mêlée jusqu'à 90 pour ceux qui sont assis à proximité. Niveau 2 Rock Garden (140), niveau 3 Molten Foundry (300).", gold = "Vendez le minerai brut à l'Hôtel des ventes : minerais et barres sont utilisés par les Forgerons, Ingénieurs, Enchanteurs et Couturiers (wowforever.be). Prix de vente : non trouvés dans les sources lues. Les barres de fin de jeu (Légionite, thorium lourd, azérothium) n'ont pas de prix vérifiés.", tips = { "Fondez jusqu'à 185, puis minez : après 185, la fonte ne donne plus de compétence (wowforever.be).", "Ne faites pas de détour pour l'étain après 165 ni pour l'argent après 175 : ils ne donnent plus de compétence.", "Le chemin 225–300 n'est pas encore documenté : vérifiez en jeu." } },
   ["Herbalism"] = { icon = "trade_herbalism", type = "gathering", altTitle = "", how = {  },
    route = { { 1, 70, "Peacebloom, Silverleaf, Earthroot (dès 15)", 0, "inv_misc_herb_07", 0, {  }, "N’importe quelle zone de départ" }, { 70, 115, "Mageroyal, Eglantine, Stranglekelp", 0, "inv_misc_herb_11", 0, {  }, "Sombrivage, Loch Modan, Forêt des Pins argentés" }, { 115, 170, "Stranglekelp, Bruiseweed, Aciérite sauvage, Kingsblood (dès 125), Liferoot (dès 150)", 0, "inv_misc_root_02", 0, {  }, "Contreforts d'Hillsbrad, Les Paluns, Les Serres-Rocheuses" }, { 170, 205, "Kingsblood, Liferoot, Fadeleaf, Goldthorn, Moustache de Khadgar (dès 185)", 0, "inv_misc_herb_08", 0, {  }, "Vallée de Strangleronce, Hautes-terres d'Arathi" }, { 205, 225, "Fadeleaf, Goldthorn, Moustache de Khadgar, Wintersbite, Firebloom, Lotus pourpre", 0, "inv_misc_herb_17", 0, {  }, "Montagnes d'Alterac, Tanaris, Gorge des Vents brûlants" }, { 225, 270, "Lotus pourpre, Firebloom, Sungrass (dès 230), Champignon fantôme (dès 245), Gromsblood (dès 250), Sansam doré (dès 260)", 0, "inv_misc_herb_sansamroot", 0, {  }, "Les Hinterlands, Tanaris, Gorge des Vents brûlants" }, { 270, 300, "Sansam doré, Dreamfoil, Sauge-argent des montagnes (dès 280), Plaguebloom (dès 285), Icecap (dès 290)", 0, "inv_misc_herb_icecap", 0, {  }, "Gangrebois, Cratère d'Un'Goro, Berceau-de-l'Hiver, Maleterres de l'est et de l'ouest" } },
    alt = {  },
    forever = { "Thé de dorépine : +15 Herboristerie pendant un moment, nouveau dans Forever (wowforever.be).", "Serre (140) et Seed Hybridizer (300) : camp niveau 2 fait pousser les herbes à partir de graines, niveau 3 multiplie les graines ou en crée de plus rares (camping wowforever.be).", "Graines d'herbe : Graines de plantes communes, peu courantes, inhabituelles, rares ; matériaux rares Lichen à volants, Rosecap, Stranglevine (wowforever.be).", "Nouvelles herbes de fin de jeu : Marefoil, Demonsage, Death Lotus (wowforever.be ; lieu et compétence inconnus).", "Cultivation des Tauren : duplique maintenant une herbe proche au lieu d'un bonus fixe (wowforever.be).", "Perk de métier Natural Talent : plus de résistance aux écoles de magie, chance accrue de lotus rare et plus d'herbes par nœud (hub wowforever.be ; chiffres non définitifs) ." }, camp = "Incense Candle (Herboristerie 20, voir common.json). Niveau 2 Serre (140) fait pousser les herbes à partir de graines. Niveau 3 Seed Hybridizer (300) multiplie les graines.", gold = "Vendez les herbes brutes à l'Hôtel des ventes. WT : les herbes communes baissent vite de prix, les rares (ex. Lotus noir) valent plus. Prix précis : non trouvés. L'Alchimie est le principal consommateur d'herbes (WT, wowforever.be).", tips = { "Pas d'outil requis : activez Find Herbs pour voir les herbes sur la minicarte (FAQ wowforever.be).", "Les herbes donnent parfois aussi des graines : ne les jetez pas, les niveaux du camp les utilisent (wowforever.be).", "La Cultivation des Tauren demande un niveau minimum depuis le 27 sept. (wowforever.be)." } },
   ["Alchemy"] = { icon = "trade_alchemy", type = "crafting", altTitle = "", how = {  },
