    forever = { "Broderie : bonus pour les tailleurs sur l'équipement en tissu (hub wowforever.be).", "Plus de tissu des humanoïdes et ensembles de tissu nouveaux et retravaillés (hub wowforever.be).", "180 nouvelles recettes sur 439 au total (wowforever.be Couture).", "Sac de réactifs en lin à 6 emplacements fabriqué par la Couture (WT)." }, camp = "Faction Banner (20) : Spirit jusqu'à 32 (dans common.json). Niveau 2 Spinning Wheel (140) : 2 Bois simple, 5 Rouleaux d'étoffe de soie, 3 Bobines de fil raffiné. Niveau 3 Loom (300) : station pour les patrons.", gold = "Du tissu de la progression pour les enchanteurs. Prix : non trouvés. Le Sac de réactifs en lin et les sacs sont des coûts de sac, pas d'or.", tips = { "Couture + Enchantement pour le Prêtre, le Mage, le Démoniste (Gfinity : ).", "Pour le Mage et le Démoniste, Herboristerie + Alchimie est le binôme de fin de jeu (Gfinity)." } },
   ["Cooking"] = { icon = "inv_misc_food_15", type = "secondary", altTitle = "", how = { Expert = "le livre Livre de cuisine pour expert (10 pièces d’or)", Artisan = "la quête Surprise de palourdes (dès le niveau 35)" },
