    alt = {  },
    forever = { "Presque toute la nourriture : +5 % d'XP des kills pendant que vous êtes Well Fed (wowforever.be Cuisine, WT).", "Bâton à touiller de Macaron (Mortemines) : cuisine 25 % plus vite (wowforever.be).", "Nouvelles recettes : Poisson cuirassé, Savory Whimsyfin Delight, Pain de saumon et Saumon solécaille poché amélioré (wowforever.be).", "La Cuisine allume le feu à chaque camp (camping wowforever.be)." }, camp = "Basic Campfire (Cuisine 1, formateur) : 3 objets. Journeyman Campfire (plan Cuisine 90, butin des Mortemines et des Cavernes des lamentations) : 5 objets. Expert Campfire (plan Cuisine 200) : 10 objets. Niveau 2 Cookie's Feast (140) : nourriture avec buff de Stamina. Niveau 3 Iron Oven (300).", gold = "Le poisson est la voie la plus simple : recettes bon marché, poisson brut pas cher à l'Hôtel des ventes (wowforever.be). Chiffres de vente de nourriture : non trouvés.", tips = { "Pour l'Artisan : Chair de palourde piquante de la Palourde à large bouche (côte est de Tanaris) et Oeuf géant des mobs Sandfury (wowforever.be).", "La Cuisine et la Pêche sont recommandées à tous ; elles ne prennent pas de place de métier principal (WT)." } },
   ["First Aid"] = { icon = "inv_misc_bandage_01", type = "secondary", altTitle = "", how = { Expert = "le livre Expert en premiers soins - Sous les pansements", Artisan = "la quête Triage (dès le niveau 35)" },
