    alt = {  },
    forever = { "Crée des potions de soin, déplacées de l'Alchimie (wowforever.be Secourisme, WT). Elles fonctionnent en combat : utile aussi pour les soigneurs.", "Remèdes contre le poison, les maladies et le saignement (nouveaux pour les maladies et le saignement, non utilisables en combat) (wowforever.be).", "Toxin Study (140) et Plague Doctor's Laboratory (300) : camp niveau 2 et 3 pour les potions et cataplasmes (camping wowforever.be)." }, camp = "First Aid Kit (Stamina jusqu'à 56, dans common.json). Niveau 2 Toxin Study (140). Niveau 3 Plague Doctor's Laboratory (300).", gold = "Potions de soin utilisées à répétition en combat : demande constante. Prix : non trouvés.", tips = { "Secondaire : il ne prend pas un des deux emplacements principaux, et tout le monde peut l'avoir (WT).", "Le livre Expert First Aid est aussi à l'Hôtel des ventes (wowforever.be)." } },
   ["Fishing"] = { icon = "trade_fishing", type = "secondary", altTitle = "", how = { Expert = "le livre Expert pêcheur - Vous et la perche, de Vieil Heming à Booty Bay", Artisan = "la quête Nat Pagle, pêcheur de l'extrême (dès le niveau 35)" },
    route = { { 1, 75, "Pêche", 0, "trade_fishing", 0, {  }, "N’importe quelle zone de départ. En dessous de 25 de compétence, utilisez une Verroterie brillante" }, { 75, 150, "Pêche", 0, "trade_fishing", 0, {  }, "Une capitale : Stormwind, Ironforge ou Darnassus (Alliance) ; Orgrimmar, Thunder Bluff ou Undercity (Horde)" }, { 150, 225, "Pêche", 0, "trade_fishing", 0, {  }, "Marécage d'Âprefange (plus facile pour l’Alliance) ou Vallée de Strangleronce (plus facile pour la Horde) ; utilisez des leurres" }, { 225, 300, "Pêche", 0, "trade_fishing", 0, {  }, "Pas encore dans le guide : les zones où vous pouvez pêcher dès 205 sont Azshara, Féralas, Les Hinterlands, Tanaris, Cratère d’Un’Goro" } },
    alt = {  },
    forever = { "Râtelier de pêche (140) et Fishing Hut (300) : camp niveau 2 et 3 pour les appâts et les poissons peu courants et rares (camping wowforever.be).", "Nourriture à base de poisson plus forte : Pain de saumon, Saumon solécaille poché, Poisson cuirassé (wowforever.be Pêche).", "Legacy Luremaster : +25 % de chance d'un poisson supplémentaire avec un appât actif (WT, wowforever.be) ." }, camp = "Fish Bowl (8 % à toutes les stats, dans common.json). Niveau 2 Râtelier de pêche (140) : appâts et poissons peu courants. Niveau 3 Fishing Hut (300) : appâts et poissons rares.", gold = "Poisson brut vendu à l'Hôtel des ventes ou utilisé pour la Cuisine (wowforever.be). Chiffres : non trouvés.", tips = { "Les chamans atteignent plus facilement les bassins de pêche avec Far Sight et Water Walking ; les chasseurs donnent du poisson brut à leur familier (wowforever.be).", "Cuisine + Pêche pour tous : +5 % d'XP grâce à la nourriture (WT)." } },
  } },
}
